def _normalize_text(value: Any, default: str = "", max_length: int = 2000) -> str:
    if value is None:
        return default
    text = re.sub(r"\s+", " ", str(value)).strip()
    if not text:
        return default
    return text[:max_length]


FULL_PAPER_TEXT_STATE_MAX_CHARS = 160000


def _normalize_paper_text(value: Any, default: str = "", max_length: int = FULL_PAPER_TEXT_STATE_MAX_CHARS) -> str:
    if value is None:
        return default
    text = str(value).replace("\r\n", "\n").replace("\r", "\n")
    text = re.sub(r"[ \t\f\v]+", " ", text)
    text = re.sub(r"\n[ \t]+", "\n", text)
    text = re.sub(r"\n{4,}", "\n\n\n", text)
    text = text.strip()
    if not text:
        return default
    return text[:max_length]


def _normalize_conflict_note_text(value: Any, max_length: int = 140) -> str:
    text = str(value or "")
    text = text.replace("<think>", " ").replace("</think>", " ")
    text = text.replace("<json>", " ").replace("</json>", " ")
    text = re.sub(r"\s+", " ", text).strip()
    if not text:
        return ""
    if len(text) <= max_length:
        return text
    return text[: max(0, max_length - 3)].rstrip() + "..."


