_MISSING_ABLATION_TARGET_PAPER_NAME_RE = re.compile(
    r"\b[A-Z]{2,}[A-Za-z0-9_-]*\b|\b[A-Za-z]+[-/][A-Za-z0-9_-]+\b|"
    r"\b[A-Za-z]_[A-Za-z0-9_]+\b|\d"
)


def _missing_ablation_bundle_context_text(bundle: Dict[str, Any]) -> str:
    if not isinstance(bundle, dict):
        return ""
    parts: List[str] = [str(bundle.get("reviewer_negative_candidate") or "")]
    anchor = bundle.get("claim_anchor") if isinstance(bundle.get("claim_anchor"), dict) else {}
    parts.append(str(anchor.get("quote") or ""))
    obligation = bundle.get("claim_obligation") if isinstance(bundle.get("claim_obligation"), dict) else {}
    parts.append(str(obligation.get("expected_entity") or ""))
    missing = bundle.get("missing_or_mismatch") if isinstance(bundle.get("missing_or_mismatch"), dict) else {}
    if missing:
        parts.append(str(missing.get("entity") or ""))
        parts.extend(str(item or "") for item in missing.get("items") or [])
    for item in bundle.get("observed_inventory") or []:
        if isinstance(item, dict):
            parts.append(str(item.get("quote") or ""))
            parts.append(str(item.get("locator") or ""))
            parts.extend(str(part or "") for part in item.get("observed_items") or [])
    return " ".join(part for part in parts if part)


def _missing_ablation_target_is_malformed_fragment(target: str) -> bool:
    lowered = str(target or "").strip().lower()
    if not lowered:
        return False
    if re.match(r"^\d+(?:\.\d+)*\s+[a-z]", lowered):
        return True
    if re.search(r"\b(?:seems?\s+similar|similar\s+to\s+the|methodology\s+involves|design\s+of\s+gradient)\b", lowered):
        return True
    if re.search(r"\b(?:recent\s+advances?|prior\s+work|related\s+work|existing\s+work)\s+(?:in|on|for)\b", lowered):
        return True
    if re.match(r"^(?:via|through)\s+(?:aggregation|aggregat(?:e|ion|ing))\b", lowered):
        return True
    if re.match(r"^(?:it\s+)?only\s+comprises?\b", lowered):
        return True
    if re.match(r"^(?:that|which|where|when|whether)\b", lowered):
        return True
    if re.match(r"^(?:examine|examines|examining|investigate|investigates|stud(?:y|ies|ying)|analy[sz]e|analy[sz]es)\b", lowered):
        return True
    if re.match(r"^(?:ensure|ensures|ensuring)\b", lowered):
        return True
    if re.match(r"^(?:from|in|on|for)\s+\S+", lowered) and re.search(
        r"\b(?:improves?|improving|results?|resulting|allows?|allowing|enables?|enabling|"
        r"ensures?|ensuring|learned|representation)\b",
        lowered,
    ):
        return True
    if re.fullmatch(r"(?:[a-z]{0,4}ional|[a-z]{0,4}al)\s+(?:branch|module|component|head)", lowered):
        return True
    if re.match(r"^(?:by|from|with|to)\s+(?:its|their|the|a|an|our)\b", lowered):
        return True
    if re.match(r"^[a-z]\s+(?:the|a|an)\s+", lowered):
        return True
    if re.search(r"\bby\s+(?:encoder|decoder|network|model|module|component)\b$", lowered):
        return True
    if re.match(r"^(?:with|using)\s+(?:greater|more|less|better|worse)\s+", lowered):
        return True
    if re.search(r"\bwe\s+(?:expect|show|use|propose|train|optimi[sz]e)\b", lowered):
        return True
    if re.search(r"\b(?:function|method|model|framework)\s+(?:generates?|predicts?|outputs?|uses?)\b", lowered):
        return True
    if re.search(r"\b(?:and|or)\s+(?:network|model|module|component|architecture)\b", lowered) and re.search(
        r"[$\\{}]|(?:^|\s)[a-z]\$",
        lowered,
    ):
        return True
    if re.search(r"(?:^|\s)(?:and|or)\s+(?:network|model|module|component|architecture)$", lowered):
        return True
    if re.fullmatch(r"[a-z]\$?\s+(?:and|or)\s+(?:network|model|module|component|architecture)", lowered):
        return True
    if re.fullmatch(r"ranch[_ -]?(?:encoder|decoder|branch|module|component|head)", lowered):
        return True
    return False


def _missing_ablation_bundle_targets_ogl_family(bundle: Dict[str, Any]) -> bool:
    context = _missing_ablation_bundle_context_text(bundle)
    lowered = context.lower()
    target = _review_issue_primary_missing_text(bundle, neg_type="missing_ablation").lower()
    if re.search(
        r"\borthogonal\s+gradient(?:\s+learning)?\b|\bogl\b|"
        r"\borthogonal\s+direction(?:\s+to)?\s+the\s+gradient\b|"
        r"\borthogonality\s+constraint\b",
        target,
    ):
        return True
    if re.search(r"\b(?:base\s+vectors?|pre[- ]constructed|gradient\s+space|gradient\s+vectors?)\b", target) and re.search(
        r"\b(?:orthogonal\s+gradient|ogl|orthogonal\s+direction|supernet\s+training)\b",
        lowered,
    ):
        return True
    return False


def _paper_has_ogl_ablation_or_comparison(text: str) -> bool:
    value = str(text or "")
    if not value or not re.search(r"\b(?:OGL|orthogonal\s+gradient\s+learning)\b", value, re.IGNORECASE):
        return False
    if re.search(r"\b(?:with\s+or\s+without|with/without|without|w/o)\s+OGL\b", value, re.IGNORECASE):
        return True
    if re.search(r"\bmethods?\s+with\s+or\s+without\s+OGL\b", value, re.IGNORECASE):
        return True
    if re.search(
        r"\b(?:RandomNAS|GDAS)\s*[- ]?\s*OGL\b.{0,180}\b(?:RandomNAS|GDAS)\b|"
        r"\b(?:RandomNAS|GDAS)\b.{0,180}\b(?:RandomNAS|GDAS)\s*[- ]?\s*OGL\b",
        value,
        re.IGNORECASE | re.DOTALL,
    ):
        return True
    if re.search(
        r"\b(?:Table|Fig(?:ure)?\.?)\b.{0,120}\b(?:OGL|RandomNAS\s*[- ]?\s*OGL|GDAS\s*[- ]?\s*OGL)\b"
        r".{0,220}\b(?:comparison|compare|ranking|validation|accuracy|results?)\b",
        value,
        re.IGNORECASE | re.DOTALL,
    ):
        return True
    return False


def _missing_ablation_target_quality(bundle: Dict[str, Any]) -> Dict[str, str]:
    """Classify whether a missing-ablation target is review-worthy.

    This is stricter than generic specificity: "decoder" is concrete text, but
    not a defensible verified review issue unless the paper frames a named,
    contribution-bearing decoder mechanism.  Quantity is preserved by allowing
    medium-confidence paper-specific mechanisms while rejecting architecture
    placeholders and action fragments.
    """

    missing = bundle.get("missing_or_mismatch") if isinstance(bundle, dict) else {}
    raw_items = []
    if isinstance(missing, dict):
        raw_items = [
            str(item or "").strip()
            for item in (missing.get("items") or [missing.get("entity")])
            if str(item or "").strip()
        ]
    raw = raw_items[0] if raw_items else ""
    target = _missing_ablation_target_text(raw)
    target = re.sub(r"^of\s+(?:an?\s+|the\s+)?", "", target, flags=re.IGNORECASE).strip()
    target = re.sub(r"^training\s+of\s+(?:an?\s+|the\s+)?", "", target, flags=re.IGNORECASE).strip()
    target = re.sub(r"^(?:train|training)\s+(?:an?\s+|the\s+)?", "", target, flags=re.IGNORECASE).strip()
    target = re.sub(r"^(?:with|using)\s+(?:an?\s+|the\s+)?", "", target, flags=re.IGNORECASE).strip()
    target = re.sub(r"^(?:with|using)\s+", "", target, flags=re.IGNORECASE).strip()
    target = re.sub(r"\s+", " ", target).strip(" ,.;:")
    lowered = target.lower()
    target_core = re.sub(
        r"\s+(?:module|component|mechanism|network|model|architecture|framework)$",
        "",
        lowered,
        flags=re.IGNORECASE,
    ).strip()
    context = _missing_ablation_bundle_context_text(bundle)
    target_context = f"{target} {context}"
    if lowered in {"recurrent neural network", "rnn"} and re.search(
        r"\b(?:draft\s+model|redrafter|speculative\s+decoding)\b",
        context,
        re.IGNORECASE,
    ):
        target = "recurrent draft model"
        lowered = target.lower()
        target_core = lowered
        target_context = f"{target} {context}"

    if not target:
        return {"quality": "reject", "reason": "missing_ablation_target_empty"}
    if lowered in {"long-term", "short-term", "pre-training", "pretraining"}:
        return {"quality": "reject", "reason": "missing_ablation_target_generic_component"}
    if _MISSING_ABLATION_TARGET_WEAK_ACTION_RE.search(target.lower()):
        return {"quality": "reject", "reason": "missing_ablation_target_weak_action"}
    if re.fullmatch(
        r"(?:analy[sz]e|analysis\s+of|investigate|study|examine)\s+(?:the\s+)?(?:mechanism|effect|impact)",
        lowered,
    ):
        return {"quality": "reject", "reason": "missing_ablation_target_weak_action"}
    if _missing_ablation_target_is_malformed_fragment(target):
        return {"quality": "reject", "reason": "missing_ablation_target_malformed_fragment"}
    if re.search(r"\b(?:seems?\s+similar|methodology\s+involves|design\s+of\s+gradient)\b", lowered):
        return {"quality": "reject", "reason": "missing_ablation_target_malformed_fragment"}
    if re.search(r"\b(?:only\s+comprises?|via\s+aggregation|aggregation\s+of\s+local\s+network)\b", lowered):
        return {"quality": "reject", "reason": "missing_ablation_target_prose_fragment"}
    if re.search(
        r"\b(?:data\s+with\s+the\s+latest\s+network|aspects?\s+(?:of\s+)?(?:the\s+)?causal\s+mechanism|"
        r"domain\s+(?:of\s+)?causal\s+representation|ranch\s+encoder|significantly\s+module)\b",
        lowered,
    ):
        return {"quality": "reject", "reason": "missing_ablation_target_malformed_or_abstract"}
    if re.match(r"^(?:in|of|for)\s+(?:the\s+)?causal\s+representation\b", lowered):
        return {"quality": "reject", "reason": "missing_ablation_target_malformed_or_abstract"}
    if re.search(r"\bglide\b", lowered) and re.search(
        r"\b(?:docking|target\s+pockets?|schrodinger|software\s+package|rocs|evaluate|evaluation)\b",
        context,
        re.IGNORECASE,
    ):
        return {"quality": "reject", "reason": "missing_ablation_target_evaluation_tool"}
    if re.search(r"\bpockets?\s+with\s+(?:the\s+)?[a-z0-9_-]+\s+module\b", lowered):
        return {"quality": "reject", "reason": "missing_ablation_target_evaluation_tool"}
    if re.match(r"^including\s+", lowered):
        return {"quality": "reject", "reason": "missing_ablation_target_prose_fragment"}
    if re.fullmatch(r"performance\s+of\s+(?:the\s+)?(?:neural\s+)?network", lowered):
        return {"quality": "reject", "reason": "missing_ablation_target_generic_component"}
    if re.fullmatch(
        r"(?:develop|build|train|design|construct)\s+(?:a|an|the)\s+"
        r"(?:graph\s+)?(?:neural\s+)?network",
        lowered,
    ):
        return {"quality": "reject", "reason": "missing_ablation_target_weak_action"}
    if re.fullmatch(
        r"(?:first\s+)?(?:practical\s+|novel\s+|new\s+)?(?:graph\s+)?(?:neural\s+)?network",
        lowered,
    ):
        return {"quality": "reject", "reason": "missing_ablation_target_generic_component"}
    if re.fullmatch(r"(?:[a-z0-9_-]+\s+)?transformer[- ]based\s+network", lowered):
        return {"quality": "reject", "reason": "missing_ablation_target_generic_component"}
    if re.search(r"\blora\b", lowered):
        context_l = context.lower()
        if not re.search(r"\b(?:proposed|novel|our|new|contribution|core|main)\b.{0,80}\blora\b", context_l):
            return {"quality": "reject", "reason": "missing_ablation_target_standard_tool"}
    if re.search(r"\bcarefully\s+initiali[sz]e\b", lowered):
        return {"quality": "reject", "reason": "missing_ablation_target_weak_action"}
    if re.fullmatch(r"(?:[a-z]{0,4}ional|[a-z]{0,4}al)\s+(?:branch|module|component|head)", lowered):
        return {"quality": "reject", "reason": "missing_ablation_target_malformed_fragment"}
    if re.search(
        r"\b(?:stochastic\s+gradient|gradient\s+descent|cross[- ]entropy\s+(?:for\s+)?(?:classification\s+)?loss|"
        r"classification\s+loss|ce\s+loss)\b",
        lowered,
    ) and not re.search(
        r"\b(?:orthogonal|ogl|gradient\s+matching|distillation|novel|proposed|custom|contrastive|regulari[sz]ation)\b",
        f"{lowered} {context.lower()}",
    ):
        return {"quality": "reject", "reason": "missing_ablation_target_not_contribution_bound"}
    if re.search(r"\bgradients?\b", lowered) and not re.search(
        r"\b(?:orthogonal|ogl|matching|distillation|local[- ]global|federated\s+gradient\s+matching)\b",
        lowered,
    ):
        return {"quality": "reject", "reason": "missing_ablation_target_not_contribution_bound"}
    if re.fullmatch(r"(?:greater|more|less|better|worse)\s+(?:encoder|decoder|network|model|module|component)", lowered):
        return {"quality": "reject", "reason": "missing_ablation_target_generic_component"}
    if re.fullmatch(
        r"(?:encoder|decoder|network|neural\s+network|deep\s+neural\s+network|"
        r"convolutional\s+network|transformer|model|module|component|fusion|alignment|gradient)",
        lowered,
    ):
        return {"quality": "reject", "reason": "missing_ablation_target_generic_component"}
    if re.fullmatch(r"(?:federated\s+)?gradient", lowered) and not re.search(
        r"\b(?:orthogonal|ogl|matching|learning)\b",
        lowered,
    ):
        return {"quality": "reject", "reason": "missing_ablation_target_not_contribution_bound"}
    if re.match(r"^(?:section|table|figure|fig\.?|appendix|algorithm)\b", lowered) or (
        len(lowered.split()) >= 4
        and re.search(r"\b(?:describes?|states?|reports?|shows?|presents?|introduces?|contains?|uses?|used)\b", lowered)
    ):
        return {"quality": "reject", "reason": "missing_ablation_target_prose_fragment"}
    if len(lowered.split()) >= 3 and re.search(
        r"\b(?:generates?|predicts?|outputs?|updates?|updated|expects?|devises?|devised)\b",
        lowered,
    ):
        return {"quality": "reject", "reason": "missing_ablation_target_weak_action"}
    if re.fullmatch(
        r"(?:analy[sz]e|analysis\s+of|investigate|study|examine)\s+(?:the\s+)?(?:mechanism|effect|impact)",
        lowered,
    ):
        return {"quality": "reject", "reason": "missing_ablation_target_weak_action"}
    if re.fullmatch(r"(?:t?he\s+)?following\s+empirical\s+loss|empirical\s+loss", lowered):
        return {"quality": "reject", "reason": "missing_ablation_target_prose_fragment"}
    if _MISSING_ABLATION_TARGET_GENERIC_COMPONENT_RE.fullmatch(lowered) or _MISSING_ABLATION_TARGET_GENERIC_COMPONENT_RE.fullmatch(target_core):
        if not (
            _MISSING_ABLATION_TARGET_STRONG_SIGNAL_RE.search(target_context)
            and _MISSING_ABLATION_TARGET_CONTEXT_SIGNAL_RE.search(context)
            and not re.fullmatch(r"(?:encoder|decoder|network|convolutional\s+network|transformer|model|module|component)", target_core or lowered)
        ):
            return {"quality": "reject", "reason": "missing_ablation_target_generic_component"}
    if re.fullmatch(r"(?:component[- ]isolation\s+)?ablation\s+for\s+(?:encoder|decoder|network|transformer|model|module|component)", str(raw or ""), re.IGNORECASE):
        return {"quality": "reject", "reason": "missing_ablation_target_generic_component"}
    if lowered in {"predicts a textual representation", "predict a textual representation", "trained with full-batch gradient", "full-batch gradient"}:
        return {"quality": "reject", "reason": "missing_ablation_target_weak_action"}
    if re.search(r"\bhas\s+been\s+stud(?:ied|y)\b", lowered) or re.search(
        r"\beffect\s+of\b.{0,80}\bhas\s+been\s+stud(?:ied|y)\b",
        lowered,
    ):
        return {"quality": "reject", "reason": "missing_ablation_target_already_studied_phrase"}
    if re.search(r"\bframe[- ]by[- ]frame\s+module\b", lowered) and re.search(
        r"\b(?:contrast(?:ing|s|ed)?\s+with|rather\s+than|instead\s+of)\s+frame[- ]by[- ]frame\b",
        context.lower(),
    ):
        return {"quality": "reject", "reason": "missing_ablation_target_contrast_baseline_as_module"}
    if re.search(r"\b(?:simulated\s+)?loss\b", lowered):
        context_l = context.lower()
        theory_context = re.search(
            r"\b(?:learning\s+dynamics|global\s+minimum|global\s+minima|expressivity|"
            r"symmetric\s+datasets?|two[- ]layer|bias[- ]free|relu|theorem|proof|"
            r"convergence|optimization\s+landscape)\b",
            context_l,
        )
        empirical_driver = re.search(
            r"\b(?:benchmark|experiment|experimental|table|accuracy|mAP|mIoU|"
            r"f1|auc|outperform|improv(?:e|es|ed|ement)|performance\s+gain|sota|"
            r"state[- ]of[- ]the[- ]art)\b",
            context_l,
        )
        if theory_context and not empirical_driver:
            return {"quality": "reject", "reason": "missing_ablation_target_theory_loss_analysis"}
    if _MISSING_ABLATION_TARGET_STRONG_SIGNAL_RE.search(target_context):
        named_signal = bool(
            _MISSING_ABLATION_TARGET_PAPER_NAME_RE.search(target)
            or re.search(r"\b(?:head|predictor|loss|objective|regulari[sz]ation|gradient|attention|fusion|alignment|distillation)\b", lowered)
        )
        return {
            "quality": "high" if named_signal and _MISSING_ABLATION_TARGET_CONTEXT_SIGNAL_RE.search(context) else "medium",
            "reason": "missing_ablation_target_named_or_mechanistic",
        }
    if _MISSING_ABLATION_TARGET_PAPER_NAME_RE.search(target):
        return {"quality": "medium", "reason": "missing_ablation_target_paper_specific_name"}
    return {"quality": "low", "reason": "missing_ablation_target_low_confidence"}


def _review_issue_primary_missing_text(bundle: Dict[str, Any], *, neg_type: str = "") -> str:
    missing = bundle.get("missing_or_mismatch") if isinstance(bundle, dict) else {}
    raw_items: List[str] = []
    if isinstance(missing, dict):
        raw_items = [
            str(item or "").strip()
            for item in (missing.get("items") or [missing.get("entity")])
            if str(item or "").strip()
        ]
    raw = raw_items[0] if raw_items else ""
    if _canonical_negative_evidence_type(neg_type) == "missing_ablation":
        raw = _missing_ablation_target_text(raw)
    return re.sub(r"\s+", " ", raw).strip(" ,.;:")


def _review_issue_slot_for_type(issue_type: str) -> str:
    issue_type = _canonical_negative_evidence_type(issue_type)
    if issue_type in {"missing_baseline", "unfair_or_weak_baseline"}:
        return "missing_baseline"
    if issue_type == "missing_ablation":
        return "missing_ablation"
    if issue_type in {"missing_robustness_or_generalization", "scope_overclaim", "insufficient_evaluation"}:
        return "scope_or_robustness"
    if issue_type in {"evaluation_protocol_risk", "reproducibility_gap", "method_support_gap"}:
        return "protocol_or_reproducibility"
    if issue_type == "efficiency_cost_gap":
        return "efficiency_cost"
    if issue_type in {"result_claim_mismatch", "negative_result"}:
        return "result_claim_mismatch"
    return issue_type or "unknown"


def _review_issue_inventory_anchor_type(items: Sequence[Dict[str, Any]]) -> str:
    inventory_types: List[str] = []
    sources: List[str] = []
    for item in items or []:
        if not isinstance(item, dict):
            continue
        inventory_type = str(item.get("inventory_type") or "").strip()
        source = str(item.get("inventory_source") or item.get("support_bucket") or "").strip()
        if inventory_type and inventory_type not in inventory_types:
            inventory_types.append(inventory_type)
        if source and source not in sources:
            sources.append(source)
    if inventory_types:
        return ",".join(inventory_types[:3])
    if sources:
        return ",".join(sources[:3])
    return ""


def _review_issue_normalized_cluster_target(bundle: Dict[str, Any], neg_type: str) -> str:
    """Stable target family for paper-facing issue cluster counts."""

    neg_type = _canonical_negative_evidence_type(neg_type)
    target = _review_issue_primary_missing_text(bundle, neg_type=neg_type)
    target = re.sub(
        r"^(?:of\s+the|of|with\s+(?:an?\s+|the\s+)?|using\s+(?:an?\s+|the\s+)?|"
        r"train(?:ing)?\s+(?:an?\s+|the\s+)?)",
        "",
        target,
        flags=re.IGNORECASE,
    ).strip()
    target = re.sub(r"\bmodule\s+module\b", "module", target, flags=re.IGNORECASE)
    lowered = target.lower()

    if neg_type == "missing_ablation":
        context_l = _missing_ablation_bundle_context_text(bundle).lower() if isinstance(bundle, dict) else ""
        if (
            re.search(r"\bacceptance\s+prediction\s+head\b", lowered)
            or (
                re.search(r"\bprediction\s+head\b|\bbias(?:es)?\b|\bweighted\s+(?:bce|binary\s+cross[- ]entropy)\s+loss\b", lowered)
                and re.search(
                    r"\b(?:acceptance\s+prediction\s+head|token\s+acceptance|candidate\s+length|draft\s+model|specdec)\b",
                    context_l,
                )
            )
        ):
            return "acceptance_prediction_head"
        if isinstance(bundle, dict) and _missing_ablation_bundle_targets_ogl_family(bundle):
            return "orthogonal_gradient_learning"
        if re.search(
            r"\borthogonal\s+gradient(?:\s+learning)?\b|\bogl\b|"
            r"\borthogonal\s+direction(?:\s+to)?\s+the\s+gradient\b|"
            r"\borthogonality\s+constraint\b",
            lowered,
        ):
            return "orthogonal_gradient_learning"
        if re.search(r"\bgeneralized\s+noise\s+regulari[sz]ation\b|\bnoise\s+regulari[sz]ation\b|\bnr-dcca\b", lowered):
            return "generalized_noise_regularization"
        if re.search(r"\brecurrent\s+drafter\b|\brecurrent\s+neural\s+network\b|\brnn\b", lowered):
            return "recurrent_draft_model"
        if re.search(r"\blocal\s+virtual\s+data\b", lowered):
            return "local_virtual_data_regularization"
        if re.search(r"\bfederated\s+gradient(?:\s+matching)?\b", lowered):
            return "federated_gradient_matching"
        if re.search(r"\bdistributed\s+gradient\b", lowered):
            return "distributed_gradient"
        if re.search(r"\blong[- ]term\s+model(?:ing|ling)?\b|\blt-ms\b", lowered):
            return "long_term_modeling"

    if neg_type in {"missing_baseline", "unfair_or_weak_baseline"} and re.search(r"\bequalal\b", lowered):
        return "equalal_baseline"
    if neg_type in {"missing_robustness_or_generalization", "scope_overclaim"} and re.search(
        r"\bgraph[- ]level\b|\bgraph\s+classification\b", lowered
    ):
        return "graph_classification_coverage"
    if neg_type == "efficiency_cost_gap":
        return "efficiency_resource_measurement"
    if neg_type == "reproducibility_gap":
        if re.search(r"\bhyperparameter|implementation|code|config|split|seed\b", lowered):
            return "implementation_reproducibility_details"

    tokens = [
        token.lower()
        for token in re.findall(r"[A-Za-z][A-Za-z0-9_-]{2,}", target)
        if token.lower()
        not in {
            "ablation",
            "component",
            "isolation",
            "isolating",
            "comparison",
            "same-setting",
            "against",
            "measurement",
            "evaluation",
            "runtime",
            "memory",
            "parameter",
            "hardware",
        }
    ]
    return "_".join(tokens[:8]) or "unspecified_target"


def _review_issue_cluster_signature_for_record(record: Dict[str, Any]) -> Tuple[str, str]:
    neg_type = _negative_evidence_type_for_record(record)
    bundle = record.get("review_issue_bundle") if isinstance(record.get("review_issue_bundle"), dict) else {}
    return (neg_type, _review_issue_normalized_cluster_target(bundle, neg_type))


def _review_issue_cluster_id_for_record(record: Dict[str, Any]) -> str:
    claim_id = str(record.get("claim_id") or "")
    paper_hint = str(record.get("paper_id") or "")
    neg_type, target = _review_issue_cluster_signature_for_record(record)
    return _slugify("review-issue-cluster", f"{paper_hint}-{neg_type}-{target or claim_id}", 0)


def _review_issue_relation_cluster_key_for_record(record: Dict[str, Any]) -> Tuple[str, str, str]:
    if not isinstance(record, dict):
        return ("", "", "")
    bundle = record.get("review_issue_bundle") if isinstance(record.get("review_issue_bundle"), dict) else {}
    if not bundle:
        return ("", "", "")
    source = str(record.get("source") or "").strip()
    review_issue_source = str(record.get("review_issue_source") or bundle.get("review_issue_source") or "").strip()
    if source != ABSENCE_AUDIT_SOURCE and review_issue_source != REVIEW_ISSUE_BUNDLE_SOURCE:
        return ("", "", "")
    claim_id = str(record.get("claim_id") or bundle.get("claim_id") or "").strip()
    neg_type = _canonical_negative_evidence_type(
        record.get("negative_evidence_type")
        or record.get("review_issue_type")
        or bundle.get("negative_evidence_type")
        or bundle.get("review_issue_type")
        or bundle.get("issue_type")
        or bundle.get("negative_type")
    ) or _negative_evidence_type_for_record(record)
    target = _review_issue_normalized_cluster_target(bundle, neg_type)
    if not claim_id or not neg_type or not target or target == "unspecified_target":
        return ("", "", "")
    return (claim_id, neg_type, target)


def _normalize_review_issue_relation_cluster_key(value: Any) -> Tuple[str, str, str]:
    if isinstance(value, dict):
        claim_id = str(value.get("claim_id") or "").strip()
        neg_type = _canonical_negative_evidence_type(
            value.get("issue_type")
            or value.get("negative_evidence_type")
            or value.get("review_issue_type")
            or value.get("negative_type")
        )
        target = _normalize_text(
            value.get("issue_cluster_target")
            or value.get("cluster_target")
            or value.get("target"),
            max_length=180,
        )
        if claim_id and neg_type and target:
            return (claim_id, neg_type, target)
    if isinstance(value, str):
        parts = [part.strip() for part in value.split("|", 2)]
        if len(parts) == 3 and all(parts):
            return (parts[0], _canonical_negative_evidence_type(parts[1]), parts[2])
    return ("", "", "")


def _review_issue_relation_cluster_key_payload(key: Tuple[str, str, str]) -> Dict[str, str]:
    return {
        "claim_id": key[0],
        "issue_type": key[1],
        "issue_cluster_target": key[2],
    }


def _review_issue_observed_inventory_text(bundle: Dict[str, Any]) -> str:
    parts: List[str] = []
    for item in (bundle.get("observed_inventory") or []) if isinstance(bundle, dict) else []:
        if isinstance(item, dict):
            parts.append(str(item.get("quote") or ""))
            parts.append(str(item.get("locator") or ""))
            parts.extend(str(part or "") for part in item.get("observed_items") or [])
    return " ".join(parts)


def _review_issue_bundle_review_worthiness_failure(
    bundle: Dict[str, Any],
    state: Dict[str, Any],
    *,
    neg_type: str,
) -> str:
    """Reject verifier-passing bundles that are not reviewer-worthy issues.

    The bundle verifier checks grounding.  This layer checks whether the
    grounded mismatch is actually a review-worthy defect rather than a template
    demand such as "ablate ordinary distributed gradient".
    """

    neg_type = _canonical_negative_evidence_type(neg_type)
    missing_text = _review_issue_primary_missing_text(bundle, neg_type=neg_type)
    missing_l = missing_text.lower()
    anchor = bundle.get("claim_anchor") if isinstance(bundle.get("claim_anchor"), dict) else {}
    anchor_quote = str(anchor.get("quote") or "")
    anchor_l = anchor_quote.lower()
    inventory_text = _review_issue_observed_inventory_text(bundle)
    inventory_l = inventory_text.lower()

    if neg_type == "missing_ablation":
        cluster_target = _review_issue_normalized_cluster_target(bundle, neg_type)
        target_tokens = _ablation_missing_item_target_tokens(missing_text)
        own_target_context = f"{anchor_l} {inventory_l}"
        if target_tokens and not _window_contains_any_target_marker(own_target_context, target_tokens):
            return "missing_ablation_target_not_claim_or_inventory_bound"
        inventory_has_target = bool(target_tokens and _window_contains_any_target_marker(inventory_l, target_tokens))
        inventory_is_current_ablation_table = bool(
            re.search(
                r"\b(?:table\s*\d+[:.]?\s*)?ablation\s+stud(?:y|ies)\b|"
                r"\b(?:components?|variants?)\s+of\s+(?:our|the)\s+(?:method|model|framework)\b|"
                r"\bour\s+(?:method|model|framework)\b.{0,120}\bablation\b|"
                r"\bablation\b.{0,120}\bour\s+(?:method|model|framework)\b",
                inventory_l,
                re.IGNORECASE,
            )
        )
        if not inventory_has_target and not inventory_is_current_ablation_table:
            return "missing_ablation_inventory_not_target_or_ablation_table_bound"
        if cluster_target == "distributed_gradient":
            return "missing_ablation_target_not_review_worthy_generic_training_mechanism"
        if cluster_target == "long_term_modeling" and re.search(
            r"\bablation\b.{0,140}\b(?:three\s+main\s+components|one\s+component\s+at\s+a\s+time|components\s+of\s+our\s+method)\b",
            inventory_l,
            re.IGNORECASE,
        ):
            return "missing_ablation_target_already_covered_by_component_ablation"
        if cluster_target == "global_encoder" and re.search(
            r"\bablation\s+stud(?:y|ies)\b|"
            r"\beach\s+component\b|"
            r"\b(?:local|global)\s+encoder\b.{0,120}\b(?:contributes?|ablation|component)\b|"
            r"\bcomponents?\s+of\s+(?:our|the)\s+(?:method|model|framework)\b",
            f"{anchor_l} {inventory_l}",
            re.IGNORECASE,
        ):
            return "missing_ablation_target_already_covered_by_component_ablation"
        if re.search(r"\b(?:optimizer|sgd|adam|gradient\s+descent|distributed\s+gradient)\b", missing_l) and not re.search(
            r"\b(?:orthogonal|federated\s+gradient\s+matching|novel|proposed|contribution|key\s+aspect|drives?)\b",
            f"{missing_l} {anchor_l} {inventory_l}",
            re.IGNORECASE,
        ):
            return "missing_ablation_target_not_contribution_bound"

    if neg_type == "reproducibility_gap":
        if re.search(r"\b(?:supplement|supplementary|appendix)\b|\\cref\{supp:|\\ref\{supp:", inventory_l) and re.search(
            r"\b(?:hyperparameters?|implementation|configuration|config|training\s+details?|optimizer|seed|split|code)\b",
            f"{missing_l} {inventory_l}",
            re.IGNORECASE,
        ):
            return "reproducibility_detail_deferred_to_supplement_or_appendix"

    if neg_type == "evaluation_protocol_risk":
        if _review_issue_protocol_missing_item_is_generic(missing_l):
            return "evaluation_protocol_missing_item_too_template_broad"
        if re.search(r"\btrain/?test\s+split,\s*seed,\s*threshold,\s*or\s+same[- ]budget\s+protocol\b", missing_l):
            return "evaluation_protocol_missing_item_too_template_broad"
        if str(bundle.get("discovery_origin") or "") == "deterministic_protocol_seed":
            if not (_CLAIM_REQ_EVALUATION_PROTOCOL_RE.search(anchor_quote) or _PROTOCOL_SEED_EXPLICIT_CUE_RE.search(anchor_quote)):
                return "evaluation_protocol_seed_without_explicit_claim_protocol_obligation"
            if not _review_issue_protocol_seed_missing_item(anchor_quote, ""):
                return "evaluation_protocol_seed_missing_specific_protocol_dimension"

    if neg_type == "efficiency_cost_gap":
        if not _CLAIM_REQ_EFFICIENCY_RE.search(anchor_quote):
            return "efficiency_gap_without_explicit_resource_claim"
        body = str((state or {}).get("paper_text") or "")
        if re.search(r"\b(?:speedup|latency|runtime|throughput|inference|gpu|h100|mlx|tensorrt|metal)\b", body, re.I) and re.search(
            r"\b\d+(?:\.\d+)?\s*(?:x|%|ms|s|sec(?:onds?)?|gpu|gpus|h100|tokens?/s)\b",
            body,
            re.I,
        ):
            return "full_text_efficiency_counterevidence"

    if neg_type in {"missing_robustness_or_generalization", "scope_overclaim", "insufficient_evaluation"}:
        body = str((state or {}).get("paper_text") or "")
        if re.search(r"\b(?:learning\s+rate|network\s+width|dataset\s+variation)\b", missing_l):
            theory_anchor = re.search(
                r"\b(?:theorem|proof|lemma|learning\s+dynamics|loss\s+landscape|global\s+minim|"
                r"closed[- ]form|bias[- ]free|relu|linear\s+network|symmetry|symmetric)\b",
                anchor_l,
                re.IGNORECASE,
            )
            explicit_scope_claim = re.search(
                r"\b(?:robust|robustness|generaliz(?:e|ation)|generalisation|across|out[- ]of[- ]domain|"
                r"ood|dataset\s+variation|network\s+width|learning\s+rate)\b",
                anchor_l,
                re.IGNORECASE,
            )
            if theory_anchor and not explicit_scope_claim:
                return "scope_robustness_gap_without_explicit_scope_claim"
        if re.search(r"\bgraph[- ]level\b|\bgraph\s+classification\b", missing_l) and re.search(
            r"\bnode\s+classification\b", anchor_l
        ) and not re.search(r"\bgraph\s+classification\b", anchor_l):
            return "missing_scope_not_claim_bound"
        if re.search(r"\b(?:held[- ]out|coverage)\b.{0,80}\bgcl\b", missing_l):
            if re.search(
                r"\b(?:heterophily|heterophilous|large[- ]scale|large\s+scale|node\s+classification|"
                r"benchmark(?:s)?|dataset(?:s)?|cora|citeseer|pubmed|ogbn|arxiv)\b",
                body,
                re.IGNORECASE,
            ):
                return "scope_coverage_counterevidenced_by_existing_graph_benchmarks"

    if neg_type in {
        "missing_robustness_or_generalization",
        "scope_overclaim",
        "insufficient_evaluation",
        "efficiency_cost_gap",
        "reproducibility_gap",
    }:
        menu_quality_failure = _review_issue_candidate_menu_quality_failure(
            neg_type=neg_type,
            expected_entity=missing_text,
            claim_text=anchor_quote,
            inventory_text=inventory_text,
            source=str(bundle.get("discovery_origin") or bundle.get("source_of_expectation") or ""),
        )
        if menu_quality_failure:
            return menu_quality_failure

    return ""


def _review_issue_missing_items_are_resource_cost_dimension(missing_items: Sequence[str]) -> bool:
    text = _missing_joined_text(missing_items)
    if not text:
        return False
    return bool(
        re.search(
            r"\b(?:runtime|latency|throughput|wall[- ]clock|time[- ]to[- ]first[- ]token|ttft|"
            r"inference\s+time|training\s+time|memory|gpu|cpu|hardware|parameters?|flops?|"
            r"compute|computational\s+(?:cost|time|budget)|resource|footprint|speedup)\b",
            text,
            re.IGNORECASE,
        )
    )


def _paper_has_with_without_target_counterevidence(
    paper_text: str,
    missing_items: Sequence[str],
    *,
    max_scan_chars: int = 80000,
    max_tokens: int = 12,
) -> bool:
    """Catch explicit with/without target comparisons that omit "ablation" wording."""

    text = str(paper_text or "")[:max_scan_chars]
    if not text:
        return False
    checked_tokens = 0
    for item in missing_items or []:
        tokens = {
            token.lower()
            for token in _ablation_missing_item_target_tokens(str(item or ""))
            if token and len(token) >= 3
        }
        tokens -= {
            "component",
            "isolation",
            "direction",
            "gradient",
            "learning",
            "regularization",
            "regularisation",
            "model",
            "module",
            "method",
        }
        for token in sorted(tokens, key=lambda value: (-len(value), value)):
            if not re.fullmatch(r"[a-z0-9][a-z0-9_-]{2,30}", token):
                continue
            checked_tokens += 1
            if checked_tokens > max_tokens:
                return False
            pattern = re.compile(
                rf"\b(?:with\s+or\s+without|with/without|w/?o|without)\s+{re.escape(token)}\b|"
                rf"\b{re.escape(token)}\b.{0,80}\b(?:with\s+or\s+without|without|w/?o)\b",
                re.IGNORECASE,
            )
            match = pattern.search(text)
            if match:
                local = text[max(0, match.start() - 160) : min(len(text), match.end() + 220)]
                if (
                    re.search(r"\bwith\s+(?:or|and)\s+without\b|\bwith/without\b|\bw/o\b", local, re.IGNORECASE)
                    or _ABLATION_COUNTEREVIDENCE_RE.search(local)
                    or (
                        _REVIEW_ISSUE_FULL_TEXT_EVAL_RE.search(local)
                        and re.search(
                            r"\b(?:compare[sd]?|comparison|results?|performance|score|ranking|rankings?|"
                            r"accuracy|kendall|baseline|methods?)\b",
                            local,
                            re.IGNORECASE,
                        )
                    )
                ):
                    return True
    return False


def _paper_has_ablation_counterevidence_for_missing_claim(
    state: Dict[str, Any],
    evidence: Dict[str, Any],
    claim_text: str,
    *,
    max_scan_chars: int = 80000,
    max_ablation_matches: int = 32,
) -> bool:
    """Reject missing-ablation negatives when the paper already reports the ablation.

    Missing-ablation is an absence claim. A quote about a component existing is
    not enough to verify that the ablation is absent; the full paper must also
    be checked for a reported ablation/variant that removes that component.
    """

    paper_text = str((state or {}).get("paper_text") or "")[:max_scan_chars]
    if not paper_text:
        return False

    missing_items = evidence.get("coverage_missing_items") or evidence.get("missing_or_weak_items") or []
    if isinstance(missing_items, str):
        missing_items = [missing_items]
    # Only target the alleged missing component, not the observed variants in the
    # quote/table. Pulling tokens from the quote itself would turn "w/o beam" into
    # false counterevidence for "missing routing-module ablation".
    normalized_missing_items = [
        str(item or "")
        for item in missing_items
        if isinstance(item, (str, int, float)) and str(item or "").strip()
    ]
    if not normalized_missing_items:
        normalized_missing_items = [str(claim_text or "")]
    if not any(_ablation_missing_item_target_tokens(item) for item in normalized_missing_items):
        return False
    cache_key = (
        _review_issue_full_text_cache_signature(paper_text),
        tuple(_normalize_text(item, max_length=180).lower() for item in normalized_missing_items),
        _normalize_text(claim_text, max_length=220).lower(),
        int(max_scan_chars),
        int(max_ablation_matches),
    )
    cached = _PAPER_ABLATION_COUNTEREVIDENCE_CACHE.get(cache_key)
    if cached is not None:
        return bool(cached)
    if _paper_has_with_without_target_counterevidence(paper_text, normalized_missing_items):
        return _review_issue_bool_cache_store(_PAPER_ABLATION_COUNTEREVIDENCE_CACHE, cache_key, True)
    if not _ABLATION_COUNTEREVIDENCE_RE.search(paper_text):
        return _review_issue_bool_cache_store(_PAPER_ABLATION_COUNTEREVIDENCE_CACHE, cache_key, False)

    for idx, match in enumerate(_ABLATION_COUNTEREVIDENCE_RE.finditer(paper_text)):
        if idx >= max_ablation_matches:
            break
        prev_breaks = [
            paper_text.rfind(marker, 0, match.start())
            for marker in ("\n\n", "\nTable", "\nFigure", "\nFig.", "\nSection", "\n\\section")
        ]
        next_breaks = [
            pos - match.end()
            for pos in (
                paper_text.find("\n\n", match.end()),
                paper_text.find("\nTable", match.end()),
                paper_text.find("\nFigure", match.end()),
                paper_text.find("\nFig.", match.end()),
                paper_text.find("\nSection", match.end()),
                paper_text.find("\n\\section", match.end()),
            )
            if pos >= 0
        ]
        start = max(prev_breaks) + 1 if max(prev_breaks) >= 0 else max(0, match.start() - 320)
        end = match.end() + (min(next_breaks) if next_breaks else 420)
        end = min(len(paper_text), end)
        window = paper_text[start:end]
        if _ablation_missing_items_resolved_by_text(window, normalized_missing_items):
            return _review_issue_bool_cache_store(_PAPER_ABLATION_COUNTEREVIDENCE_CACHE, cache_key, True)
        if not _ablation_missing_items_have_scope(normalized_missing_items):
            expanded = paper_text[max(0, match.start() - 900) : min(len(paper_text), match.end() + 1400)]
            if expanded != window and _ablation_missing_items_resolved_by_text(expanded, normalized_missing_items):
                return _review_issue_bool_cache_store(_PAPER_ABLATION_COUNTEREVIDENCE_CACHE, cache_key, True)
    return _review_issue_bool_cache_store(_PAPER_ABLATION_COUNTEREVIDENCE_CACHE, cache_key, False)


_MISSING_BASELINE_TARGET_BROAD_OR_TRUNCATED_RE = re.compile(
    r"^(?:"
    r"baseline_for_[a-z0-9_-]+|"
    r"high[- ]?retur(?:n)?|"
    r"pre[- ]?training|pretrained|pre[- ]?trained|"
    r"distillation[- ]?based|distillation|"
    r"same[- ]setting|same[- ]budget|"
    r"strong(?:er|est)?|standard|recent|relevant|competitive|"
    r"prior|existing|state[- ]of[- ]the[- ]art|sota|"
    r"method|methods|approach|approaches|model|models|baseline|baselines|comparison|comparisons|"
    r"paper[- ]named|closed[- ]source|open[- ]source|reference|"
    r"something[- ]something"
    r")$",
    re.IGNORECASE,
)


def _missing_baseline_target_text(text: str) -> str:
    value = re.sub(r"\s+", " ", str(text or "")).strip(" ,.;:")
    value = re.sub(r"^baseline_for_", "", value, flags=re.IGNORECASE).replace("_", " ")
    value = re.sub(
        r"^\s*(?:same[- ]setting|same[- ]budget|fair|strong|stronger|paper[- ]named)?\s*"
        r"(?:(?:baseline|method|model)\s+)?(?:comparison\s+)?(?:against|for|to|with)\s+",
        "",
        value,
        flags=re.IGNORECASE,
    ).strip(" ,.;:")
    value = re.sub(r"\s+(?:baseline|method|model|comparison)$", "", value, flags=re.IGNORECASE).strip(" ,.;:")
    return re.sub(r"\s+", " ", value)


def _paper_named_baseline_name_from_target(text: str) -> str:
    value = _normalize_text(text, max_length=180)
    if not value:
        return ""
    match = re.search(
        r"\bpaper[- ]named\s+([A-Z][A-Za-z0-9_-]{2,}(?:[-+][A-Za-z0-9]+)?)\b",
        value,
    )
    if match:
        return _normalize_text(match.group(1), max_length=80)
    return ""


def _paper_named_baseline_bundle_proves_target_name(bundle: Dict[str, Any], raw: str, target: str) -> bool:
    name = _paper_named_baseline_name_from_target(raw) or _paper_named_baseline_name_from_target(target)
    if not name:
        return False
    lowered = name.lower()
    if lowered in {"labor", "labour", "paper", "prior", "related", "work", "method", "model", "network"}:
        return False
    if lowered in _PAPER_NAMED_BASELINE_NAME_STOPWORDS or _PAPER_NAMED_BASELINE_DATASET_NAME_RE.search(name):
        return False

    menu_item = bundle.get("review_issue_candidate_menu_item") if isinstance(bundle, dict) else {}
    if not isinstance(menu_item, dict):
        menu_item = {}
    source_text = " ".join(
        str(value or "")
        for value in [
            bundle.get("discovery_origin") if isinstance(bundle, dict) else "",
            bundle.get("entity_source") if isinstance(bundle, dict) else "",
            bundle.get("source_of_expectation") if isinstance(bundle, dict) else "",
            menu_item.get("source"),
            menu_item.get("entity_source"),
        ]
    ).lower()
    if "paper_named" not in source_text and "related_method" not in source_text:
        return False

    expected_blob = " ".join(
        str(value or "")
        for value in [
            raw,
            target,
            menu_item.get("expected_entity"),
            menu_item.get("verifier_target_entity"),
            bundle.get("paper_named_baseline_name") if isinstance(bundle, dict) else "",
            menu_item.get("paper_named_baseline_name"),
            " ".join(str(term or "") for term in menu_item.get("counterevidence_search_terms") or []),
        ]
    )
    if not _text_contains_surface_marker(expected_blob, name):
        return False

    proven_name = _normalize_text(
        menu_item.get("paper_named_baseline_name")
        or menu_item.get("baseline_name")
        or (bundle.get("paper_named_baseline_name") if isinstance(bundle, dict) else ""),
        max_length=80,
    )
    expectation_quote = _normalize_text(
        menu_item.get("paper_named_baseline_expectation_quote")
        or menu_item.get("expectation_quote")
        or (bundle.get("paper_named_baseline_expectation_quote") if isinstance(bundle, dict) else ""),
        max_length=300,
    )
    if not proven_name or not expectation_quote:
        return False
    if proven_name.lower() != lowered:
        return False
    return _paper_named_baseline_name_is_usable(proven_name, expectation_quote, "", "")


def _missing_baseline_target_specificity_failure(bundle: Dict[str, Any]) -> str:
    missing = bundle.get("missing_or_mismatch") if isinstance(bundle, dict) else {}
    raw_items: List[str] = []
    if isinstance(missing, dict):
        raw_items = [
            str(item or "").strip()
            for item in (missing.get("items") or [missing.get("entity")])
            if str(item or "").strip()
        ]
    for raw in raw_items:
        target = _missing_baseline_target_text(raw)
        lowered = target.lower()
        if not target:
            return "missing_baseline_target_empty"
        if re.search(r"\bstandard\b.{0,80}\b(?:baselines?|datasets?)\b.{0,80}\bclaim\s+scope\b", lowered):
            return "missing_baseline_target_generic_or_truncated"
        if _MISSING_BASELINE_TARGET_BROAD_OR_TRUNCATED_RE.fullmatch(lowered):
            return "missing_baseline_target_generic_or_truncated"
        if lowered.endswith("-") or re.search(r"\b(?:retur|distillatio|pre-trainin|compariso)\b", lowered):
            return "missing_baseline_target_generic_or_truncated"
        if _paper_named_baseline_bundle_proves_target_name(bundle, raw, target):
            continue
        if re.fullmatch(r"[A-Z]{2,10}(?:-[A-Z0-9]+)?", target) and target.lower() not in {
            "fl",
            "gnn",
            "gnns",
            "nas",
            "ris",
            "rl",
            "uda",
        }:
            continue
        if re.fullmatch(r"[a-z]+(?:[- ][a-z]+){0,2}", lowered) and not re.search(
            r"\b(?:lavt|equalal|gpt-\d|bert|clip|dino|sam|yolo|resnet|vit|llama|mistral|"
            r"t5|gdas|randomnas|ripu|tcmt-ft|snas|darts|fairnas|fbnet|proxylessnas)\b",
            lowered,
        ):
            return "missing_baseline_target_generic_or_truncated"
    return ""


def _baseline_candidate_item_is_generic(text: str) -> bool:
    lowered = _normalize_text(text, max_length=180).lower()
    if not lowered:
        return True
    return bool(
        re.search(
            r"\b(?:other|more|strong(?:er)?|leading|competitive|state[- ]of[- ]the[- ]art|sota|"
            r"standard|recent|relevant|additional)\s+"
            r"(?:[a-z0-9_-]+\s+){0,5}(?:baseline|baselines|methods|competitors)\b",
            lowered,
        )
        or lowered in {
            "strong baselines",
            "stronger baselines",
            "other baselines",
            "other methods",
            "competitive baselines",
        }
    )


def _single_named_baseline_contextualized_in_candidate(name: str, text: str) -> bool:
    clean = _normalize_text(name, max_length=60).strip()
    if not clean or not text:
        return False
    escaped = re.escape(clean)
    return bool(
        re.search(
            rf"\b(?:baseline|baselines|method|methods|model|models|comparison|comparisons|competitor|competitors)\s+"
            rf"(?:[A-Za-z0-9_+\-]+\s+){{0,4}}{escaped}\b",
            text,
            re.IGNORECASE,
        )
        or re.search(
            rf"\b{escaped}\s+"
            rf"(?:[A-Za-z0-9_+\-]+\s+){{0,4}}(?:baseline|baselines|method|methods|model|models|competitor|competitors)\b",
            text,
            re.IGNORECASE,
        )
        or re.search(
            rf"\b(?:against|with|include|includes|including|omits?|missing|compare|compares|compared|comparison)\b"
            rf"[^.;:\n]{{0,80}}\b{escaped}\b",
            text,
            re.IGNORECASE,
        )
    )


def _window_has_broad_sota_baseline_comparison(window: str) -> bool:
    text = re.sub(r"\s+", " ", str(window or ""))
    if not text:
        return False
    return bool(
        re.search(
            r"\b(?:compare|compares|compared|comparison)\b.{0,120}\b(?:with|against|between)\b"
            r".{0,80}\b\d{1,2}\s+(?:(?:state[- ]of[- ]the[- ]art|sota|strong|competitive)\s+)?"
            r"(?:[a-z0-9-]+\s+){0,4}(?:methods?|competitors?|baselines?)\b",
            text,
            re.IGNORECASE,
        )
        or re.search(
            r"\b\d{1,2}\s+(?:(?:state[- ]of[- ]the[- ]art|sota|strong|competitive)\s+)?"
            r"(?:[a-z0-9-]+\s+){0,4}(?:methods?|competitors?|baselines?)\b",
            text,
            re.IGNORECASE,
        )
    )


def _reviewer_candidate_external_baseline_list_countered_by_broad_comparison(
    bundle: Dict[str, Any],
    body: str,
    windows: Sequence[str],
    missing_items: Sequence[str],
) -> bool:
    if str((bundle or {}).get("source_of_expectation") or "") != "reviewer_candidate":
        return False
    if not re.search(
        r"\b(?:freeform|critique|review-issue-candidate)\b",
        " ".join([
            str((bundle or {}).get("discovery_origin") or ""),
            str((bundle or {}).get("reviewer_negative_candidate_id") or ""),
        ]),
        re.IGNORECASE,
    ):
        return False
    terms = {
        term for term in _baseline_missing_counterevidence_terms(missing_items)
        if term and term not in _BASELINE_COUNTEREVIDENCE_GENERIC_TERMS and len(term) >= 3
    }
    if len(terms) < 2:
        return False
    # If the paper itself names the expected method family, the candidate is
    # auditable as a paper-surface omission.  The broad-comparison guard only
    # blocks external lists that the paper never names while already claiming a
    # large same-setting comparison set.
    if any(_text_contains_surface_marker(body, term) for term in terms):
        return False
    return _window_has_broad_sota_baseline_comparison(body) or any(
        _window_has_broad_sota_baseline_comparison(window)
        for window in windows
    )


def _named_baseline_items_from_candidate(candidate: Dict[str, Any]) -> List[str]:
    if not isinstance(candidate, dict):
        return []
    neg_type = _canonical_negative_evidence_type(
        candidate.get("negative_type")
        or candidate.get("issue_type")
        or candidate.get("review_issue_type")
    )
    if neg_type not in _COVERAGE_BASELINE_NEGATIVE_TYPES:
        return []
    raw_missing = _normalize_list_of_strings(
        candidate.get("missing_or_weak_items")
        or candidate.get("coverage_missing_items")
        or candidate.get("missing_items")
        or candidate.get("expected_missing_items"),
        max_items=6,
        max_length=160,
    )
    if raw_missing and any(_coverage_item_is_specific_for_type(item, neg_type) for item in raw_missing):
        return []
    raw_missing_name_candidates: List[str] = []
    for item in raw_missing:
        target = _missing_baseline_target_text(item)
        target = re.sub(r"\s+(?:baseline|baselines|method|methods|model|models)$", "", target, flags=re.IGNORECASE).strip()
        if re.fullmatch(r"[A-Z][A-Za-z0-9_+\-]{2,40}", target) or re.search(
            r"(?:NAS|Net|DARTS|BERT|CLIP|ViT)$",
            target,
        ):
            raw_missing_name_candidates.append(target)
    text_parts = [
        str(candidate.get("verification_question") or ""),
        str(candidate.get("weakness") or ""),
        str(candidate.get("rationale") or ""),
    ]
    text_parts.extend(
        _normalize_list_of_strings(
            candidate.get("possible_counterevidence_terms")
            or candidate.get("counterevidence_search_terms")
            or candidate.get("expected_quote_cues"),
            max_items=12,
            max_length=80,
        )
    )
    text = " ".join(text_parts)
    if not re.search(r"\b(?:baseline|baselines|method|methods|comparison|competitor|competitors|NAS|SOTA)\b", text):
        text = ""
    allow_single_contextual_name = (
        len(raw_missing_name_candidates) == 1
        and _single_named_baseline_contextualized_in_candidate(raw_missing_name_candidates[0], text)
    )
    if raw_missing and not any(_baseline_candidate_item_is_generic(item) for item in raw_missing) and len(raw_missing_name_candidates) < 2:
        if not allow_single_contextual_name:
            return []
    candidates: List[str] = list(raw_missing_name_candidates)
    for match in re.finditer(r"\b[A-Z][A-Za-z0-9]*(?:NAS|Net|Former|BERT|CLIP|DARTS|GDAS|SNAS|SAM|YOLO|ViT)\b", text):
        candidates.append(match.group(0))
    for match in re.finditer(r"\b[A-Z]{2,}(?:-[A-Z0-9]+)?\b", text):
        candidates.append(match.group(0))
    for match in re.finditer(r"\b(?:e\.g\.,?|including|such\s+as)\s+([^.;:()]{2,160})", text, re.IGNORECASE):
        segment = match.group(1)
        for token in re.split(r",|\bor\b|\band\b|/", segment):
            token = token.strip(" `\"'()[]{}")
            if re.fullmatch(r"[A-Z][A-Za-z0-9_+\-]{2,30}", token) or re.search(r"(?:NAS|Net|DARTS|BERT|CLIP|ViT)$", token):
                candidates.append(token)
    generic = {
        "NAS",
        "SOTA",
        "OOD",
        "GPU",
        "CPU",
        "FLOP",
        "FLOPS",
        "CIFAR",
        "CIFAR-10",
        "CIFAR-100",
        "ImageNet",
    }
    normalized: List[str] = []
    seen: set[str] = set()
    for name in candidates:
        clean = _normalize_text(name, max_length=40).strip(" ,.;:")
        if not clean or clean in generic:
            continue
        if clean.lower() in _BASELINE_COUNTEREVIDENCE_GENERIC_TERMS:
            continue
        key = clean.lower()
        if key in seen:
            continue
        seen.add(key)
        normalized.append(f"same-setting comparison against {clean} baseline")
        if len(normalized) >= 5:
            break
    # A single extracted acronym can easily be a dataset/task token.  Requiring
    # at least two names keeps this normalization tied to explicit example lists.
    return normalized if len(normalized) >= 2 or (allow_single_contextual_name and normalized) else []


def _freeform_candidate_for_targeted_negative_evidence(
    state: Dict[str, Any],
    evidence: Dict[str, Any],
) -> Optional[Dict[str, Any]]:
    task_id = str(evidence.get("targeted_negative_search_task_id") or "").strip()
    candidate_id = str(evidence.get("reviewer_negative_candidate_id") or "").strip()
    claim_id = str(evidence.get("claim_id") or "").strip()
    if not task_id and not candidate_id:
        return None
    for candidate in (state or {}).get("reviewer_negative_candidates", []) or []:
        if not isinstance(candidate, dict):
            continue
        cand_claim_id = str(candidate.get("claim_id") or "").strip()
        if claim_id and cand_claim_id and cand_claim_id != claim_id:
            continue
        cand_id = str(candidate.get("candidate_id") or "").strip()
        expected_task_id = _slugify(
            "neg-search-freeform",
            f"{cand_claim_id}-{cand_id or str(candidate.get('negative_type') or '').strip()}",
            1,
        )
        if (candidate_id and cand_id == candidate_id) or (task_id and task_id == expected_task_id):
            return candidate
    return None


def _coverage_missing_items_for_evidence(state: Dict[str, Any], evidence: Dict[str, Any], neg_type: str) -> List[str]:
    raw_items: List[str] = []
    for field in ("coverage_missing_items", "missing_or_weak_items", "missing_items", "expected_missing_items"):
        raw_items.extend(_normalize_list_of_strings(evidence.get(field), max_items=8, max_length=160))
    candidate = _freeform_candidate_for_targeted_negative_evidence(state, evidence)
    if candidate:
        for field in ("missing_or_weak_items", "missing_items", "expected_missing_items", "coverage_missing_items"):
            raw_items.extend(_normalize_list_of_strings(candidate.get(field), max_items=8, max_length=160))
    selected: List[str] = []
    seen: set[str] = set()
    for item in raw_items:
        key = item.lower()
        if key in seen:
            continue
        seen.add(key)
        if not _coverage_item_is_specific_for_type(item, neg_type):
            continue
        selected.append(item)
        if len(selected) >= 6:
            break
    return selected


_QUOTE_GROUNDABLE_REVIEWER_NEGATIVE_TYPES = frozenset(
    {
        "direct_contradiction",
        "negative_result",
        "missing_ablation",
        "missing_baseline",
        "unfair_or_weak_baseline",
        "insufficient_evaluation",
        "result_claim_mismatch",
        "evaluation_protocol_risk",
        "efficiency_cost_gap",
    }
)


_QUOTE_GROUNDABLE_INTERNAL_NEGATIVE_CUE_RE = re.compile(
    r"\b("
    r"cannot\s+(?:be\s+)?(?:used\s+to\s+)?compar\w*"
    r"|not\s+comparable"
    r"|incomparable"
    r"|unfair\s+compar\w*"
    r"|worse"
    r"|lower\s+than"
    r"|underperform"
    r"|less\s+favo(?:u)?rable"
    r"|reduc(?:e|es|ed|ing)\s+(?:the\s+)?performance"
    r"|performance\s+(?:declin|degrad)"
    r"|degrad(?:e|es|ed|ation)"
    r"|minimal\s+performance\s+gains?"
    r"|no\s+significant\s+improv\w*"
    r"|fail(?:s|ed)?\s+to"
    r"|invalid\s+compar\w*"
    r"|memory\s+bottleneck"
    r"|latency"
    r"|runtime"
    r"|overhead"
    r"|trade[- ]?off"
    r"|sensitivity"
    r"|must\s+be\s+tuned"
    r")\b",
    re.IGNORECASE,
)
_QUOTE_GROUNDABLE_SELF_COMPARISON_RE = re.compile(
    r"\b([A-Z][A-Za-z0-9_-]{2,})\s+outperform\w*\s+\1\b",
    re.IGNORECASE,
)


def _reviewer_negative_candidate_quote_route(candidate: Dict[str, Any]) -> str:
    """Classify whether a reviewer-negative hypothesis belongs in quote verification."""

    mode = str(candidate.get("quote_grounding_mode") or "").strip().lower()
    negative_type = str(candidate.get("negative_type") or "").strip().lower().replace("-", "_")
    if mode == "quote_groundable_internal_negative":
        raw_quote = str(candidate.get("candidate_raw_quote") or candidate.get("raw_quote") or "")
        candidate_context = " ".join(
            str(candidate.get(field) or "")
            for field in ("weakness", "rationale", "verification_question")
        )
        candidate_context = " ".join(
            [candidate_context]
            + _normalize_list_of_strings(candidate.get("expected_quote_cues"), max_items=8, max_length=80)
            + _normalize_list_of_strings(
                candidate.get("missing_or_weak_items")
                or candidate.get("missing_items")
                or candidate.get("expected_missing_items"),
                max_items=8,
                max_length=80,
            )
        )
        has_quote_anchor = bool(raw_quote.strip())
        has_raw_negative_cue = bool(_QUOTE_GROUNDABLE_INTERNAL_NEGATIVE_CUE_RE.search(raw_quote))
        has_candidate_negative_cue = bool(_QUOTE_GROUNDABLE_INTERNAL_NEGATIVE_CUE_RE.search(candidate_context))
        if (
            has_quote_anchor
            and _REVIEW_NEGATIVE_POSITIVE_CONTEXT_RE.search(raw_quote)
            and not has_raw_negative_cue
        ):
            return "absence_or_requirement_gap"
        if negative_type == "direct_contradiction" and _QUOTE_GROUNDABLE_SELF_COMPARISON_RE.search(raw_quote):
            return mode
        if negative_type in _QUOTE_GROUNDABLE_REVIEWER_NEGATIVE_TYPES:
            if has_raw_negative_cue:
                return mode
            if has_quote_anchor and has_candidate_negative_cue:
                return mode
            if (
                has_quote_anchor
                and _normalize_list_of_strings(candidate.get("expected_quote_cues"), max_items=8, max_length=80)
                and not _REVIEW_NEGATIVE_POSITIVE_CONTEXT_RE.search(raw_quote)
            ):
                return mode
            return "absence_or_requirement_gap"
        if _QUOTE_GROUNDABLE_INTERNAL_NEGATIVE_CUE_RE.search(raw_quote):
            return mode
        if has_quote_anchor and has_candidate_negative_cue:
            return mode
        return "absence_or_requirement_gap"
    if mode in {"table_scope_absence", "absence_or_requirement_gap"}:
        return mode
    if negative_type in _QUOTE_GROUNDABLE_REVIEWER_NEGATIVE_TYPES:
        return "quote_groundable_internal_negative"
    return ""


def _specific_surface_tokens(text: str) -> set[str]:
    value = str(text or "")
    tokens = set()
    for left, right in re.findall(r"(?<![A-Za-z])\$?([A-Za-z])\$?\s*-\s*([A-Za-z]{2,})\b", value):
        tokens.add(f"{left}-{right}".lower())
    patterns = (
        r"\b[A-Z]{2,}[A-Za-z0-9_-]*\b",
        r"\b[A-Z][a-z]+[A-Z][A-Za-z0-9_-]*\b",
        r"\b[A-Za-z]+[-/][A-Za-z0-9_-]+\b",
        r"\b[A-Za-z]*\d[A-Za-z][A-Za-z0-9_-]*\b",
        r"\b[A-Za-z]+[A-Za-z0-9_-]*\d[A-Za-z0-9_-]*\b",
    )
    for pattern in patterns:
        for match in re.findall(pattern, value):
            clean = str(match).strip().lower()
            if len(clean) >= 3:
                tokens.add(clean)
    return tokens


def _surface_marker_patterns(token: str) -> List[str]:
    """Regexes for paper-surface entity markers, including LaTeX/hyphen variants."""

    clean = str(token or "").strip().lower()
    if not clean:
        return []
    patterns = [re.escape(clean)]
    parts = [part for part in re.split(r"[-/\s]+", clean) if part]
    if len(parts) >= 2:
        part_patterns = []
        for part in parts:
            escaped = re.escape(part)
            if len(part) <= 2:
                part_patterns.append(rf"\$?\s*{escaped}\s*\$?")
            else:
                part_patterns.append(escaped)
        sep = r"(?:\s|[-–—/\\]|\$)+"
        patterns.append(sep.join(part_patterns))
    return list(dict.fromkeys(patterns))


def _text_contains_surface_marker(text: str, token: str) -> bool:
    lowered = str(text or "").lower()
    if not lowered or not str(token or "").strip():
        return False
    for pattern in _surface_marker_patterns(token):
        if re.search(rf"(?<![a-z0-9]){pattern}(?![a-z0-9])", lowered, re.IGNORECASE):
            return True
    return False


def _coverage_observed_items_for_evidence(evidence: Dict[str, Any]) -> List[str]:
    return _normalize_list_of_strings(
        evidence.get("coverage_observed_items") or evidence.get("observed_items"),
        max_items=12,
        max_length=80,
    )


def _coverage_quote_has_visible_observed_scope(
    quote: str,
    evidence: Dict[str, Any],
) -> bool:
    observed_items = _coverage_observed_items_for_evidence(evidence)
    quote_tokens = _semantic_tokens(quote)
    if observed_items:
        for item in observed_items:
            item_tokens = _semantic_tokens(item)
            if item_tokens and item_tokens <= quote_tokens:
                return True
            if _specific_surface_tokens(item) & _specific_surface_tokens(quote):
                return True
        return False
    # Fallback when the model forgot coverage_observed_items: only accept quotes
    # that visibly enumerate concrete paper artifacts (named datasets, methods,
    # models, benchmarks).  Generic prose about metrics/evaluation is not enough
    # to verify an absence claim.
    specific_tokens = _specific_surface_tokens(quote)
    if len(specific_tokens) < 2:
        return False
    if re.search(
        r"\b(?:results?\s+(?:demonstrate|show|indicate)|significant\s+advantage|"
        r"superior\s+performance|showcasing|outperform(?:s|ed)?)\b",
        quote,
        re.IGNORECASE,
    ) and not (_SEMANTIC_TABLE_RE.search(quote) or re.search(r"[|&;]", quote)):
        return False
    if _SEMANTIC_TABLE_RE.search(quote) or re.search(r"[|&;]", quote):
        return True
    if len(specific_tokens) >= 3 and re.search(
        r"\b(?:include|including|listed|consist(?:s)?\s+of|as\s+follows|"
        r"datasets?|benchmarks?|baselines?|metrics?|components?)\b",
        quote,
        re.IGNORECASE,
    ):
        return True
    return False


_BASELINE_PRESENT_SUPPORT_QUOTE_RE = re.compile(
    r"\b(?:baseline|baselines|comparison|compared|against|strongest|state[- ]of[- ]the[- ]art|sota)\b",
    re.IGNORECASE,
)
_TABLE_SCOPE_NEGATIVE_QUOTE_ANCHOR_RE = re.compile(
    r"\b(?:only|limited|single|few|minimal|marginal|worse|underperform|"
    r"cannot|does\s+not|do\s+not|did\s+not|no|without|lack(?:s|ed|ing)?|"
    r"missing|not\s+(?:evaluated|tested|reported|provided|compared))\b",
    re.IGNORECASE,
)


def _baseline_absence_target_already_present_in_quote(
    quote: str,
    coverage_missing_items: Sequence[str],
) -> bool:
    """Reject baseline absence claims whose named target is already in the quote.

    A quote saying "k-NN is the strongest baseline" grounds that k-NN was used as
    a comparison point; it does not itself verify a reviewer flaw that the k-NN
    baseline is missing/weak.  Such baseline adequacy judgments should stay in
    the absence-audit / follow-up channel unless the quote explicitly reports a
    current-paper comparison failure.
    """

    if not _BASELINE_PRESENT_SUPPORT_QUOTE_RE.search(str(quote or "")):
        return False
    quote_surface = _specific_surface_tokens(quote)
    if not quote_surface:
        return False
    for item in coverage_missing_items or []:
        item_surface = _specific_surface_tokens(str(item or ""))
        if item_surface and item_surface <= quote_surface:
            return True
    return False


def _is_table_scope_absence_negative(
    state: Dict[str, Any],
    evidence: Dict[str, Any],
    quote: str,
    claim_text: str,
    evidence_text: str,
    source_locator: str,
) -> bool:
    """Narrowly verify list/table-scope absence claims.

    This covers reviewer findings such as "the claim names DAVIS2017, but the
    paper's own result table lists only DAVIS2016/FBMS59/SegTrackV2".  It still
    requires a copied paper quote with a table/list/result anchor and rejects
    author limitations, prior-work text, and positive support.
    """

    if not _evidence_has_negative_intent(evidence):
        return False
    neg_type = _negative_evidence_type_for_record(evidence)
    if neg_type not in _SEMANTIC_ABSENCE_NEGATIVE_TYPES:
        return False
    evidence_absence_text = " ".join([evidence_text, str(evidence.get("agent_raw_quote") or "")])
    if _SEMANTIC_ABSENCE_EXCERPT_LIMIT_RE.search(evidence_absence_text):
        return False
    combined = " ".join([claim_text, evidence_absence_text])
    coverage_missing_items = _coverage_missing_items_for_evidence(state, evidence, neg_type)
    if not _SEMANTIC_ABSENCE_TERMS_RE.search(evidence_absence_text) and not coverage_missing_items:
        return False
    if not _SEMANTIC_LIST_OR_TABLE_RE.search(quote):
        return False
    if (
        not _TABLE_SCOPE_NEGATIVE_QUOTE_ANCHOR_RE.search(quote)
        and not _SEMANTIC_ABSENCE_TERMS_RE.search(evidence_absence_text)
    ):
        return False
    if (
        not coverage_missing_items
        and not _TABLE_SCOPE_NEGATIVE_QUOTE_ANCHOR_RE.search(quote)
        and not _coverage_quote_has_visible_observed_scope(quote, evidence)
    ):
        return False
    if not coverage_missing_items and neg_type == "missing_ablation":
        return False
    if coverage_missing_items and not _coverage_quote_has_visible_observed_scope(quote, evidence):
        return False
    if (
        neg_type in _COVERAGE_BASELINE_NEGATIVE_TYPES
        and coverage_missing_items
        and _baseline_absence_target_already_present_in_quote(quote, coverage_missing_items)
    ):
        return False
    if _REVIEW_NEGATIVE_AUTHOR_LIMITATION_RE.search(quote) or _negative_anchor_is_prior_work_context(quote):
        return False
    if _REVIEW_NEGATIVE_POSITIVE_CONTEXT_RE.search(quote):
        return False
    quote_tokens = _semantic_tokens(quote)
    if coverage_missing_items:
        target_text = " ".join(coverage_missing_items)
    else:
        target_text = evidence_absence_text
    target_tokens = _absence_target_tokens(target_text) - quote_tokens
    target_tokens = {
        token
        for token in target_tokens
        if any(ch.isdigit() for ch in token) or len(token) >= 6
    }
    if not target_tokens:
        return False
    claim_tokens = _semantic_tokens(claim_text)
    evidence_tokens = _semantic_tokens(evidence_text)
    # Require the missing entity to be explicitly named in the model's evidence
    # statement.  Claim-only generic words such as "comprehensive evaluation"
    # are too weak to verify a list/table absence.
    if coverage_missing_items:
        evidence_tokens |= _semantic_tokens(" ".join(coverage_missing_items))
    if not (target_tokens & evidence_tokens):
        return False
    if not coverage_missing_items and not (target_tokens & claim_tokens):
        return False
    if not (target_tokens & (claim_tokens | evidence_tokens)):
        return False
    return True


def _derive_table_scope_absence_negative_type(evidence: Dict[str, Any]) -> str:
    text = " ".join(
        str(evidence.get(key) or "")
        for key in ("evidence", "agent_raw_quote", "binding_rationale", "source", "source_locator")
    ).lower()
    if re.search(r"\bablat(?:e|ed|ion|ions)?\b|component|module|mechanism", text):
        return "missing_ablation"
    if re.search(r"\bbaseline|comparison|compare|sota|state-of-the-art|state of the art\b", text):
        return "missing_baseline"
    if re.search(r"\bruntime|latency|memory|flops|compute|cost|efficien", text):
        return "efficiency_cost_gap"
    if re.search(r"\brobust|generaliz|generalis|out-of-domain|ood|unseen|cross-domain|stress\b", text):
        return "missing_robustness_or_generalization"
    return "insufficient_evaluation"


def _semantic_numeric_anchors(text: str) -> set[str]:
    numbers = set()
    value_text = str(text or "")
    for match in _SEMANTIC_NUMBER_RE.finditer(value_text):
        raw = match.group(0)
        prefix = value_text[max(0, match.start() - 24):match.start()].lower()
        value = raw.rstrip("%")
        try:
            numeric = float(value)
        except ValueError:
            continue
        # Years and table/figure ordinals are weak semantic anchors; table/figure ids
        # are checked separately so they do not overconstrain broad claims.
        if 1900 <= numeric <= 2099:
            continue
        if re.search(r"(?:section|sec\.|subsection)\s*$", prefix):
            continue
        if numeric < 10 and "." not in value and not raw.endswith("%"):
            continue
        numbers.add(raw.lower())
    return numbers


def _semantic_table_anchors(text: str) -> set[str]:
    anchors = set()
    for match in _SEMANTIC_TABLE_RE.finditer(str(text or "")):
        kind = match.group(1).lower().replace("fig.", "figure")
        number = re.search(r"\d+", match.group(0))
        if number:
            anchors.add(f"{kind} {number.group(0)}")
    return anchors


def _claim_text_for_evidence(state: Dict[str, Any], claim_id: str) -> str:
    for claim in state.get("claims", []) or []:
        if isinstance(claim, dict) and str(claim.get("claim_id") or "") == claim_id:
            return str(claim.get("claim") or claim.get("text") or "")
    return ""


def _quote_bank_entries_for_grounding(state: Dict[str, Any]) -> List[Dict[str, Any]]:
    entries: List[Dict[str, Any]] = []
    latest_meta = (state or {}).get("_latest_evidence_context_meta") or {}
    for source in (
        latest_meta.get("evidence_quote_bank", []) if isinstance(latest_meta, dict) else [],
        latest_meta.get("critique_negative_quote_bank", []) if isinstance(latest_meta, dict) else [],
        (state or {}).get("evidence_quote_bank", []),
        (state or {}).get("critique_negative_quote_bank", []),
    ):
        for entry in source or []:
            if isinstance(entry, dict):
                entries.append(entry)
    deduped: List[Dict[str, Any]] = []
    seen: set[str] = set()
    for entry in entries:
        key = _quote_bank_entry_state_dedupe_key(entry)
        if key in seen:
            continue
        seen.add(key)
        deduped.append(entry)
    return deduped


def _quote_bank_entry_state_dedupe_key(entry: Dict[str, Any]) -> str:
    quote_id = str((entry or {}).get("quote_id") or "")
    raw_quote = str((entry or {}).get("raw_quote") or "")
    raw_key = _quote_bank_dedupe_key(raw_quote)
    if _is_candidate_window_quote_bank_entry(entry):
        return f"candidate-window:{quote_id}:{raw_key}"
    return f"id:{quote_id}" if quote_id else f"raw:{raw_key}"


def _is_candidate_window_quote_bank_entry(entry: Dict[str, Any]) -> bool:
    if not isinstance(entry, dict):
        return False
    return bool(entry.get("candidate_window_quote")) or str(entry.get("source_bucket") or "") == "candidate_window"


def _persist_latest_verifier_quote_bank_entries(state: Dict[str, Any]) -> None:
    """Keep dynamic quote-bank entries needed for offline re-verification.

    Candidate-window quote ids are local to an Evidence turn and may be reused
    on later turns.  If we only keep the latest transient context, dashboards
    cannot re-ground earlier verified negative evidence after stripping runtime
    verifier fields.  Persist only verifier quote references, not full prompt
    context, and de-duplicate candidate windows by quote id plus raw text.
    """

    if not isinstance(state, dict):
        return
    meta = state.get("_latest_evidence_context_meta") or {}
    if not isinstance(meta, dict):
        return

    current_bank = [item for item in state.get("evidence_quote_bank", []) or [] if isinstance(item, dict)]
    seen = {_quote_bank_entry_state_dedupe_key(item) for item in current_bank}
    candidate_window_additions: List[Dict[str, Any]] = []
    for entry in meta.get("evidence_quote_bank", []) or []:
        if not isinstance(entry, dict) or not _is_candidate_window_quote_bank_entry(entry):
            continue
        key = _quote_bank_entry_state_dedupe_key(entry)
        if key in seen:
            continue
        persisted = dict(entry)
        persisted["persisted_candidate_window_quote"] = True
        candidate_window_additions.append(persisted)
        seen.add(key)
    if candidate_window_additions:
        base_entries = [
            item for item in current_bank
            if not _is_candidate_window_quote_bank_entry(item)
        ][:12]
        existing_windows = [
            item for item in current_bank
            if _is_candidate_window_quote_bank_entry(item)
        ]
        state["evidence_quote_bank"] = base_entries + (existing_windows + candidate_window_additions)[-24:]

    current_negative_bank = [
        item for item in state.get("critique_negative_quote_bank", []) or []
        if isinstance(item, dict)
    ]
    seen_negative = {_quote_bank_entry_state_dedupe_key(item) for item in current_negative_bank}
    negative_additions: List[Dict[str, Any]] = []
    for entry in meta.get("critique_negative_quote_bank", []) or []:
        if not isinstance(entry, dict):
            continue
        key = _quote_bank_entry_state_dedupe_key(entry)
        if key in seen_negative:
            continue
        persisted = dict(entry)
        persisted["persisted_critique_negative_quote"] = True
        negative_additions.append(persisted)
        seen_negative.add(key)
    if negative_additions:
        state["critique_negative_quote_bank"] = (current_negative_bank + negative_additions)[-24:]


def _apply_quote_bank_entry_metadata(item: Dict[str, Any], entry: Dict[str, Any], *, canonicalize_quote: bool = False, overwrite_locator: bool = False) -> None:
    quote_id = str(entry.get("quote_id") or "")
    if quote_id:
        item["quote_id"] = quote_id
    canonical_quote = str(entry.get("raw_quote") or "")
    if canonicalize_quote and canonical_quote:
        agent_raw_quote = str(item.get("raw_quote") or "")
        if agent_raw_quote and agent_raw_quote != canonical_quote:
            item["agent_raw_quote"] = agent_raw_quote
            item["quote_bank_canonicalized"] = True
        item["raw_quote"] = canonical_quote
    locator = str(entry.get("source_locator") or "")
    if locator and (overwrite_locator or not item.get("source_locator") or item.get("source_locator") == item.get("source")):
        item["source_locator"] = locator
    span_start = _normalize_int(entry.get("source_span_start"), default=-1)
    span_end = _normalize_int(entry.get("source_span_end"), default=-1)
    if span_start >= 0:
        item["source_span_start"] = span_start
    if span_end >= 0:
        item["source_span_end"] = span_end
    overlap_score = _normalize_int(entry.get("claim_overlap_score"), default=0, min_value=0)
    if overlap_score > 0:
        item["verified_claim_overlap_score"] = overlap_score
    # P0-4 (diagnostic-only): propagate the 5-class negative_evidence_type label
    # from the quote-bank entry to the evidence item so offline audits can read
    # it without re-classifying. No flow effect.
    neg_type = str(entry.get("negative_evidence_type") or "").strip()
    existing_neg_type = str(item.get("negative_evidence_type") or "").strip()
    if (
        neg_type
        and existing_neg_type in ACTIONABLE_NEGATIVE_EVIDENCE_TYPES
        and neg_type not in ACTIONABLE_NEGATIVE_EVIDENCE_TYPES
    ):
        pass
    elif neg_type:
        item["negative_evidence_type"] = neg_type
    bucket = str(entry.get("source_bucket") or "")
    if not bucket:
        return
    item["verified_source_bucket"] = bucket
    if bucket == "table_or_figure":
        item["support_source_bucket"] = "table_or_figure"
    elif bucket == "ablation":
        item["support_source_bucket"] = "ablation"
    elif bucket == "comparison":
        item["support_source_bucket"] = "result_or_experiment"
    elif bucket == "results":
        item["support_source_bucket"] = "result_or_experiment"
    elif bucket == "method":
        item["support_source_bucket"] = "method_or_approach"
    elif bucket == "theory_or_proof":
        item["support_source_bucket"] = "method_or_approach"
    elif bucket == "abstract":
        item["support_source_bucket"] = "abstract"
    elif bucket == "negative_or_gap":
        item["support_source_bucket"] = "limitation_or_gap"
    elif bucket == "candidate_window":
        item["support_source_bucket"] = "limitation_or_gap"
    elif bucket == "conclusion":
        item["support_source_bucket"] = "conclusion_or_discussion"
    elif bucket == "claim_match" and not item.get("support_source_bucket"):
        item["support_source_bucket"] = _evidence_source_bucket(item)
    if not item.get("support_role"):
        role_hint = str(entry.get("support_role_hint") or "").strip()
        if role_hint:
            item["support_role"] = role_hint


def _verified_claim_overlap_score(evidence: Dict[str, Any]) -> int:
    return _normalize_int(evidence.get("verified_claim_overlap_score"), default=0, min_value=0)


def _has_verified_claim_overlap_support(evidence: Dict[str, Any], *, min_score: int = 1) -> bool:
    if _verified_claim_overlap_score(evidence) < min_score:
        return False
    source_bucket = str(evidence.get("support_source_bucket") or evidence.get("verified_source_bucket") or "")
    if source_bucket in {"abstract", "negative_or_gap", "limitation_or_gap"}:
        return False
    return True


def _select_claim_overlap_quote_bank_entry(
    state: Dict[str, Any],
    item: Dict[str, Any],
    quote_bank: Sequence[Dict[str, Any]],
) -> Optional[Dict[str, Any]]:
    if str(item.get("stance") or "") not in {"supports", "partially_supports"}:
        return None
    if _evidence_has_negative_intent(item):
        return None
    binding_status = str(item.get("binding_status") or "").strip()
    if binding_status not in {"", "unchecked", "bound_real_claim"}:
        return None
    claim_id = str(item.get("claim_id") or "")
    if not claim_id or claim_id not in _real_claim_ids_from_state(state or {}):
        return None
    claim_text = _claim_text_for_evidence(state or {}, claim_id)
    evidence_text = str(item.get("evidence") or "")
    candidates: List[Tuple[int, float, int, int, Dict[str, Any]]] = []
    source_priority = {"table_or_figure": 6, "results": 5, "theory_or_proof": 4, "claim_match": 3, "method": 2, "conclusion": 1}
    for index, entry in enumerate(quote_bank):
        bucket = str(entry.get("source_bucket") or "")
        if bucket in {"abstract", "negative_or_gap"}:
            continue
        quote = str(entry.get("raw_quote") or "").strip()
        if len(_quote_bank_dedupe_key(quote)) < 40:
            continue
        if _SEMANTIC_NEGATIVE_TERMS_RE.search(quote):
            continue
        overlap = _normalize_int(entry.get("claim_overlap_score"), default=0, min_value=0)
        if overlap <= 0:
            continue
        claim_score = _semantic_alignment_score(claim_text, quote)
        evidence_score = _semantic_alignment_score(evidence_text, quote)
        score = max(claim_score, evidence_score)
        if score < 0.08:
            continue
        if overlap < 2 and score < 0.14:
            continue
        candidates.append((overlap, score, source_priority.get(bucket, 0), -index, entry))
    if not candidates:
        return None
    return max(candidates, key=lambda candidate: candidate[:4])[-1]


def _semantic_alignment_score(source_text: str, quote: str) -> float:
    source_tokens = _semantic_tokens(source_text)
    quote_tokens = _semantic_tokens(quote)
    if not source_tokens or not quote_tokens:
        return 0.0
    denominator = max(1, min(len(source_tokens), len(quote_tokens), 24))
    return min(1.0, len(source_tokens & quote_tokens) / denominator)


def _evidence_has_negative_intent(evidence: Dict[str, Any]) -> bool:
    stance = str(evidence.get("stance") or "").strip().lower()
    strength = str(evidence.get("strength") or "").strip().lower()
    return (
        stance in {"contradicts", "contradict", "refutes", "refute", "weakens", "weaken", "undermines", "undermine", "partially_contradicts", "partially_refutes", "negative", "missing", "not_grounded", "unsupported", "opposes", "oppose"}
        or strength == "missing"
    )


REVIEW_NEGATIVE_VERIFIED_LABEL = "review_negative_verified"
REVIEW_NEGATIVE_ABSENCE_AUDIT_LABEL = "review_negative_absence_audit_verified"
ABSENCE_AUDIT_GROUNDING_LABEL = "paper_absence_audit_verified"
ABSENCE_AUDIT_SOURCE = "reviewer_absence_audit"
REVIEW_ISSUE_BUNDLE_SOURCE = "obligation_grounded_review_issue"
REVIEW_ISSUE_BUNDLE_STATUS = "verified_review_issue"
REVIEW_ISSUE_BUNDLE_GROUNDING_LABEL = "review_issue_bundle_verified"


def _comparison_invalidation_is_current_paper_issue(text: str) -> bool:
    """True only when a comparison-invalidation quote concerns this paper.

    Related-work prose often says a cited prior system "does not compare" to
    other methods.  That is useful motivation, but it is not a verified
    reviewer-negative against the current paper.  Evaluate the sentence that
    actually contains the comparison-invalidation phrase, rather than allowing a
    following self-anchored method sentence to launder the prior-work sentence.
    """
    value = str(text or "")
    if not value or not _SEMANTIC_COMPARISON_INVALIDATION_RE.search(value):
        return False
    segments = [
        segment.strip()
        for segment in re.split(r"\\section\{[^}]*\}|(?<=[.!?])\s+|\n{2,}", value)
        if segment and segment.strip()
    ]
    if not segments:
        segments = [value]
    for segment in segments:
        if not _SEMANTIC_COMPARISON_INVALIDATION_RE.search(segment):
            continue
        self_anchor = bool(_INTRO_NEGATIVE_SELF_ANCHOR_RE.search(segment))
        external_context = bool(_COMPARISON_INVALIDATION_EXTERNAL_CONTEXT_RE.search(segment))
        plain_not_compare = bool(_COMPARISON_INVALIDATION_PLAIN_NOT_COMPARE_RE.search(segment))
        current_protocol = bool(_COMPARISON_INVALIDATION_CURRENT_PROTOCOL_RE.search(segment))
        if external_context and not self_anchor:
            continue
        if plain_not_compare and not (self_anchor or current_protocol):
            continue
        if self_anchor or current_protocol:
            return True
    return False

_REVIEW_NEGATIVE_POSITIVE_CONTEXT_RE = re.compile(
    r"\b(?:address(?:es|ed|ing)?|overcom(?:e|es|ing)|mitigat(?:e|es|ing)|solve(?:s|d|ing)?|"
    r"tackl(?:e|es|ed|ing)|alleviat(?:e|es|ed|ing))\b[^.!?]{0,100}\b(?:limitation|limitations|challenge|challenges|issue|issues|problem|problems)\b|"
    r"\b(?:present|propose|introduce|develop)\b[^.!?]{0,80}\b(?:novel|new|effective|efficient|robust|viewpoint|approach|method)\b|"
    r"\b(?:outperform(?:s|ed|ing)?|improv(?:e|es|ed|ement)|enhanc(?:e|es|ed|ing)|boost(?:s|ed|ing)?|"
    r"achiev(?:e|es|ed|ing)|guarantee(?:s|d)?|superior)\b|"
    r"\b(?:strongest|strong|competitive|best(?:-performing)?)\s+baseline\b",
    re.IGNORECASE,
)
_REVIEW_NEGATIVE_PRIOR_WORK_RE = re.compile(
    r"\b(?:prior work|previous work|existing method|existing methods|related work|baseline method|baseline methods|"
    r"et al\.|\((?:19|20)\d{2}[a-z]?\)|(?:19|20)\d{2}\))\b[^.!?]{0,160}"
    r"\b(?:introduc(?:e|es|ed)|propos(?:e|es|ed)|present(?:s|ed)?|address(?:es|ed|ing)?|"
    r"overcom(?:e|es|ing)|fail(?:s|ed)?|lack(?:s|ed|ing)?|do(?:es)? not)\b"
    # Codex-audit fix: LaTeX \cite{...}/\citep/\citet references are external-work context
    # too. Related-work criticism of a CITED paper (e.g. "\cite{x2024} ... only provides ...
    # and does not compare ...") is a prior_work_limitation, NOT a verified negative against
    # THIS paper. Requires a criticism verb after the citation so positive "Following
    # \cite{x}, we adopt ..." adoption is unaffected.
    r"|\\cite[tp]?\{[^}]*\}[^.!?]{0,160}"
    r"\b(?:introduc(?:e|es|ed)|propos(?:e|es|ed)|present(?:s|ed)?|provid(?:e|es|ed)|"
    r"address(?:es|ed|ing)?|overcom(?:e|es|ing)|fail(?:s|ed)?|lack(?:s|ed|ing)?|"
    r"do(?:es)? not|only\s+(?:provid|evaluat|consider|focus|support))\b",
    re.IGNORECASE,
)
_REVIEW_NEGATIVE_RESOURCE_CONTEXT_RE = re.compile(
    r"\b(?:computational|compute|resource|resources|memory|budget)\b[^.!?]{0,80}"
    r"\b(?:limitation|limitations|constraint|constraints|limited|prioriti[sz]e|prioriti[sz]ed|select|choose|chosen)\b|"
    r"\b(?:due to|because of|given)\b[^.!?]{0,80}\b(?:resource|compute|computational|budget)\b",
    re.IGNORECASE,
)
_REVIEW_NEGATIVE_CONCRETE_GAP_RE = re.compile(
    r"\b(?:we|our|this paper|this work|the paper|the method|the model|the system|the experiments?|the evaluation)\b"
    r"[^.!?]{0,140}\b(?:do(?:es)? not|did not|cannot|not|no|without|lack(?:s|ed|ing)?|missing|absent|"
    r"insufficient|limited|only evaluated|not evaluated|not compared|not provided|not reported|not included|not tested|not released)\b|"
    r"\b(?:evaluation|experiment|experiments|comparison|baseline|baselines|ablation|implementation|hyperparameter|"
    r"hyperparameters|code|runtime|latency|memory|robustness|generalization|generalisation|output quality|reproducibility)\b"
    r"[^.!?]{0,100}\b(?:not|no|without|missing|absent|limited|insufficient|omitted|unavailable|not evaluated|not compared|"
    r"not provided|not reported|not included|not tested|not released)\b",
    re.IGNORECASE,
)
_REVIEW_NEGATIVE_SCOPE_RELATION_RE = re.compile(
    r"\b(?:only evaluated on|only tested on|limited to|restricted to|only applies|only applicable|only valid|"
    r"does not generalize|does not generalise|out of scope|assumes?|assumption requires?|requires? [^.!?]{0,60}assumption)\b",
    re.IGNORECASE,
)
_REVIEW_NEGATIVE_BROAD_CLAIM_RE = re.compile(
    r"\b(?:general|generali[sz]e|robust|robustness|across|various|diverse|all|any|broad|universal|"
    r"state-of-the-art|sota|outperform|scalable|transfer|out-of-domain|cross-domain)\b",
    re.IGNORECASE,
)
_REVIEW_NEGATIVE_AUTHOR_LIMITATION_RE = re.compile(
    r"\b(?:limitation|limitations|limited|future work|threats? to validity|we leave|we plan|we will|"
    r"we hope|we intend|we focus|out of scope)\b|"
    r"\b(?:we|our|this paper|this work)\b[^.!?]{0,100}\b"
    r"(?:do not|does not|did not|cannot|don't|doesn't)\s+"
    r"(?:evaluate|report|compare|include|test|measure|judge|assess|provide|release)\b",
    re.IGNORECASE,
)


def _negative_anchor_is_prior_work_context(text: str) -> bool:
    """Detect negative-looking sentences whose target is external work."""
    value = str(text or "")
    if not value:
        return False
    segments = [
        segment.strip()
        for segment in re.split(r"\\section\{[^}]*\}|(?<=[.!?])\s+|\n{2,}", value)
        if segment and segment.strip()
    ] or [value]
    prior_negative = False
    current_paper_negative = False
    for segment in segments:
        has_negative_anchor = bool(
            _SEMANTIC_NEGATIVE_TERMS_RE.search(segment)
            or _SEMANTIC_COMPARISON_INVALIDATION_RE.search(segment)
            or _COMPARISON_INVALIDATION_PLAIN_NOT_COMPARE_RE.search(segment)
        )
        if not has_negative_anchor:
            continue
        self_anchor = bool(_INTRO_NEGATIVE_SELF_ANCHOR_RE.search(segment))
        external_context = bool(
            _REVIEW_NEGATIVE_PRIOR_WORK_RE.search(segment)
            or _COMPARISON_INVALIDATION_EXTERNAL_CONTEXT_RE.search(segment)
        )
        current_gap = bool(_REVIEW_NEGATIVE_CONCRETE_GAP_RE.search(segment)) and not external_context
        if external_context and not self_anchor:
            prior_negative = True
            continue
        if self_anchor or current_gap:
            current_paper_negative = True
    return prior_negative and not current_paper_negative

# Codex-audit fix: problem-motivation / addressed-by-our-method structure.
# A first-person observation of a difficulty arising under the paper's OWN method or
# setting (e.g. "we found increased heterogeneity when training with our distilled data")
# is an author motivation that the paper then solves — NOT a reviewer-discovered final
# flaw. Absent an independent concrete reviewer gap, such a quote must not auto-verify
# as a negative concern. Deliberately requires the paper's own-method context
# (our/proposed/distilled/...) so criticism of a baseline/prior work is unaffected.
_REVIEW_NEGATIVE_PROBLEM_MOTIVATION_RE = re.compile(
    r"\b(?:we|our)\b[^.!?]{0,30}\b(?:found|find|observ\w+|notic\w+|identif\w+|reveal\w+|see|saw|show\w*)\b"
    r"[^.!?]{0,140}\b(?:when|while|with|using|after|during)\b[^.!?]{0,90}"
    r"\b(?:our|proposed|distilled|our method|our model|our approach|our framework|the proposed|our setting|our training)\b",
    re.IGNORECASE,
)
# Route A: "the paper's own method underperforms a baseline/SOTA" — a result that
# contradicts the paper's headline claim (data contradicts the claim). This is a genuine
# reviewer-discovered negative, distinct from author-reported ablation/variant/control
# comparisons (which compare the paper's OWN internal configs, not against a baseline/SOTA).
_OWN_METHOD_WORSE_THAN_BASELINE_RE = re.compile(
    r"(?:"
    # own method + underperform (a shortfall verb that is intrinsically negative)
    r"\b(?:our|proposed|the proposed|the method|our method|our model|our approach|our framework|the model|the approach|method|model)\b"
    r"[^.!?]{0,60}\bunderperform\w*"
    r"|"
    # own method + worse/lower/losing/falls-short THAN/TO a baseline / SOTA
    r"\b(?:our|proposed|the proposed|the method|our method|our model|our approach|our framework|the model|the approach)\b[^.!?]{0,80}"
    r"\b(?:worse|lower|losing|loses|lost|inferior|fall[s]? short|fails? to (?:match|beat|outperform))\b[^.!?]{0,50}"
    r"\b(?:than|to|compared|versus|vs\.?|relative to|below)\b[^.!?]{0,40}"
    r"\b(?:baseline|baselines|state-of-the-art|state of the art|sota|strongest|prior (?:work|method)|existing (?:method|methods|work))\b"
    r"|"
    # a baseline / SOTA is reported above the paper's own method
    r"\b(?:baseline|baselines|state-of-the-art|state of the art|sota|strongest|prior (?:method|work)|existing (?:method|methods))\b[^.!?]{0,55}"
    r"\b(?:higher|better|outperform\w*|superior|exceed\w*|surpass\w*)\b"
    r"|"
    # a current-paper system/component yields a less favorable result than the baseline
    r"\b(?:our|proposed|the proposed|the method|our method|our model|our approach|our framework|"
    r"the model|the approach|the system|our system|federated model|secure aggregator)\b[^.!?]{0,100}"
    r"\b(?:less\s+favo[u]?rable|worse|lower|inferior)\b[^.!?]{0,50}"
    r"\b(?:than|to|compared|versus|vs\.?|relative to|below)\b[^.!?]{0,40}"
    r"\b(?:baseline|baselines|baseline system|state-of-the-art|state of the art|sota|strongest|"
    r"prior (?:work|method)|existing (?:method|methods|work))\b"
    r")",
    re.IGNORECASE,
)


def _review_negative_assessment(
    label: str,
    reason: str,
    relation_score: float,
) -> Dict[str, Any]:
    return {
        "review_negative_checked": True,
        "review_negative_label": label,
        "review_negative_reason": reason,
        "review_negative_relation_score": round(relation_score, 4),
    }


_LOWER_IS_BETTER_METRIC_RE = re.compile(
    r"\b(?:eer|error\s+rate|word\s+error\s+rate|wer|character\s+error\s+rate|cer|"
    r"loss|mae|rmse|mse|fpr|fnr|false\s+positive\s+rate|false\s+negative\s+rate|"
    r"perplexity|latency|runtime|time|cost)\b",
    re.IGNORECASE,
)
_METRIC_IMPROVEMENT_CUE_RE = re.compile(
    r"\b(?:improv(?:e|es|ed|ement)|relative\s+improvement|reduc(?:e|es|ed|tion)|"
    r"decreas(?:e|es|ed)|lower|smaller|better|outperform(?:s|ed)?)\b",
    re.IGNORECASE,
)
_EXPLICIT_METRIC_IMPROVEMENT_CUE_RE = re.compile(
    r"\b(?:improv(?:e|es|ed|ement)|relative\s+improvement|reduc(?:e|es|ed|tion)|"
    r"decreas(?:e|es|ed))\b",
    re.IGNORECASE,
)


def _review_negative_quote_is_positive_metric_improvement(quote: str, neg_type: str) -> bool:
    """Reject lower-is-better improvements mislabeled as result mismatches."""

    if _canonical_negative_evidence_type(neg_type) not in {
        "result_claim_mismatch",
        "negative_result",
        "direct_contradiction",
    }:
        return False
    text = str(quote or "")
    if not text or not _LOWER_IS_BETTER_METRIC_RE.search(text):
        return False
    if _METRIC_IMPROVEMENT_CUE_RE.search(text):
        return True
    return bool(
        re.search(
            r"\b(?:from|baseline)\s+\d+(?:\.\d+)?\s*%?\s+(?:to|->|→)\s+\d+(?:\.\d+)?\s*%?",
            text,
            re.IGNORECASE,
        )
        and re.search(r"\b(?:lower|reduc|improv|better)\b", text, re.IGNORECASE)
    )


def _review_negative_quote_has_explicit_metric_improvement_context(quote: str) -> bool:
    text = str(quote or "")
    return bool(_LOWER_IS_BETTER_METRIC_RE.search(text) and _EXPLICIT_METRIC_IMPROVEMENT_CUE_RE.search(text))


def _review_negative_quote_is_positive_baseline_comparison_support(quote: str) -> bool:
    """Reject ordinary baseline-comparison result prose mislabeled as negative."""

    text = str(quote or "")
    if not text:
        return False
    if _OWN_METHOD_WORSE_THAN_BASELINE_RE.search(text):
        return False
    if _REVIEW_NEGATIVE_CONCRETE_GAP_RE.search(text):
        return False
    if _SEMANTIC_NEGATIVE_TERMS_RE.search(text):
        return False
    has_baseline = bool(re.search(r"\bbaseline(?:s)?\b", text, re.IGNORECASE))
    has_comparison = bool(
        re.search(
            r"\b(?:compare[sd]?|comparison|compared|performance\s+comparison|"
            r"evaluate[sd]?|evaluation|benchmark(?:s)?|result(?:s)?)\b",
            text,
            re.IGNORECASE,
        )
    )
    has_paper_self_anchor = bool(
        re.search(
            r"\b(?:we|our|ours|in\s+our\s+study|this\s+(?:paper|work|study)|"
            r"the\s+proposed\s+(?:method|model|approach|framework))\b",
            text,
            re.IGNORECASE,
        )
    )
    if not (has_baseline and has_comparison and has_paper_self_anchor):
        return False
    return bool(
        re.search(
            r"\b(?:use[sd]?|utili[sz]e[sd]?|adopt(?:ed)?|include[sd]?|set)\b"
            r"[^.!?]{0,90}\bbaseline(?:s)?\b|"
            r"\bbaseline(?:s)?\b[^.!?]{0,140}\b(?:compare[sd]?|comparison|"
            r"evaluate[sd]?|benchmark(?:s)?|result(?:s)?)\b|"
            r"\b(?:compare[sd]?|comparison|evaluate[sd]?|benchmark(?:s)?|result(?:s)?)\b"
            r"[^.!?]{0,140}\bbaseline(?:s)?\b",
            text,
            re.IGNORECASE,
        )
    )


def _has_review_negative_semantic_intent(evidence: Dict[str, Any]) -> bool:
    """Recognize concrete current-paper gaps even when model stance is wrong."""
    if not isinstance(evidence, dict):
        return False
    quote = str(evidence.get("raw_quote") or evidence.get("evidence") or "")
    if quote and _REVIEW_NEGATIVE_AUTHOR_LIMITATION_RE.search(quote):
        return False
    if quote and _negative_anchor_is_prior_work_context(quote):
        return False
    if quote and _comparison_invalidation_is_current_paper_issue(quote):
        return True
    if _evidence_has_negative_intent(evidence):
        return True
    neg_type = _negative_evidence_type_for_record(evidence)
    if neg_type not in TRUE_PAPER_NEGATIVE_EVIDENCE_TYPES:
        return False
    if not _REVIEW_NEGATIVE_CONCRETE_GAP_RE.search(quote):
        return False
    if _REVIEW_NEGATIVE_POSITIVE_CONTEXT_RE.search(quote):
        return False
    if _negative_anchor_is_prior_work_context(quote):
        return False
    if _REVIEW_NEGATIVE_AUTHOR_LIMITATION_RE.search(quote):
        return False
    return True


def _comparison_invalidation_negative_override_applies(
    state: Dict[str, Any],
    evidence: Dict[str, Any],
) -> bool:
    if not isinstance(evidence, dict):
        return False
    quote = str(evidence.get("raw_quote") or evidence.get("evidence") or "")
    if not quote or not _comparison_invalidation_is_current_paper_issue(quote):
        return False
    if str(evidence.get("verified_grounding_label") or "") not in VERIFIED_PAPER_GROUNDED_LABELS:
        return False
    if _REVIEW_NEGATIVE_AUTHOR_LIMITATION_RE.search(quote):
        return False
    if _negative_anchor_is_prior_work_context(quote):
        return False
    if not _is_real_paper_claim_id_for_negative(evidence.get("claim_id")):
        return False
    return True


def _apply_comparison_invalidation_negative_override(
    state: Dict[str, Any],
    evidence: Dict[str, Any],
) -> None:
    """Correct a narrow model-labeling failure for comparison-invalidation quotes.

    MiMo sometimes finds a real paper quote saying a protocol / hyperparameter
    cannot be used to compare across methods, but still emits the row as
    ``stance=supports`` and ``negative_evidence_type=generic_gap``.  The quote
    itself is the artifact: once it is paper-grounded, it should be evaluated as
    an actionable reviewer concern rather than as positive support.  This helper
    only rewrites that exact, grounded pattern; it does not manufacture
    negatives from ungrounded text or author/prior-work limitations.
    """
    if not _comparison_invalidation_negative_override_applies(state or {}, evidence):
        return

    neg_type = _negative_evidence_type_for_record(evidence)
    if neg_type in {"", "generic_gap", "neutral_control_context"}:
        evidence["negative_evidence_type"] = "evaluation_protocol_risk"
        evidence["negative_evidence_type_decision_view_reason"] = "comparison_invalidation_type_derived"
    stance = str(evidence.get("stance") or "").strip().lower()
    if stance in {"", "supports", "support", "partially_supports", "partially_support"}:
        evidence["comparison_invalidation_original_stance"] = str(evidence.get("stance") or "")
        evidence["stance"] = "contradicts"
    if str(evidence.get("semantic_grounding_label") or "") in {
        "",
        "semantic_support_verified",
        "semantic_support_weak",
        "semantic_mismatch",
    }:
        reasons = list(evidence.get("semantic_grounding_reasons") or [])
        if "comparison_invalidation_verified" not in reasons:
            reasons.append("comparison_invalidation_verified")
        evidence["semantic_grounding_label"] = "semantic_negative_verified"
        evidence["semantic_grounding_reasons"] = reasons
        evidence["quote_evidence_semantic_mismatch"] = False
    evidence["comparison_invalidation_negative_override"] = True


def _assess_review_negative_relation(state: Dict[str, Any], evidence: Dict[str, Any]) -> Dict[str, Any]:
    """Decide whether a grounded negative-looking quote is a reviewer flaw.

    Paper quote existence is a grounding fact.  This gate is the separate review
    relation: the quote must weaken a target claim or ground a concrete reviewer
    concern.  Author self-limitations, prior-work limitations, and positive
    "we address limitations" text are not verified negative evidence.
    """

    quote = str(evidence.get("raw_quote") or evidence.get("evidence") or "")
    claim_text = _claim_text_for_evidence(state or {}, str(evidence.get("claim_id") or ""))
    evidence_text = str(evidence.get("evidence") or "")
    source_text = " ".join(
        str(evidence.get(key) or "")
        for key in ("source", "source_locator", "support_source_bucket", "verified_source_bucket")
    )
    relation_text = " ".join([claim_text, evidence_text])
    relation_score = _semantic_alignment_score(relation_text, quote)
    neg_type = _negative_evidence_type_for_record(evidence)
    if _review_negative_quote_is_positive_metric_improvement(quote, neg_type):
        return _review_negative_assessment(
            "not_negative_evidence",
            "lower_is_better_metric_improvement_support",
            relation_score,
        )
    if _review_negative_quote_is_positive_baseline_comparison_support(quote):
        return _review_negative_assessment(
            "positive_or_neutral_support",
            "quote_describes_baseline_comparison_support",
            relation_score,
        )
    if _SEMANTIC_ABSENCE_EXCERPT_LIMIT_RE.search(
        " ".join([evidence_text, str(evidence.get("agent_raw_quote") or "")])
    ):
        return _review_negative_assessment(
            "insufficient_claim_relation",
            "absence_claim_limited_to_quote_or_excerpt",
            relation_score,
        )

    if not (_has_review_negative_semantic_intent(evidence) or neg_type in NEGATIVE_EVIDENCE_TYPES_ALL):
        return _review_negative_assessment("not_negative_evidence", "record_has_no_negative_intent", relation_score)
    if str(evidence.get("verified_grounding_label") or "") not in VERIFIED_PAPER_GROUNDED_LABELS:
        return _review_negative_assessment("insufficient_paper_grounding", "quote_not_paper_grounded", relation_score)
    semantic_label = str(evidence.get("semantic_grounding_label") or "")
    if semantic_label == "semantic_author_limitation":
        reason = (
            f"{neg_type}_is_author_self_limitation"
            if neg_type
            else "author_scope_or_future_work_note"
        )
        return _review_negative_assessment("author_limitation_only", reason, relation_score)
    if semantic_label != "semantic_negative_verified":
        return _review_negative_assessment("insufficient_semantic_negative", "semantic_negative_verification_missing", relation_score)
    if neg_type in {"neutral_control_context", "generic_gap", "bibliographic_or_title_noise", "neutral_instruction_noise"}:
        return _review_negative_assessment("insufficient_claim_relation", f"negative_type_{neg_type}_not_review_negative", relation_score)
    if neg_type == "missing_ablation" and _paper_has_ablation_counterevidence_for_missing_claim(
        state or {},
        evidence,
        claim_text,
    ):
        return _review_negative_assessment(
            "insufficient_claim_relation",
            "existing_ablation_counterevidence_in_paper",
            relation_score,
        )

    quote_l = quote.lower()
    self_anchor = bool(_INTRO_NEGATIVE_SELF_ANCHOR_RE.search(quote))
    author_limitation = bool(_REVIEW_NEGATIVE_AUTHOR_LIMITATION_RE.search(quote_l))
    concrete_gap = bool(_REVIEW_NEGATIVE_CONCRETE_GAP_RE.search(quote))
    broad_claim = bool(_REVIEW_NEGATIVE_BROAD_CLAIM_RE.search(claim_text))
    scope_relation = bool(_REVIEW_NEGATIVE_SCOPE_RELATION_RE.search(quote))
    prior_work_negative_context = _negative_anchor_is_prior_work_context(quote)
    table_scope_absence_negative = _is_table_scope_absence_negative(
        state,
        evidence,
        quote,
        claim_text,
        evidence_text,
        str(evidence.get("source_locator") or ""),
    )
    comparison_invalidation = bool(_comparison_invalidation_is_current_paper_issue(quote)) and (
        neg_type in {
            "missing_baseline",
            "unfair_or_weak_baseline",
            "insufficient_evaluation",
            "evaluation_protocol_risk",
            "result_claim_mismatch",
            "scope_overclaim",
        }
        or bool(
            re.search(
                r"\b(compare|comparison|cross[- ]method|across\s+methods?|between\s+methods?|"
                r"baseline|baselines|sota|state[- ]of[- ]the[- ]art)\b",
                " ".join([claim_text, evidence_text, quote]),
                re.IGNORECASE,
            )
        )
    )

    own_method_underperforms = bool(_OWN_METHOD_WORSE_THAN_BASELINE_RE.search(quote))
    direct_contradiction_phrase = bool(_NEG_TYPE_DIRECT_CONTRADICTION_RE.search(quote))
    if _REVIEW_NEGATIVE_POSITIVE_CONTEXT_RE.search(quote):
        if _review_negative_quote_has_explicit_metric_improvement_context(quote):
            return _review_negative_assessment(
                "positive_or_neutral_support",
                "quote_describes_addressing_or_positive_result",
                relation_score,
            )
        if not (
            own_method_underperforms
            or concrete_gap
            or table_scope_absence_negative
            or comparison_invalidation
            or direct_contradiction_phrase
        ):
            return _review_negative_assessment("positive_or_neutral_support", "quote_describes_addressing_or_positive_result", relation_score)
    if prior_work_negative_context:
        return _review_negative_assessment("prior_work_limitation", "quote_describes_prior_or_external_work", relation_score)
    if _REVIEW_NEGATIVE_RESOURCE_CONTEXT_RE.search(quote):
        if not concrete_gap:
            return _review_negative_assessment("resource_or_scope_context", "resource_context_without_current_paper_gap", relation_score)

    # Route A: a paper quote is a reviewer-discovered negative ONLY if it contradicts the
    # paper's own claim — (1) the paper's own method underperforms a baseline/SOTA ("data
    # contradicts the headline claim"), (2) a concrete reviewer evidence gap on THIS paper
    # (a required baseline/ablation/evaluation/comparison is missing/not done), or (3) a
    # broad claim is left scope-restricted. Author-reported ablation/variant/control/
    # tradeoff results (negative-looking but supporting the paper's OWN argument) match none
    # of these and fall through to paper_observation. Deterministic missing-evidence
    # coverage is also carried separately by the Route-3 verified_coverage_gap.
    contradicts_paper_claim = (
        own_method_underperforms
        or concrete_gap
        or table_scope_absence_negative
        or comparison_invalidation
        or direct_contradiction_phrase
        or (broad_claim and scope_relation)
    )

    if neg_type in TRUE_PAPER_NEGATIVE_EVIDENCE_TYPES or neg_type in {"scope_overclaim", "scope_limitation"}:
        if author_limitation:
            return _review_negative_assessment("author_limitation_only", f"{neg_type}_is_author_self_limitation", relation_score)
        if _REVIEW_NEGATIVE_PROBLEM_MOTIVATION_RE.search(quote) and not contradicts_paper_claim:
            return _review_negative_assessment("author_limitation_only", f"{neg_type}_is_problem_motivation_addressed_by_method", relation_score)
        if contradicts_paper_claim:
            reason = (
                "own_method_underperforms_baseline"
                if own_method_underperforms
                else "table_scope_absence_weakens_claim"
                if table_scope_absence_negative
                else "comparison_invalidation_weakens_claim"
                if comparison_invalidation
                else f"{neg_type}_weakens_overclaimed_paper_claim"
            )
            return _review_negative_assessment(REVIEW_NEGATIVE_VERIFIED_LABEL, reason, relation_score)
        return _review_negative_assessment("insufficient_claim_relation", f"{neg_type}_is_paper_observation_not_claim_contradiction", relation_score)

    return _review_negative_assessment("insufficient_claim_relation", "no_review_negative_relation", relation_score)


def _apply_review_negative_relation_label(state: Dict[str, Any], evidence: Dict[str, Any]) -> None:
    if not isinstance(evidence, dict):
        return
    if not (_has_review_negative_semantic_intent(evidence) or str(evidence.get("negative_evidence_type") or "").strip()):
        return
    evidence.update(_assess_review_negative_relation(state or {}, evidence))


def _review_negative_label_for_record(item: Dict[str, Any], state: Dict[str, Any]) -> str:
    if not isinstance(item, dict):
        return ""
    existing_label = str(item.get("review_negative_label") or "").strip()
    if existing_label:
        if _review_negative_quote_is_positive_metric_improvement(
            str(item.get("raw_quote") or item.get("evidence") or ""),
            _negative_evidence_type_for_record(item),
        ):
            return str(_assess_review_negative_relation(state or {}, item).get("review_negative_label") or "")
        if existing_label == REVIEW_NEGATIVE_ABSENCE_AUDIT_LABEL:
            return existing_label if _is_reviewer_absence_audit_evidence_record(item, state or {}) else ""
        if existing_label == REVIEW_NEGATIVE_VERIFIED_LABEL:
            quote = str(item.get("raw_quote") or item.get("evidence") or "")
            semantic_reasons = {
                str(reason)
                for reason in item.get("semantic_grounding_reasons") or []
            }
            high_risk_absence_label = bool(
                _negative_anchor_is_prior_work_context(quote)
                or str(item.get("review_negative_reason") or "") == "table_scope_absence_weakens_claim"
                or "table_scope_absence_verified" in semantic_reasons
            )
            if high_risk_absence_label:
                # Do not let stale high-risk runtime labels bypass the current
                # relation gate. This lets dashboard re-audits remove false
                # positives after guard tightening while preserving direct
                # contradiction / negative-result records.
                reassessed = str(_assess_review_negative_relation(state or {}, item).get("review_negative_label") or "").strip()
                if reassessed:
                    return reassessed
        return existing_label
    if str(item.get("semantic_grounding_label") or "").strip() != "semantic_negative_verified":
        return ""
    return str(_assess_review_negative_relation(state or {}, item).get("review_negative_label") or "")


def _is_review_negative_verified_evidence_record(item: Dict[str, Any], state: Dict[str, Any]) -> bool:
    return _review_negative_label_for_record(item, state) == REVIEW_NEGATIVE_VERIFIED_LABEL


# P0-1 Medium Promotion Calibration thresholds (semantic_alignment_score):
#   - method-depth (moderate): score >= METHOD_PROMOTION_STRONG_MIN_SCORE → strong;
#     METHOD_PROMOTION_MODERATE_MIN_SCORE <= score < strong-threshold → held at moderate;
#     score < moderate-threshold → held at moderate (low-score). All non-strong
#     outcomes preserve the medium/moderate tier so that
#     `_support_admission_tier` can surface them as `verified_moderate`.
#   - deep (results / table_or_figure / theory): score >= DEEP_PROMOTION_STRONG_MIN_SCORE → strong;
#     score < threshold → held at moderate.
METHOD_PROMOTION_STRONG_MIN_SCORE = 0.7
METHOD_PROMOTION_MODERATE_MIN_SCORE = 0.6
DEEP_PROMOTION_STRONG_MIN_SCORE = 0.6
DEEP_PROMOTION_NEAR_MISS_MIN_SCORE = 0.55
METHOD_PROMOTION_NEAR_MISS_MIN_SCORE = 0.65

# Mainline-Final-Integrated P0-1: final-strong guard threshold.  A support
# that the hygiene view re-scores below this number is held at
# ``verified_moderate`` even if it carried ``strength=strong`` from the live
# state.  Promotion-time scores may be higher than the hygiene re-score because
# ``build_decision_hygiene_view`` runs semantic grounding with the full final
# evidence pool; the guard catches the cases where the re-score drops below
# the calibrated promotion floor.
FINAL_STRONG_MIN_SCORE = 0.6

# Mainline-Final-Integrated P0-1: bucket / locator signals that mark a quote
# as a Limitation / Gap / Negative-evidence anchor.  Such anchors should
# never be admitted as positive strong support: they are at best flaw
# anchors.  The two source buckets are emitted by
# ``support_quality.evidence_section_bucket`` (``limitation_or_gap``) and
# by the quote-bank canonicalisation path (``negative_or_gap``).  The
# regex covers the locators that the runner writes when it canonicalises a
# negative quote-bank entry into a support row (see
# ``_negative_quote_bank_salvage_payload`` and the locator strings produced
# by ``_apply_quote_bank_entry_metadata``).
NEGATIVE_SUPPORT_BUCKETS = frozenset({"negative_or_gap", "limitation_or_gap"})
_NEGATIVE_SUPPORT_LOCATOR_RE = re.compile(
    r"\b(limitation|gap|negative\s+evidence|negative\s+excerpt|missing\s+comparison|no\s+ablation)\b",
    re.IGNORECASE,
)
# Buckets whose verified table/figure/theorem anchors may legitimately carry a
# low semantic_alignment_score (e.g. a table number with sparse textual
# overlap).  The guard exempts these only when grounding is paper_grounded_exact
# and the verified quote match type signals an exact reproduction.
_TABLE_OR_RESULT_ANCHOR_BUCKETS = frozenset(
    {"table_or_figure", "result_or_experiment", "ablation", "comparison", "theory_or_proof"}
)


def _evidence_negative_locator_or_bucket_signal(evidence: Dict[str, Any]) -> bool:
    """Return True iff the support is anchored on a Limitation / Gap / negative
    quote bucket or locator.

    The check covers ``support_source_bucket`` (the original Evidence Agent
    label) and ``quote_bank_claim_overlap_fallback_source_bucket`` (the bucket
    that was canonicalised into this support via the quote-bank claim-overlap
    fallback path).  It also matches the ``source_locator`` string against the
    deterministic Limitation / Gap regex so quotes copied verbatim from the
    paper's limitation section are recognised even when the Evidence Agent
    did not emit the negative bucket label.
    """
    if not isinstance(evidence, dict):
        return False
    bucket = str(evidence.get("support_source_bucket") or "").strip().lower()
    if bucket in NEGATIVE_SUPPORT_BUCKETS:
        return True
    fallback_bucket = str(
        evidence.get("quote_bank_claim_overlap_fallback_source_bucket") or ""
    ).strip().lower()
    if fallback_bucket in NEGATIVE_SUPPORT_BUCKETS:
        return True
    locator = str(evidence.get("source_locator") or "")
    if _NEGATIVE_SUPPORT_LOCATOR_RE.search(locator):
        return True
    return False


def _has_specific_or_empirical_locator_signal(evidence: Dict[str, Any]) -> bool:
    """Return True for verified supports with concrete empirical/method anchors.

    This is intentionally narrower than a global score-threshold relaxation: a
    near-miss moderate support only upgrades when it is paper-grounded,
    semantically verified, non-abstract, and anchored by a specific locator or
    by an empirical/table source bucket.
    """
    locator = str((evidence or {}).get("source_locator") or "")
    if _is_specific_locator(locator):
        return True
    if bool((evidence or {}).get("source_locator_specific")):
        return True
    declared_bucket = str((evidence or {}).get("support_source_bucket") or "").strip()
    decision_bucket = _decision_support_source_bucket(evidence or {})
    return declared_bucket in _TABLE_OR_RESULT_ANCHOR_BUCKETS or decision_bucket in _TABLE_OR_RESULT_ANCHOR_BUCKETS


def _verified_moderate_near_miss_promotion_path(evidence: Dict[str, Any]) -> str:
    """Classify safe near-miss verified moderate supports.

    The path is used both by the promotion rule and by dashboards. It avoids
    reviving abstract, negative, shallow, unverified, or semantic-mismatch
    rows; only concrete deep/method supports just below the strong threshold
    qualify.
    """
    if not isinstance(evidence, dict):
        return ""
    if str(evidence.get("stance") or "") not in {"supports", "partially_supports"}:
        return ""
    if _evidence_has_negative_intent(evidence) or _evidence_negative_locator_or_bucket_signal(evidence):
        return ""
    if str(evidence.get("verified_grounding_label") or "") not in VERIFIED_PAPER_GROUNDED_LABELS:
        return ""
    if str(evidence.get("semantic_grounding_label") or "") != "semantic_support_verified":
        return ""
    declared_bucket = str(evidence.get("support_source_bucket") or "").strip()
    decision_bucket = _decision_support_source_bucket(evidence)
    if declared_bucket == "abstract" or decision_bucket == "abstract":
        return ""
    if not _has_specific_or_empirical_locator_signal(evidence):
        return ""
    score = _normalize_float(evidence.get("semantic_alignment_score"), default=0.0)
    depth = _support_depth_label(evidence)
    if depth == "deep" and DEEP_PROMOTION_NEAR_MISS_MIN_SCORE <= score < DEEP_PROMOTION_STRONG_MIN_SCORE:
        return "near_miss_verified_deep_support"
    if depth == "moderate" and METHOD_PROMOTION_NEAR_MISS_MIN_SCORE <= score < METHOD_PROMOTION_STRONG_MIN_SCORE:
        return "near_miss_verified_method_support"
    return ""


def _final_strong_guard(evidence: Dict[str, Any]) -> None:
    """Mainline-Final-Integrated P0-1: downgrade low-score / negative-anchor
    strong supports during hygiene rendering.

    Two failure modes are caught:

    - **Negative locator / bucket**: the quote is from a Limitation / Gap /
      Negative evidence section, so it is at best a contextual flaw anchor.
      Downgrade to ``strength=medium`` unconditionally and tag the
      adjustment with ``downgraded_negative_locator``.  This catches the
      cross-pollination case where the quote-bank fallback canonicalised a
      ``negative_or_gap`` bucket onto a ``stance=supports`` support row.
    - **Low semantic alignment**: the hygiene re-scored
      ``semantic_alignment_score`` is below :data:`FINAL_STRONG_MIN_SCORE`.
      Downgrade unless the support is anchored by a verified table /
      figure / theorem quote where low textual overlap is expected.  Such
      anchor exceptions still require ``verified_grounding_label`` to be
      ``paper_grounded_exact`` and the verified-quote match-type to indicate
      an exact reproduction.

    The function is idempotent and operates in place on ``evidence``.  It does
    not touch the live ReviewState; it only runs from
    :func:`_verify_evidence_grounding_against_state`, which itself is only
    invoked by :func:`build_decision_hygiene_view`.
    """
    if not isinstance(evidence, dict):
        return
    if str(evidence.get("strength") or "") != "strong":
        return
    if str(evidence.get("stance") or "") not in {"supports", "partially_supports"}:
        return

    downgrade_reason = ""
    if _evidence_negative_locator_or_bucket_signal(evidence):
        downgrade_reason = "negative_locator_strong_support_downgrade"
    else:
        score = _normalize_float(evidence.get("semantic_alignment_score"), default=0.0)
        if score < FINAL_STRONG_MIN_SCORE:
            decision_bucket = _decision_support_source_bucket(evidence)
            grounding_label = str(evidence.get("verified_grounding_label") or "")
            match_type = str(evidence.get("verified_quote_match_type") or "").lower()
            near_miss_path = _verified_moderate_near_miss_promotion_path(evidence)
            semantic_weak_promotion = bool(evidence.get("semantic_weak_promotion_used"))
            locator_type = str(evidence.get("locator_type") or evidence.get("source_locator_type") or "").strip().lower()
            if not locator_type:
                locator_type = _locator_type_from_anchor(str(evidence.get("source_locator") or ""))
            anchor_exception = (
                not semantic_weak_promotion
                and
                decision_bucket in _TABLE_OR_RESULT_ANCHOR_BUCKETS
                and locator_type in {"table", "figure", "algorithm", "theorem"}
                and grounding_label == "paper_grounded_exact"
                and match_type
                in {
                    "exact",
                    "exact_match",
                    "exact_quote",
                    "quote_bank_id_canonical",
                    "quote_bank_raw_canonical",
                }
            )
            if not anchor_exception:
                downgrade_reason = "low_score_strong_support_downgrade"

    if not downgrade_reason:
        return

    evidence["strength"] = "medium"
    evidence["final_strength_guard_downgrade_reason"] = downgrade_reason
    evidence["strength_promotion_held_at_moderate"] = True
    if evidence.get("strength_promotion_from_medium_used"):
        evidence["strength_promotion_from_medium_used"] = False
    previous = str(evidence.get("support_quality_adjustment") or "")
    adjustment = (
        "downgraded_negative_locator"
        if downgrade_reason == "negative_locator_strong_support_downgrade"
        else "downgraded_low_semantic_alignment"
    )
    evidence["support_quality_adjustment"] = (
        f"{previous};{adjustment}" if previous and adjustment not in previous else (previous or adjustment)
    )


def _classify_medium_support_promotion_tier(evidence: Dict[str, Any]) -> Dict[str, Any]:
    """Decide whether a verified medium support should be promoted to strong.

    Returns ``{"tier": <strong|moderate|none>, "reason": <str>}``.  ``strong``
    promotes the support to ``strength=strong`` and tags
    ``strength_promotion_reason`` with the matching path.  ``moderate`` keeps
    the support at medium (so it surfaces as ``verified_moderate`` in the
    final-view admission tier) but records *why* the promotion was held.
    ``none`` means the support was not even a promotion candidate.
    """
    none = {"tier": "none", "reason": ""}
    if str(evidence.get("strength") or "") != "medium":
        return none
    initial_strength = str(evidence.get("initial_strength") or "")
    restored_from_low_score_guard = (
        initial_strength == "strong"
        and str(evidence.get("final_strength_guard_downgrade_reason") or "") == "low_score_strong_support_downgrade"
    )
    if initial_strength not in {"", "medium"} and not restored_from_low_score_guard:
        return none
    # Bug C fix: align with `_is_real_bound_support` instead of requiring the
    # explicit `bound_real_claim` tag.  Manager/binding pipelines mark a
    # support as bound by leaving `binding_status` empty or as `unchecked`
    # while the Evidence Agent has already merged the support into the real
    # claim's evidence_map — refusing those here forces every paper without
    # an explicit late-stage rebinding to stay zero-real.
    if str(evidence.get("binding_status") or "") not in {"", "unchecked", "bound_real_claim"}:
        return none
    if str(evidence.get("stance") or "") not in {"supports", "partially_supports"}:
        return none
    if _evidence_has_negative_intent(evidence):
        return none
    grounding_label = str(evidence.get("verified_grounding_label") or "")
    if grounding_label not in VERIFIED_PAPER_GROUNDED_LABELS:
        return none
    semantic_label = str(evidence.get("semantic_grounding_label") or "")
    if semantic_label != "semantic_support_verified":
        return none
    # Bug C fix: `verified_claim_overlap_score` is only populated on the
    # quote-bank claim-overlap *fallback* path (see
    # `_apply_quote_bank_entry_metadata`).  Supports that grounded directly
    # via `paper_grounded_exact` + `semantic_support_verified` never receive
    # an overlap score at all, so the original `> 0` gate silently rejected
    # the strongest grounding path.  Allow direct, fully-verified supports
    # to bypass the overlap requirement; keep the gate for weaker grounding
    # paths where overlap is the safety net.
    has_overlap = _normalize_int(evidence.get("verified_claim_overlap_score"), default=0, min_value=0) > 0
    is_direct_verified = grounding_label == "paper_grounded_exact" and semantic_label == "semantic_support_verified"
    if not (has_overlap or is_direct_verified):
        return none
    # Bug C fix: `support_depth` returns `moderate` for method-section
    # supports (see `support_quality.support_depth`).  A method-section
    # support that is fully paper-grounded, semantically verified, bound to
    # a real claim, non-abstract, and non-shallow is genuine real-strong
    # evidence — it is not the same as a `shallow` (abstract) support.
    # Allow {deep, moderate} but keep `shallow` and empty as hard rejects.
    depth = _support_depth_label(evidence)
    if depth not in {"deep", "moderate"}:
        return none
    source_bucket = str(evidence.get("support_source_bucket") or evidence.get("verified_source_bucket") or "")
    declared_bucket = str(evidence.get("support_source_bucket") or "").strip()
    decision_bucket = _decision_support_source_bucket(evidence)
    if source_bucket == "abstract":
        return none
    # Mainline-Final-Integrated P0-1: never promote a Limitation / Gap /
    # Negative-evidence anchor to strong, regardless of method/deep depth.
    # The same signals that block ``_final_strong_guard`` from admitting an
    # already-strong support are applied here so the promotion path itself
    # cannot launder a negative anchor into ``verified_strong``.
    if _evidence_negative_locator_or_bucket_signal(evidence):
        return {
            "tier": "moderate",
            "reason": "negative_anchor_support_held_at_moderate",
        }
    score = _normalize_float(evidence.get("semantic_alignment_score"), default=0.0)
    near_miss_path = _verified_moderate_near_miss_promotion_path(evidence)
    if depth == "deep":
        if score >= DEEP_PROMOTION_STRONG_MIN_SCORE:
            reason = (
                "verified_claim_overlap_deep_support" if has_overlap else "direct_verified_deep_support"
            )
            return {"tier": "strong", "reason": reason}
        match_type = str(evidence.get("verified_quote_match_type") or "").lower()
        locator = str(evidence.get("source_locator") or "")
        specific_anchor = bool(evidence.get("source_locator_specific")) or _is_specific_locator(locator)
        anchor_verified = (
            specific_anchor
            and grounding_label == "paper_grounded_exact"
            and match_type
            in {
                "exact",
                "exact_match",
                "exact_quote",
                "quote_bank_id_canonical",
                "quote_bank_raw_canonical",
            }
            and (declared_bucket in _TABLE_OR_RESULT_ANCHOR_BUCKETS or decision_bucket in _TABLE_OR_RESULT_ANCHOR_BUCKETS)
        )
        if anchor_verified:
            return {"tier": "moderate", "reason": "specific_anchor_low_score_support_held_at_moderate"}
        if near_miss_path == "near_miss_verified_deep_support":
            return {"tier": "moderate", "reason": near_miss_path}
        return {
            "tier": "moderate",
            "reason": "low_score_deep_support_held_at_moderate",
        }
    # depth == "moderate" (method-section)
    if score >= METHOD_PROMOTION_STRONG_MIN_SCORE:
        reason = (
            "verified_claim_overlap_method_support" if has_overlap else "direct_verified_method_support"
        )
        return {"tier": "strong", "reason": reason}
    if near_miss_path == "near_miss_verified_method_support":
        return {"tier": "moderate", "reason": near_miss_path}
    if score >= METHOD_PROMOTION_MODERATE_MIN_SCORE:
        return {
            "tier": "moderate",
            "reason": "moderate_score_method_support_held_at_moderate",
        }
    return {
        "tier": "moderate",
        "reason": "low_score_method_support_held_at_moderate",
    }


def _should_promote_verified_medium_support(evidence: Dict[str, Any]) -> bool:
    """Backward-compatible helper: True iff the verified medium support is
    eligible for promotion to ``strength=strong``.  Score-based moderate
    holds return False here while still being promotion *candidates* in the
    audit/shadow path."""
    return _classify_medium_support_promotion_tier(evidence)["tier"] == "strong"


_UNTRUSTED_VERIFIER_SOURCE_LABELS = {
    "fallback",
    "fallback-extraction",
    "model-output",
    "model output",
    "model_generated",
    "manager_model",
    "system recovery salvage",
    "system_meta",
    "system-meta",
    "quote-bank-negative-grounding",
}


def _has_trusted_existing_grounding(evidence: Dict[str, Any]) -> bool:
    source = str((evidence or {}).get("source") or "").strip().lower()
    source_locator = str((evidence or {}).get("source_locator") or "").strip().lower()
    if source in _UNTRUSTED_VERIFIER_SOURCE_LABELS or source_locator in _UNTRUSTED_VERIFIER_SOURCE_LABELS:
        return False
    if str(evidence.get("verified_grounding_label") or "") not in VERIFIED_PAPER_GROUNDED_LABELS:
        return False
    if str(evidence.get("semantic_grounding_label") or "") not in {
        "semantic_support_verified",
        "semantic_negative_verified",
    }:
        return False
    if not str(evidence.get("raw_quote") or "").strip():
        return False
    start = _normalize_int(evidence.get("verified_source_span_start"), default=-1)
    end = _normalize_int(evidence.get("verified_source_span_end"), default=-1)
    if start < 0 or end <= start:
        return False
    match_type = str(evidence.get("verified_quote_match_type") or "").strip().lower()
    return match_type in {
        "exact",
        "exact_match",
        "normalized",
        "normalized_match",
        "quote_bank_id_canonical",
        "quote_bank_raw_canonical",
        "quote_bank_claim_overlap_canonical",
        "candidate_window_quote_bank_exact_substring",
        "candidate_window_quote_bank_normalized_substring",
        "full_paper_exact_substring",
        "full_paper_normalized_substring",
    }


def _apply_final_support_promotion_and_guard(evidence: Dict[str, Any]) -> None:
    promotion_decision = _classify_medium_support_promotion_tier(evidence)
    promotion_tier = promotion_decision["tier"]
    promotion_reason = promotion_decision["reason"]
    if promotion_tier == "strong":
        evidence["strength"] = "strong"
        evidence["support_quality_adjustment"] = "promoted_verified_claim_matched_support"
        evidence["strength_promotion_from_medium_used"] = True
        evidence["strength_promotion_held_at_moderate"] = False
        evidence["strength_promotion_reason"] = promotion_reason
    elif promotion_tier == "moderate":
        evidence["strength_promotion_held_at_moderate"] = True
        evidence["strength_promotion_from_medium_used"] = False
        evidence["strength_promotion_reason"] = promotion_reason
    _final_strong_guard(evidence)


def _assess_quote_semantic_grounding(state: Dict[str, Any], evidence: Dict[str, Any]) -> Dict[str, Any]:
    """Check whether a paper-grounded quote semantically supports the evidence item.

    Quote existence is necessary but not sufficient: a copied abstract quote should
    not verify an evidence statement about a specific table, metric, or margin.
    This verifier is intentionally conservative and uses deterministic anchors
    before accepting strong support.
    """
    quote = str(evidence.get("raw_quote") or "")
    if not quote or evidence.get("verified_grounding_label") not in VERIFIED_PAPER_GROUNDED_LABELS:
        return {
            "semantic_grounding_label": "semantic_unverified_quote",
            "semantic_grounding_reasons": ["quote_not_verified"],
            "semantic_alignment_score": 0.0,
            "semantic_grounding_checked": True,
            "quote_evidence_semantic_mismatch": True,
        }

    claim_text = _claim_text_for_evidence(state or {}, str(evidence.get("claim_id") or ""))
    evidence_text = str(evidence.get("evidence") or "")
    agent_raw_quote = str(evidence.get("agent_raw_quote") or "")
    support_bucket = str(evidence.get("support_source_bucket") or evidence.get("verified_source_bucket") or "")
    source_locator = str(evidence.get("source_locator") or "")
    check_text = " ".join([claim_text, evidence_text, agent_raw_quote]).strip()
    reasons: List[str] = []

    check_numbers = _semantic_numeric_anchors(" ".join([evidence_text, agent_raw_quote]))
    quote_numbers = _semantic_numeric_anchors(quote)
    if check_numbers and not (check_numbers & quote_numbers):
        reasons.append("missing_numeric_anchor")

    check_tables = _semantic_table_anchors(" ".join([evidence_text, agent_raw_quote, source_locator]))
    quote_tables = _semantic_table_anchors(quote)
    if check_tables and not (check_tables & quote_tables):
        if not re.search(r"\b(table|figure|fig\.)\b", quote, re.IGNORECASE):
            reasons.append("missing_table_or_figure_anchor")

    quote_looks_abstract = bool(_SEMANTIC_ABSTRACT_MARKER_RE.search(quote[:260]))
    bucket_claims_result = support_bucket in {"result_or_experiment", "table_or_figure", "results"}
    if bucket_claims_result and quote_looks_abstract and not _SEMANTIC_TABLE_RE.search(quote):
        reasons.append("abstract_quote_used_for_result_support")

    score = _semantic_alignment_score(check_text, quote)
    has_anchor_match = bool((check_numbers & quote_numbers) or (check_tables & quote_tables))
    author_limitation_quote = bool(_REVIEW_NEGATIVE_AUTHOR_LIMITATION_RE.search(quote))
    prior_work_negative_context = _negative_anchor_is_prior_work_context(quote)
    negative_intent = _has_review_negative_semantic_intent(evidence)
    comparison_invalidation = bool(_comparison_invalidation_is_current_paper_issue(quote))
    quote_has_negative_anchor = bool(_SEMANTIC_NEGATIVE_TERMS_RE.search(quote) or comparison_invalidation)
    excerpt_limited_absence = bool(
        _SEMANTIC_ABSENCE_EXCERPT_LIMIT_RE.search(" ".join([evidence_text, agent_raw_quote]))
    )
    table_scope_absence_negative = _is_table_scope_absence_negative(
        state,
        evidence,
        quote,
        claim_text,
        evidence_text,
        source_locator,
    )

    claim_overlap_verified = _has_verified_claim_overlap_support(evidence, min_score=2)

    semantic_weak_promotion_used = False
    semantic_weak_promotion_reason = ""

    if _evidence_has_negative_intent(evidence) and author_limitation_quote:
        label = "semantic_author_limitation"
        reasons.append("author_self_limitation_or_future_work_note")
    elif negative_intent:
        if prior_work_negative_context:
            label = "semantic_mismatch"
            reasons.append("prior_work_negative_context")
        elif excerpt_limited_absence:
            label = "semantic_mismatch"
            reasons.append("absence_claim_limited_to_quote_or_excerpt")
        elif not quote_has_negative_anchor and not table_scope_absence_negative:
            reasons.append("quote_lacks_negative_anchor")
        if prior_work_negative_context:
            pass
        elif excerpt_limited_absence:
            pass
        elif table_scope_absence_negative:
            label = "semantic_negative_verified"
            reasons.append("table_scope_absence_verified")
            current_neg_type = str(evidence.get("negative_evidence_type") or "").strip()
            if not current_neg_type or current_neg_type == "direct_contradiction":
                evidence["negative_evidence_type"] = _derive_table_scope_absence_negative_type(evidence)
                evidence["negative_evidence_type_decision_view_reason"] = "table_scope_absence_type_derived"
        elif comparison_invalidation:
            label = "semantic_negative_verified"
            reasons.append("comparison_invalidation_verified")
        elif reasons:
            label = "semantic_mismatch"
        elif has_anchor_match or score >= 0.14 or quote_has_negative_anchor:
            label = "semantic_negative_verified"
        elif score >= 0.08:
            label = "semantic_negative_weak"
            reasons.append("low_semantic_overlap")
        else:
            label = "semantic_mismatch"
            reasons.append("low_semantic_overlap")
    elif reasons:
        label = "semantic_mismatch"
    elif has_anchor_match or score >= 0.18:
        label = "semantic_support_verified"
    elif claim_overlap_verified and score >= 0.08:
        label = "semantic_support_verified"
        semantic_weak_promotion_used = True
        semantic_weak_promotion_reason = "verified_claim_overlap_low_semantic_alignment"
    elif score >= 0.08:
        label = "semantic_support_weak"
        reasons.append("low_semantic_overlap")
    else:
        label = "semantic_mismatch"
        reasons.append("low_semantic_overlap")

    return {
        "semantic_grounding_label": label,
        "semantic_grounding_reasons": reasons,
        "semantic_alignment_score": round(score, 4),
        "semantic_grounding_checked": True,
        "quote_evidence_semantic_mismatch": label == "semantic_mismatch",
        "semantic_weak_promotion_used": semantic_weak_promotion_used,
        "semantic_weak_promotion_reason": semantic_weak_promotion_reason,
    }


def _verify_evidence_grounding_against_state(state: Dict[str, Any], evidence: Dict[str, Any]) -> Dict[str, Any]:
    item = dict(evidence)
    if state.get("paper_id") and not item.get("paper_id"):
        item["paper_id"] = str(state.get("paper_id") or "")
    if not item.get("support_id"):
        item["support_id"] = str(item.get("evidence_id") or "")
    if not item.get("turn_id"):
        item["turn_id"] = _evidence_turn_index(item)
    if "initial_strength" not in item:
        item["initial_strength"] = str(item.get("strength") or "")
    if "initial_stance" not in item:
        item["initial_stance"] = str(item.get("stance") or "")
    item["source_locator_specific"] = _is_specific_locator(str(item.get("source_locator") or ""))
    item["support_depth"] = _support_depth_label(item)
    item["final_strength"] = str(item.get("strength") or "")
    item["final_support_depth"] = str(item.get("support_depth") or "")
    if _has_trusted_existing_grounding(item):
        _apply_comparison_invalidation_negative_override(state, item)
        _apply_review_negative_relation_label(state, item)
        _apply_programmatic_source_locator(state, item)
        _apply_final_support_promotion_and_guard(item)
        item["support_depth"] = _support_depth_label(item)
        item["final_strength"] = str(item.get("strength") or "")
        item["final_support_depth"] = str(item.get("support_depth") or "")
        return item
    quote_bank = _quote_bank_entries_for_grounding(state or {})
    raw_quote_text = str(item.get("raw_quote") or "")
    if not quote_bank and not (raw_quote_text.strip() and str((state or {}).get("paper_text") or "")):
        return item

    quote_id = str(item.get("quote_id") or "")
    ordered_refs: List[Dict[str, Any]] = []
    seen_ids: set[int] = set()
    for entry in quote_bank:
        if quote_id and str(entry.get("quote_id") or "") == quote_id:
            ordered_refs.append(entry)
            seen_ids.add(id(entry))
    for entry in quote_bank:
        if id(entry) not in seen_ids:
            ordered_refs.append(entry)

    verification = _verify_quote_against_reference("", "")
    matched_quote_id_entry: Optional[Dict[str, Any]] = None
    if quote_id:
        for entry in quote_bank:
            if str(entry.get("quote_id") or "") == quote_id:
                matched_quote_id_entry = entry
                break

    if matched_quote_id_entry is not None and (not raw_quote_text.strip() or not _evidence_has_negative_intent(item)):
        # For positive support, preserve the legacy quote_id canonicalization
        # path: the model may provide a paraphrase plus a program-extracted
        # quote_id anchor.  Negative/missing evidence is stricter below because
        # a mismatched quote_id can otherwise turn a reviewer concern into a
        # false verified negative.
        canonical_quote = str(matched_quote_id_entry.get("raw_quote") or "")
        _apply_quote_bank_entry_metadata(
            item,
            matched_quote_id_entry,
            canonicalize_quote=True,
            overwrite_locator=True,
        )
        verification = _verify_quote_against_reference(
            canonical_quote,
            canonical_quote,
            _normalize_int(matched_quote_id_entry.get("source_span_start"), default=-1),
        )
        verification["verified_quote_match_type"] = "quote_bank_id_canonical"
        verification["verified_grounding_reason"] = "quote_id matched a program-extracted quote-bank item; raw_quote was canonicalized to that item"
    elif matched_quote_id_entry is not None:
        canonical_quote = str(matched_quote_id_entry.get("raw_quote") or "")
        matched_entry_is_candidate_window = _is_candidate_window_quote_bank_entry(matched_quote_id_entry)
        quote_id_verification = _verify_quote_against_reference(
            raw_quote_text,
            canonical_quote,
            _normalize_int(matched_quote_id_entry.get("source_span_start"), default=-1),
        )
        prefix_verification: Optional[Dict[str, Any]] = None
        if quote_id_verification.get("verified_grounding_label") not in VERIFIED_PAPER_GROUNDED_LABELS:
            prefix_verification = _verify_quote_bank_prefix_canonicalization(
                raw_quote_text,
                canonical_quote,
                _normalize_int(matched_quote_id_entry.get("source_span_start"), default=-1),
            )
        if (
            quote_id_verification.get("verified_grounding_label") in VERIFIED_PAPER_GROUNDED_LABELS
            or (
                prefix_verification is not None
                and prefix_verification.get("verified_grounding_label") in VERIFIED_PAPER_GROUNDED_LABELS
            )
        ):
            _apply_quote_bank_entry_metadata(
                item,
                matched_quote_id_entry,
                canonicalize_quote=bool(canonical_quote) and not matched_entry_is_candidate_window,
                overwrite_locator=True,
            )
            if matched_entry_is_candidate_window:
                verification = quote_id_verification
                match_type = str(verification.get("verified_quote_match_type") or "quote_bank_raw_substring")
                verification["verified_quote_match_type"] = f"candidate_window_{match_type}"
                verification["verified_grounding_reason"] = (
                    "raw_quote matched a candidate-relevant paper window generated from the full paper text; "
                    "raw_quote was kept verbatim rather than canonicalized to the whole window"
                )
            elif prefix_verification is not None:
                verification = prefix_verification
            elif canonical_quote:
                verification = _verify_quote_against_reference(
                    canonical_quote,
                    canonical_quote,
                    _normalize_int(matched_quote_id_entry.get("source_span_start"), default=-1),
                )
                verification["verified_quote_match_type"] = "quote_bank_id_canonical"
                verification["verified_grounding_reason"] = "raw_quote matched the supplied quote_id's program-extracted quote-bank item; raw_quote was canonicalized to that item"
        else:
            item["quote_id_mismatch_ignored"] = True
            item["quote_id_mismatch_ignored_quote_id"] = quote_id
            item["quote_id_mismatch_grounding_label"] = str(quote_id_verification.get("verified_grounding_label") or "")
            item["quote_id_mismatch_reason"] = "raw_quote did not match the supplied quote_id's quote-bank item; searching quote bank by raw_quote instead"

    if verification.get("verified_grounding_label") not in VERIFIED_PAPER_GROUNDED_LABELS:
        for entry in ordered_refs:
            verification = _verify_quote_against_reference(
                raw_quote_text,
                str(entry.get("raw_quote") or ""),
                _normalize_int(entry.get("source_span_start"), default=-1),
            )
            if verification.get("verified_grounding_label") in VERIFIED_PAPER_GROUNDED_LABELS:
                canonical_quote = str(entry.get("raw_quote") or "")
                entry_is_candidate_window = _is_candidate_window_quote_bank_entry(entry)
                _apply_quote_bank_entry_metadata(
                    item,
                    entry,
                    canonicalize_quote=bool(canonical_quote) and not entry_is_candidate_window,
                    overwrite_locator=False,
                )
                if entry_is_candidate_window:
                    match_type = str(verification.get("verified_quote_match_type") or "quote_bank_raw_substring")
                    verification["verified_quote_match_type"] = f"candidate_window_{match_type}"
                    verification["verified_grounding_reason"] = (
                        "raw_quote matched a candidate-relevant paper window generated from the full paper text; "
                        "raw_quote was kept verbatim rather than canonicalized to the whole window"
                    )
                elif canonical_quote:
                    verification = _verify_quote_against_reference(
                        canonical_quote,
                        canonical_quote,
                        _normalize_int(entry.get("source_span_start"), default=-1),
                    )
                    verification["verified_quote_match_type"] = "quote_bank_raw_canonical"
                    verification["verified_grounding_reason"] = "raw_quote matched a program-extracted quote-bank item; raw_quote was canonicalized to that item"
                break

    if (
        verification.get("verified_grounding_label") not in VERIFIED_PAPER_GROUNDED_LABELS
        and (_evidence_has_negative_intent(item) or str(item.get("negative_evidence_type") or "").strip())
    ):
        full_paper_verification = _verify_quote_against_full_paper(raw_quote_text, state or {})
        if full_paper_verification is not None:
            verification = full_paper_verification

    if verification.get("verified_grounding_label") not in VERIFIED_PAPER_GROUNDED_LABELS:
        overlap_entry = _select_claim_overlap_quote_bank_entry(state or {}, item, quote_bank)
        if overlap_entry is not None:
            canonical_quote = str(overlap_entry.get("raw_quote") or "")
            _apply_quote_bank_entry_metadata(
                item,
                overlap_entry,
                canonicalize_quote=bool(canonical_quote),
                overwrite_locator=False,
            )
            if canonical_quote:
                item["quote_bank_claim_overlap_fallback_used"] = True
                item["quote_bank_claim_overlap_fallback_quote_id"] = str(overlap_entry.get("quote_id") or "")
                item["quote_bank_claim_overlap_fallback_source_bucket"] = str(overlap_entry.get("source_bucket") or "")
                item["quote_bank_claim_overlap_fallback_score"] = _normalize_int(overlap_entry.get("claim_overlap_score"), default=0, min_value=0)
                verification = _verify_quote_against_reference(
                    canonical_quote,
                    canonical_quote,
                    _normalize_int(overlap_entry.get("source_span_start"), default=-1),
                )
                verification["verified_quote_match_type"] = "quote_bank_claim_overlap_canonical"
                verification["verified_grounding_reason"] = "raw_quote was not copied exactly, but a non-abstract claim-overlap quote-bank item was canonicalized"

    item.update(verification)
    semantic = _assess_quote_semantic_grounding(state, item)
    item.update(semantic)
    _apply_comparison_invalidation_negative_override(state, item)
    _apply_review_negative_relation_label(state, item)
    if item.get("verified_grounding_label") not in VERIFIED_PAPER_GROUNDED_LABELS and item.get("strength") == "strong":
        item["strength"] = "medium"
        item["support_quality_adjustment"] = "downgraded_unverified_quote_grounding"
    if item.get("strength") == "strong" and item.get("stance") in {"supports", "partially_supports"} and item.get("semantic_grounding_label") != "semantic_support_verified":
        item["strength"] = "medium"
        previous_adjustment = str(item.get("support_quality_adjustment") or "")
        semantic_adjustment = "downgraded_semantic_grounding_mismatch"
        item["support_quality_adjustment"] = (
            f"{previous_adjustment};{semantic_adjustment}" if previous_adjustment else semantic_adjustment
        )
    # P0-1/P0-2 calibration: classify the medium support into a promotion
    # tier based on `semantic_alignment_score`.  ``strong`` upgrades the
    # support to ``strength=strong`` with the legacy reason tags.  ``moderate``
    # keeps the support at medium so it surfaces as ``verified_moderate`` in
    # the final-view admission tier; the held-at-moderate reason is recorded
    # for audit (no impact on `_is_real_bound_support`, which still requires
    # ``strength=='strong'``).
    _apply_programmatic_source_locator(state, item)
    _apply_final_support_promotion_and_guard(item)
    item["support_depth"] = _support_depth_label(item)
    item["final_strength"] = str(item.get("strength") or "")
    item["final_support_depth"] = str(item.get("support_depth") or "")
    return item


def _verify_evidence_items_for_state(state: Dict[str, Any], evidence_items: Sequence[Dict[str, Any]]) -> List[Dict[str, Any]]:
    verified: List[Dict[str, Any]] = []
    for item in evidence_items:
        if (
            isinstance(item, dict)
            and (
                str(item.get("source") or "").strip().lower() == ABSENCE_AUDIT_SOURCE
                or bool(item.get("absence_audit_verified"))
            )
        ):
            # Reviewer absence audit rows are deterministic coverage findings,
            # not paper quotes.  They are revalidated by
            # _is_reviewer_absence_audit_evidence_record; sending them through
            # the quote-grounding verifier rewrites them as
            # insufficient_paper_grounding and loses the audit provenance.
            verified.append(copy.deepcopy(item))
            continue
        verified.append(_verify_evidence_grounding_against_state(state, item))
    return verified


def _is_verified_paper_grounded_evidence(evidence: Dict[str, Any]) -> bool:
    return str(evidence.get("verified_grounding_label") or "") in VERIFIED_PAPER_GROUNDED_LABELS


def _is_legacy_non_abstract_support_grounding(evidence: Dict[str, Any]) -> bool:
    source_text = " ".join(
        str(evidence.get(key) or "")
        for key in ("source", "source_locator", "support_source_bucket", "verified_source_bucket")
    ).strip().lower()
    if not source_text or "abstract" in source_text:
        return False
    if any(
        term in source_text
        for term in (
            "result",
            "experiment",
            "evaluation",
            "benchmark",
            "ablation",
            "table",
            "figure",
            "method",
            "section",
            "proof",
            "theorem",
        )
    ):
        return True
    bucket = _decision_support_source_bucket(evidence)
    return bucket in _EMPIRICAL_DECISION_BUCKETS or bucket in _METHOD_DECISION_BUCKETS


def _is_usable_support_grounding(evidence: Dict[str, Any]) -> bool:
    if _evidence_has_negative_intent(evidence):
        return False
    label = str(evidence.get("verified_grounding_label") or "").strip()
    semantic_label = str(evidence.get("semantic_grounding_label") or "").strip()
    if (
        label in {"", "unjudged"}
        and semantic_label in {"", "semantic_unjudged"}
        and not str(evidence.get("raw_quote") or "").strip()
        and not str(evidence.get("quote_id") or "").strip()
        and not str(evidence.get("verified_quote_match_type") or "").strip()
        and not bool(evidence.get("semantic_grounding_checked"))
    ):
        if evidence.get("runtime_evidence_verification_required") or evidence.get("model_claimed_verification_stripped"):
            return False
        return _is_legacy_non_abstract_support_grounding(evidence)
    if label not in VERIFIED_PAPER_GROUNDED_LABELS:
        return False
    if semantic_label != "semantic_support_verified":
        return False
    return True


def _has_final_support_strength(evidence: Dict[str, Any]) -> bool:
    """Return True when evidence is safe to count as final-view support.

    The normal path is a verified ``strength=strong`` row.  The narrow fallback
    handles rows that were generated as strong support, then temporarily
    downgraded during an earlier semantic-mismatch pass, but later recovered by
    quote-bank canonicalisation and semantic verification.  This avoids losing
    verified support because of a stale downgrade marker while keeping negative,
    abstract, shallow, and low-score rows out of final support.
    """
    if str(evidence.get("strength") or "") == "strong":
        return True
    if str(evidence.get("initial_strength") or "") != "strong":
        return False
    if str(evidence.get("strength") or "") != "medium":
        return False
    if str(evidence.get("final_strength_guard_downgrade_reason") or ""):
        return False
    adjustment = str(evidence.get("support_quality_adjustment") or "").lower()
    if "downgraded_negative_locator" in adjustment:
        return False
    if _evidence_negative_locator_or_bucket_signal(evidence):
        return False
    if not _is_usable_support_grounding(evidence):
        return False
    depth = _support_depth_label(evidence)
    if depth not in {"deep", "moderate"}:
        return False
    declared_bucket = str(evidence.get("support_source_bucket") or "").strip()
    decision_bucket = _decision_support_source_bucket(evidence)
    if declared_bucket == "abstract" or decision_bucket == "abstract":
        return False
    score = _normalize_float(evidence.get("semantic_alignment_score"), default=0.0)
    threshold = DEEP_PROMOTION_STRONG_MIN_SCORE if depth == "deep" else METHOD_PROMOTION_STRONG_MIN_SCORE
    return score >= threshold or bool(_verified_moderate_near_miss_promotion_path(evidence))


def _support_observability_record(evidence: Dict[str, Any]) -> Dict[str, Any]:
    return {
        "evidence_id": str(evidence.get("evidence_id") or ""),
        "support_id": str(evidence.get("support_id") or evidence.get("evidence_id") or ""),
        "claim_id": str(evidence.get("claim_id") or ""),
        "quote_id": str(evidence.get("quote_id") or ""),
        "raw_quote": str(evidence.get("raw_quote") or "")[:220],
        "agent_raw_quote": str(evidence.get("agent_raw_quote") or "")[:220],
        "source_locator": str(evidence.get("source_locator") or ""),
        "verified_quote_match_type": str(evidence.get("verified_quote_match_type") or ""),
        "semantic_grounding_label": str(evidence.get("semantic_grounding_label") or ""),
        "semantic_alignment_score": evidence.get("semantic_alignment_score", 0.0),
        "verified_claim_overlap_score": _verified_claim_overlap_score(evidence),
        "source_bucket": str(evidence.get("verified_source_bucket") or evidence.get("support_source_bucket") or ""),
        "support_depth": _support_depth_label(evidence),
        "strength": str(evidence.get("strength") or ""),
        "initial_strength": str(evidence.get("initial_strength") or ""),
        "quote_bank_claim_overlap_fallback_used": bool(evidence.get("quote_bank_claim_overlap_fallback_used")),
        "quote_bank_claim_overlap_fallback_quote_id": str(evidence.get("quote_bank_claim_overlap_fallback_quote_id") or ""),
        "quote_bank_claim_overlap_fallback_source_bucket": str(evidence.get("quote_bank_claim_overlap_fallback_source_bucket") or ""),
        "quote_bank_claim_overlap_fallback_score": _normalize_int(evidence.get("quote_bank_claim_overlap_fallback_score"), default=0, min_value=0),
        "semantic_weak_promotion_used": bool(evidence.get("semantic_weak_promotion_used")),
        "semantic_weak_promotion_reason": str(evidence.get("semantic_weak_promotion_reason") or ""),
        "strength_promotion_from_medium_used": bool(evidence.get("strength_promotion_from_medium_used")),
        "strength_promotion_reason": str(evidence.get("strength_promotion_reason") or ""),
        "included_in_final_view": False,
    }


def _is_real_paper_claim_id(claim_id: Any, declared_kind: Any = "") -> bool:
    return _classify_claim_kind(claim_id, declared_kind) == "paper_extracted"


def _is_real_paper_claim_id_for_negative(claim_id: Any, declared_kind: Any = "") -> bool:
    """Claim gate for negative-evidence binding.

    Negative evidence must bind to an ordinary real paper claim, never to a
    context/fallback/recovery scaffold.  Raw-salvaged fallback claims can still
    be used by the diagnosis/search target gate, but they no longer count as
    final verified reviewer-negative evidence.
    """
    value = str(claim_id or "").strip().lower()
    if value.startswith(
        (
            "claim-paper-context",
            "claim-context",
            "claim-paper-fallback",
            "claim-fallback",
            "claim-recovery",
            "claim-paper-recovery",
        )
    ):
        return False
    return _is_real_paper_claim_id(claim_id, declared_kind)


def _is_specific_locator(locator: str) -> bool:
    loc = str(locator or "").strip().strip("'\"")
    if not loc:
        return False
    if _GENERIC_LOCATOR_RE.match(loc):
        return False
    return bool(_SPECIFIC_LOCATOR_RE.search(loc))



_LOCATOR_NAMED_ANCHOR_RE = re.compile(
    r"\b(?:Table|Figure|Fig\.|Algorithm|Theorem|Lemma|Proposition|Corollary)\s*[A-Z]?\d+(?:[.\-]\d+)?\b",
    re.IGNORECASE,
)
_LOCATOR_TABLE_FIGURE_RE = re.compile(
    r"\b(?:Table|Figure|Fig\.)\s*[A-Z]?\d+(?:[.\-]\d+)?\b",
    re.IGNORECASE,
)
_LOCATOR_LATEX_SECTION_RE = re.compile(
    r"\\(?:sub)*section\*?\{([^{}]{2,96})\}",
    re.IGNORECASE,
)
_LOCATOR_LATEX_REF_RE = re.compile(
    r"\\(?:c|C)?ref\{([^{}]{2,120})\}|\\autoref\{([^{}]{2,120})\}",
    re.IGNORECASE,
)
_LOCATOR_LATEX_CAPTION_RE = re.compile(
    r"\\caption\{([^{}]{8,180})\}",
    re.IGNORECASE,
)
_LOCATOR_SECTION_REF_RE = re.compile(
    r"\b(?:Sec\.|Section)\s*(\d+(?:\.\d+){0,3})\b",
    re.IGNORECASE,
)
_LOCATOR_NUMBERED_SECTION_RE = re.compile(
    r"(?:^|\n)\s*(\d+(?:\.\d+){0,3})\s+([A-Z][^\n]{2,96})"
)


def _format_locator_anchor(match: re.Match[str]) -> str:
    raw = re.sub(r"\s+", " ", match.group(0)).strip()
    raw = raw.replace("Fig.", "Figure")
    return raw[:96]


def _locator_type_from_anchor(anchor: str) -> str:
    value = str(anchor or "").strip().lower()
    if not value:
        return "generic"
    if re.search(r"\btable\b", value):
        return "table"
    if re.search(r"\bfigure|\bfig\.", value):
        return "figure"
    if re.search(r"\balgorithm\b", value):
        return "algorithm"
    if re.search(r"\b(theorem|lemma|proposition|corollary)\b", value):
        return "theorem"
    if re.search(r"\b(section|sec\.)\b|\b\d+\.\d+", value):
        return "section"
    return "generic"


def _latex_label_locator(label: str) -> str:
    first = str(label or "").split(",", 1)[0].strip()
    if not first:
        return ""
    prefix, _, raw_name = first.partition(":")
    prefix_l = prefix.strip().lower()
    name = raw_name.strip() or first
    name = re.sub(r"[_-]+", " ", name)
    name = re.sub(r"\s+", " ", name).strip()
    if prefix_l in {"fig", "figure"}:
        return f"Figure: {name[:72]}"
    if prefix_l in {"tab", "table"}:
        return f"Table: {name[:72]}"
    if prefix_l in {"sec", "section"}:
        return f"Section: {name[:72]}"
    if prefix_l in {"alg", "algorithm"}:
        return f"Algorithm: {name[:72]}"
    if prefix_l in {"thm", "theorem", "lem", "lemma", "prop", "proposition", "cor", "corollary"}:
        return f"Theorem: {name[:72]}"
    return ""


def _locator_anchor_details_from_text(text: str) -> Dict[str, Any]:
    value = str(text or "")
    named = _LOCATOR_NAMED_ANCHOR_RE.search(value)
    if named:
        locator = _format_locator_anchor(named)
        return {"locator": locator, "locator_type": _locator_type_from_anchor(locator), "locator_confidence": 0.9}
    section_ref = _LOCATOR_SECTION_REF_RE.search(value)
    if section_ref:
        locator = f"Section {section_ref.group(1)}"
        return {"locator": locator, "locator_type": "section", "locator_confidence": 0.85}
    latex_ref = _LOCATOR_LATEX_REF_RE.search(value)
    if latex_ref:
        locator = _latex_label_locator(latex_ref.group(1) or latex_ref.group(2) or "")
        if locator:
            return {"locator": locator, "locator_type": _locator_type_from_anchor(locator), "locator_confidence": 0.82}
    caption = _LOCATOR_LATEX_CAPTION_RE.search(value)
    if caption:
        caption_text = re.sub(r"\s+", " ", caption.group(1)).strip()
        if caption_text:
            return {
                "locator": f"Table/Figure caption: {caption_text[:72]}",
                "locator_type": "table",
                "locator_confidence": 0.78,
            }
    latex = _LOCATOR_LATEX_SECTION_RE.search(value)
    if latex:
        title = re.sub(r"\s+", " ", latex.group(1)).strip()
        if title:
            return {"locator": f"Section: {title[:80]}", "locator_type": "section", "locator_confidence": 0.75}
    numbered = _LOCATOR_NUMBERED_SECTION_RE.search(value)
    if numbered:
        number = numbered.group(1).strip()
        title = re.sub(r"\s+", " ", numbered.group(2)).strip()
        title = re.sub(r"\s{2,}.*$", "", title)
        return {"locator": f"Section {number}: {title[:72]}", "locator_type": "section", "locator_confidence": 0.75}
    return {"locator": "", "locator_type": "generic", "locator_confidence": 0.0}


def _locator_from_text_anchor(text: str) -> str:
    return str(_locator_anchor_details_from_text(text).get("locator") or "")


def _locator_span_overlap(a_start: int, a_end: int, b_start: int, b_end: int) -> int:
    if a_start < 0 or a_end <= a_start or b_start < 0 or b_end <= b_start:
        return 0
    return max(0, min(a_end, b_end) - max(a_start, b_start))


def _programmatic_source_locator_details(state: Dict[str, Any], evidence: Dict[str, Any]) -> Dict[str, Any]:
    current = str((evidence or {}).get("source_locator") or "").strip()
    if _is_specific_locator(current):
        return {
            "locator": current,
            "locator_type": _locator_type_from_anchor(current),
            "locator_confidence": 0.9,
            "reason": "existing_specific_locator",
        }
    direct_text = " ".join(
        str((evidence or {}).get(key) or "")
        for key in ("source_locator", "raw_quote", "agent_raw_quote", "evidence")
    )
    direct = _locator_anchor_details_from_text(direct_text)
    if direct.get("locator") and _is_specific_locator(str(direct.get("locator") or "")):
        direct["reason"] = "derived_from_evidence_text_anchor"
        return direct
    span_start = _normalize_int(
        (evidence or {}).get("verified_source_span_start")
        if (evidence or {}).get("verified_source_span_start") is not None
        else (evidence or {}).get("source_span_start"),
        default=-1,
    )
    span_end = _normalize_int(
        (evidence or {}).get("verified_source_span_end")
        if (evidence or {}).get("verified_source_span_end") is not None
        else (evidence or {}).get("source_span_end"),
        default=-1,
    )
    quote_id = str((evidence or {}).get("quote_id") or "")
    support_bucket = str(
        (evidence or {}).get("support_source_bucket")
        or (evidence or {}).get("verified_source_bucket")
        or ""
    )
    entries = _quote_bank_entries_for_grounding(state or {})
    best_near: Tuple[int, Dict[str, Any]] = (10**9, {"locator": "", "locator_type": "generic", "locator_confidence": 0.0, "reason": ""})
    for entry in entries:
        entry_locator = str(entry.get("source_locator") or "")
        entry_quote = str(entry.get("raw_quote") or "")
        if _is_specific_locator(entry_locator):
            entry_details = {
                "locator": entry_locator,
                "locator_type": _locator_type_from_anchor(entry_locator),
                "locator_confidence": 0.9,
            }
        else:
            entry_details = _locator_anchor_details_from_text(entry_quote)
        entry_anchor = str(entry_details.get("locator") or "")
        if not entry_anchor or not _is_specific_locator(entry_anchor):
            continue
        entry_start = _normalize_int(entry.get("source_span_start"), default=-1)
        entry_end = _normalize_int(entry.get("source_span_end"), default=-1)
        same_quote = bool(quote_id and str(entry.get("quote_id") or "") == quote_id)
        overlaps = _locator_span_overlap(span_start, span_end, entry_start, entry_end) > 0
        if same_quote or overlaps:
            return {
                "locator": entry_anchor,
                "locator_type": str(entry_details.get("locator_type") or _locator_type_from_anchor(entry_anchor)),
                "locator_confidence": 0.95 if same_quote else 0.9,
                "reason": "derived_from_quote_id" if same_quote else "derived_from_verified_span_overlap",
            }
        if span_start >= 0 and entry_start >= 0:
            distance = min(abs(span_start - entry_start), abs(span_start - entry_end))
            entry_bucket = str(entry.get("source_bucket") or "")
            compatible_bucket = (
                support_bucket in {"table_or_figure", "result_or_experiment", "results"}
                or entry_bucket in {"table_or_figure", "results"}
            )
            if compatible_bucket and distance < best_near[0] and distance <= 650:
                best_near = (
                    distance,
                    {
                        "locator": entry_anchor,
                        "locator_type": str(entry_details.get("locator_type") or _locator_type_from_anchor(entry_anchor)),
                        "locator_confidence": max(0.55, round(0.75 - min(distance, 650) / 2600, 3)),
                        "reason": "derived_from_nearby_quote_bank_anchor",
                    },
                )
    return best_near[1]


def _programmatic_source_locator(state: Dict[str, Any], evidence: Dict[str, Any]) -> str:
    return str(_programmatic_source_locator_details(state or {}, evidence or {}).get("locator") or "")


def _apply_programmatic_source_locator(state: Dict[str, Any], evidence: Dict[str, Any]) -> None:
    details = _programmatic_source_locator_details(state or {}, evidence or {})
    inferred = str(details.get("locator") or "")
    locator_type = str(details.get("locator_type") or "generic")
    locator_confidence = _normalize_float(details.get("locator_confidence"), default=0.0)
    evidence["locator_type"] = locator_type
    evidence["source_locator_type"] = locator_type
    evidence["locator_confidence"] = locator_confidence
    evidence["source_locator_confidence"] = locator_confidence
    if not inferred or not _is_specific_locator(inferred):
        evidence["source_locator_specific"] = _is_specific_locator(str(evidence.get("source_locator") or ""))
        return
    current = str(evidence.get("source_locator") or "")
    if current != inferred:
        evidence.setdefault("source_locator_original", current)
        evidence["source_locator"] = inferred
        evidence["source_locator_programmatic"] = True
        evidence["source_locator_programmatic_reason"] = str(details.get("reason") or "derived_from_verified_quote_or_quote_bank_anchor")
    evidence["source_locator_specific"] = True

def _real_claim_ids_from_state(state: Dict[str, Any]) -> set[str]:
    real_ids: set[str] = set()
    for item in state.get("claims", []) or []:
        claim_id = str(item.get("claim_id", "") or "")
        if not claim_id:
            continue
        if (
            isinstance(item, dict)
            and _is_real_paper_claim_id(claim_id, item.get("claim_kind"))
            and not _claim_gap_should_be_not_assessable(item)
        ):
            real_ids.add(claim_id)
    return real_ids


def _claim_kind_counts(claims: Sequence[Dict[str, Any]]) -> Dict[str, int]:
    counts = {kind: 0 for kind in sorted(CLAIM_KINDS)}
    for item in claims or []:
        if not isinstance(item, dict):
            continue
        kind = _classify_claim_kind(item.get("claim_id"), item.get("claim_kind"))
        counts[kind] = counts.get(kind, 0) + 1
    return counts


def claim_coverage_summary(state: Dict[str, Any]) -> Dict[str, Any]:
    claims = [
        item
        for item in (state or {}).get("claims", []) or []
        if isinstance(item, dict) and str(item.get("claim_id") or "") and not str(item.get("claim_id") or "").startswith("claim-fallback")
    ]
    tag_counts = {tag: 0 for tag in sorted(CLAIM_COVERAGE_TAGS)}
    type_counts = {claim_type: 0 for claim_type in sorted(CLAIM_TYPES)}
    claim_summaries: List[Dict[str, Any]] = []
    for claim in claims:
        claim_text = _normalize_text(claim.get("claim"), max_length=500)
        claim_type = _normalize_text(claim.get("claim_type"), max_length=64).lower()
        if claim_type not in CLAIM_TYPES:
            claim_type = _infer_claim_type(claim, claim_text)
        type_counts[claim_type] = type_counts.get(claim_type, 0) + 1
        tags = _normalize_list_of_strings(claim.get("coverage_tags"), max_items=6, max_length=40)
        tags = [tag.lower() for tag in tags if tag.lower() in CLAIM_COVERAGE_TAGS]
        if not tags:
            tags = _normalize_claim_coverage_tags(claim, claim_text, claim_type)
        for tag in tags:
            tag_counts[tag] = tag_counts.get(tag, 0) + 1
        claim_summaries.append(
            {
                "claim_id": claim.get("claim_id", ""),
                "claim_type": claim_type,
                "coverage_tags": tags[:6],
                "evidence_need": _normalize_text(
                    claim.get("evidence_need"),
                    default=_default_claim_evidence_need(claim_type, tags),
                    max_length=160,
                ),
            }
        )
    missing_core_tags = [
        tag
        for tag in ("method", "empirical")
        if tag_counts.get(tag, 0) <= 0
    ]
    missing_review_tags = list(missing_core_tags)
    if tag_counts.get("limitation", 0) <= 0 and tag_counts.get("scope", 0) <= 0:
        missing_review_tags.append("limitation")
    thin_coverage = len(claims) < 3 or bool(missing_core_tags)
    full_claims_for_kinds = [
        item
        for item in (state or {}).get("claims", []) or []
        if isinstance(item, dict) and str(item.get("claim_id") or "")
    ]
    claim_kind_counts = _claim_kind_counts(full_claims_for_kinds)
    paper_extracted_count = claim_kind_counts.get("paper_extracted", 0)
    non_paper_claim_count = sum(
        value for key, value in claim_kind_counts.items() if key != "paper_extracted"
    )
    return {
        "claim_count": len(claims),
        "claim_type_counts": {key: value for key, value in type_counts.items() if value},
        "coverage_tag_counts": {key: value for key, value in tag_counts.items() if value},
        "missing_core_coverage_tags": missing_core_tags,
        "missing_review_coverage_tags": missing_review_tags,
        "has_method_claim": tag_counts.get("method", 0) > 0,
        "has_empirical_claim": tag_counts.get("empirical", 0) > 0,
        "has_limitation_sensitive_claim": tag_counts.get("limitation", 0) > 0 or tag_counts.get("scope", 0) > 0,
        "has_comparison_claim": tag_counts.get("comparison", 0) > 0,
        "claim_coverage_status": "thin" if thin_coverage else "expanded",
        "claim_coverage_expansion_recommended": thin_coverage,
        "claim_kind_counts": claim_kind_counts,
        "paper_extracted_claim_count": paper_extracted_count,
        "non_paper_claim_count": non_paper_claim_count,
        "claims": claim_summaries[:8],
    }


def _validate_evidence_bindings_for_state(state: Dict[str, Any], evidence_items: Sequence[Dict[str, Any]]) -> List[Dict[str, Any]]:
    real_claim_ids = _real_claim_ids_from_state(state)
    validated: List[Dict[str, Any]] = []
    for evidence in evidence_items:
        item = dict(evidence)
        claim_id = str(item.get("claim_id", "") or "")
        source = str(item.get("source", "") or "")
        binding_status = "bound_real_claim"
        if source == "fallback-extraction":
            binding_status = "fallback_unverified"
        elif not claim_id:
            binding_status = "unbound"
        elif claim_id.startswith("claim-fallback"):
            binding_status = "fallback_bound"
        elif claim_id not in real_claim_ids:
            binding_status = "invalid_claim_id"
        item["binding_status"] = binding_status
        item["support_source_bucket"] = _normalize_text(
            item.get("support_source_bucket") or _evidence_source_bucket(item),
            default="other_or_unspecified",
            max_length=80,
        )
        item["support_quality"] = _normalize_text(
            item.get("support_quality") or _support_quality_label(item),
            default="unspecified_support",
            max_length=80,
        )
        positive_support = item.get("stance") in {"supports", "partially_supports"}
        if binding_status != "bound_real_claim" and item.get("strength") == "strong":
            item["strength"] = "medium" if positive_support else item.get("strength")
            item["support_quality_adjustment"] = "downgraded_unbound_or_fallback_support"
        if binding_status == "fallback_unverified" and item.get("strength") == "strong":
            item["strength"] = "medium"
            item["support_quality_adjustment"] = "downgraded_fallback_support"
        if (
            binding_status == "bound_real_claim"
            and positive_support
            and item.get("strength") == "strong"
            and item.get("support_source_bucket") == "abstract"
        ):
            item["strength"] = "medium"
            item["support_quality"] = "abstract_claim_support"
            item["support_quality_adjustment"] = "downgraded_abstract_only_support"
        validated.append(item)
    return validated


_CONTEXT_LIMITATION_FLAW_TERMS = (
    "provided excerpt",
    "provided abstract excerpt",
    "provided text",
    "excerpt",
    "abstract cuts off",
    "abstract ends abruptly",
    "abstract ends mid-sentence",
    "abstract is truncated",
    "abstract truncated",
    "truncated abstract",
    "truncated excerpt",
    "truncated evidence",
    "truncated text",
    "evidence is truncated",
    "evidence text is truncated",
    "evidence truncated",
    "text is truncated",
    "truncated paper",
    "cuts off mid-sentence",
    "ends mid-sentence",
    "cut off",
    "incomplete abstract prevents",
    "abstract truncation",
    "incomplete abstract truncation",
    "incomplete abstract verification",
    "incomplete paper text",
    "missing abstract details",
    "explicit excerpt support",
    "excerpt support",
    "full extraction",
    "full text",
    "in the abstract",
)
_GENERIC_LACK_SUPPORT_PATTERN = re.compile(
    r"\b(?:lack(?:s|ing)?|missing|insufficient|unsubstantiated|unverified|unverifiable|unsupported)\b.{0,90}\b(?:empirical|quantitative|experimental|validation|metrics?|scores?|numbers?|benchmark|baseline|ablation|evidence|results?|evaluation|performance)\b"
    r"|\b(?:no|without)\s+(?:specific\s+|concrete\s+|clear\s+|explicit\s+|sufficient\s+)?(?:empirical|quantitative|experimental|validation|metrics?|scores?|numbers?|benchmark|baseline|ablation|evidence|results?|evaluation|performance)\b",
    re.IGNORECASE,
)


def _combined_flaw_text(title: str, description: str, source: str = "") -> str:
    return f"{title} {description} {source}".lower()


def _is_context_limitation_flaw_text(text: str) -> bool:
    lowered = str(text or "").lower()
    return any(term in lowered for term in _CONTEXT_LIMITATION_FLAW_TERMS)


def _is_schema_or_meta_artifact_flaw(flaw_id: str, text: str) -> bool:
    lowered = str(text or "").lower()
    return (
        flaw_id.startswith("flaw-fallback")
        or "\"flaw_candidates\"" in lowered
        or lowered.strip().startswith("{")
        or "the user wants me" in lowered
        or "raw output" in lowered
        or "valid json" in lowered
        or "parse failure" in lowered
        or "schema" in lowered
        or _is_context_limitation_flaw_text(lowered)
        or "evidence map" in lowered
        or "non-existent evidence" in lowered
        or "marked supported" in lowered
        or "marked as supported" in lowered
        or "dialogue confirms" in lowered
    )


def _context_limitation_question_from_flaw_item(item: Any, fallback_index: int) -> Optional[Dict[str, Any]]:
    if not isinstance(item, dict):
        return None
    title = _normalize_text(item.get("title") or item.get("flaw"), max_length=160)
    description = _normalize_text(item.get("description"), max_length=600)
    source = _normalize_text(item.get("source"), max_length=80)
    text = _combined_flaw_text(title, description, source)
    if not _is_context_limitation_flaw_text(text):
        return None
    seed = title or description or f"context-limitation-{fallback_index}"
    return {
        "question_id": _slugify("question", f"assessment-limitation-{seed}", fallback_index),
        "question": "Assessment limitation: this critique was not grounded as a paper defect; verify it with method, result, table, or figure evidence before treating it as a weakness.",
        "status": "open",
        "related_claim_ids": _normalize_list_of_strings(item.get("related_claim_ids"), max_items=6, max_length=80),
    }


def _normalize_flaw_item(item: Any, fallback_index: int) -> Optional[Dict[str, Any]]:
    if not isinstance(item, dict):
        return None
    title = _normalize_text(item.get("title") or item.get("flaw"), max_length=160)
    description = _normalize_text(item.get("description"), max_length=600)
    if not title and not description:
        return None
    seed = title or description
    flaw_id = _normalize_text(item.get("flaw_id"), max_length=80) or _slugify("flaw", seed, fallback_index)
    source = _normalize_text(item.get("source"), max_length=80)
    grounding_status = _normalize_text(item.get("grounding_status"), max_length=80)
    severity = _normalize_choice(item.get("severity"), FLAW_SEVERITY, "major")
    status = _normalize_choice(item.get("status"), FLAW_STATUS, "candidate")
    confidence = _normalize_float(item.get("confidence"), default=0.5)
    text = _combined_flaw_text(title, description, source)
    is_schema_or_meta_artifact = _is_schema_or_meta_artifact_flaw(flaw_id, text)
    if is_schema_or_meta_artifact:
        return None
    is_fallback_or_meta = source in {"fallback", "fallback-extraction", "system_meta"}
    if is_fallback_or_meta:
        source = source or "fallback-extraction"
        grounding_status = grounding_status or "fallback_unverified"
        severity = "minor"
        status = "downgraded"
        confidence = min(confidence, 0.25)
    evidence_ids = _normalize_list_of_strings(item.get("evidence_ids"), max_items=6, max_length=80)
    raw_negative_ids = _normalize_list_of_strings(
        item.get("negative_evidence_ids")
        or item.get("hard_negative_evidence_ids")
        or item.get("contradicting_evidence_ids"),
        max_items=6,
        max_length=80,
    )
    # ``negative_evidence_ids`` is the explicit hard-negative anchor for the
    # flaw (evidence that contradicts/refutes/weakens the related claim, or
    # evidence demonstrating a missing required artifact).  We keep it as a
    # subset of ``evidence_ids`` so legacy consumers that only read
    # ``evidence_ids`` still see the same anchor list, while the renderer can
    # ask ``_flaw_has_negative_grounding`` to require an explicit anchor for
    # *Grounded paper weaknesses*.
    negative_evidence_ids: List[str] = []
    if raw_negative_ids:
        negative_evidence_ids = [eid for eid in raw_negative_ids if eid]
        for eid in negative_evidence_ids:
            if eid not in evidence_ids:
                evidence_ids.append(eid)
        if len(evidence_ids) > 6:
            evidence_ids = evidence_ids[:6]
    normalized = {
        "flaw_id": flaw_id,
        "title": title or description[:120],
        "description": description or title,
        "severity": severity,
        "status": status,
        "related_claim_ids": _normalize_list_of_strings(item.get("related_claim_ids"), max_items=6, max_length=80),
        "evidence_ids": evidence_ids,
        "confidence": confidence,
    }
    if negative_evidence_ids:
        normalized["negative_evidence_ids"] = negative_evidence_ids
    if source:
        normalized["source"] = source
    if grounding_status:
        normalized["grounding_status"] = grounding_status
    weakness_type = _normalize_text(item.get("weakness_type") or item.get("flaw_type"), max_length=80)
    if weakness_type:
        normalized["weakness_type"] = weakness_type
    required_evidence_type = _normalize_text(item.get("required_evidence_type"), max_length=80)
    if required_evidence_type:
        normalized["required_evidence_type"] = required_evidence_type
    criterion = _normalize_text(item.get("criterion") or item.get("review_criterion"), max_length=80)
    if criterion:
        normalized["criterion"] = criterion
    source_stage = _normalize_text(item.get("source_stage"), max_length=80)
    if source_stage:
        normalized["source_stage"] = source_stage
    paper_side_rationale = _normalize_text(item.get("paper_side_rationale"), max_length=360)
    if paper_side_rationale:
        normalized["paper_side_rationale"] = paper_side_rationale
    negative_evidence_type = _normalize_text(item.get("negative_evidence_type"), max_length=80)
    if negative_evidence_type:
        normalized["negative_evidence_type"] = negative_evidence_type
    if is_fallback_or_meta:
        normalized["hygiene_status_reason"] = "fallback_or_meta_flaw_not_paper_defect"
    return normalized


def _normalize_questions(value: Any) -> List[Dict[str, Any]]:
    if value is None:
        return []
    if not isinstance(value, list):
        value = [value]
    results = []
    seen = set()
    for idx, item in enumerate(value, start=1):
        normalized = _normalize_question_item(item, idx)
        if normalized is None:
            continue
        key = (normalized["question_id"], normalized["question"].lower())
        if key in seen:
            continue
        seen.add(key)
        results.append(normalized)
        if len(results) >= 10:
            break
    return results


def _sanitize_conflict_excerpt(text: Any, max_length: int = 96) -> str:
    value = str(text or "")
    value = value.replace("<think>", " ").replace("</think>", " ")
    value = value.replace("<json>", " ").replace("</json>", " ")
    value = " ".join(value.split())
    if len(value) <= max_length:
        return value
    return value[: max(0, max_length - 3)].rstrip() + "..."


def _normalize_conflicts(value: Any) -> List[Dict[str, Any]]:
    if value is None:
        return []
    if not isinstance(value, list):
        value = [value]
    results = []
    seen = set()
    for idx, item in enumerate(value, start=1):
        normalized = _normalize_conflict_item(item, idx)
        if normalized is None:
            continue
        key = (
            normalized["note"].lower(),
            normalized.get("claim_id", ""),
            normalized.get("evidence_id", ""),
            normalized.get("flaw_id", ""),
        )
        if key in seen:
            continue
        seen.add(key)
        results.append(normalized)
        if len(results) >= 12:
            break
    return results


def _append_revision_event(
    revisions: List[Dict[str, Any]],
    entity_type: str,
    entity_id: str,
    field: str,
    before: Any,
    after: Any,
    reason: str = "incoming_update",
) -> None:
    if before == after:
        return
    revisions.append(
        {
            "event_id": _slugify("revision", f"{entity_type}-{entity_id}-{field}-{len(revisions) + 1}", len(revisions) + 1),
            "entity_type": entity_type,
            "entity_id": entity_id,
            "field": field,
            "before": copy.deepcopy(before),
            "after": copy.deepcopy(after),
            "reason": reason,
        }
    )


def _coerce_status_transition(entity_type: str, entity_id: str, before: Any, proposed: Any) -> tuple[Any, Optional[Dict[str, Any]]]:
    if before in (None, "") or before == proposed:
        return proposed, None

    transition_sets = {
        "claim": CLAIM_STATUS_TRANSITIONS,
        "flaw": FLAW_STATUS_TRANSITIONS,
        "unresolved_question": QUESTION_STATUS_TRANSITIONS,
    }
    allowed = transition_sets.get(entity_type, {}).get(before, {before, proposed})
    if proposed in allowed:
        return proposed, None

    return before, {
        "conflict_id": _slugify("conflict", f"{entity_type}-{entity_id}-lifecycle-{before}-{proposed}", 1),
        "note": f"Ignored unsupported lifecycle transition for {entity_type} {entity_id}: {before} -> {proposed}.",
        "claim_id": entity_id if entity_type == "claim" else "",
        "evidence_id": "",
        "flaw_id": entity_id if entity_type == "flaw" else "",
        "conflict_type": "lifecycle_guard",
    }


def _merge_items_with_revisions(
    existing: List[Dict[str, Any]],
    incoming: List[Dict[str, Any]],
    key: str,
    entity_type: str,
    tracked_fields: Iterable[str],
    max_items: int,
) -> tuple[List[Dict[str, Any]], List[Dict[str, Any]], List[Dict[str, Any]]]:
    merged = copy.deepcopy(existing)
    index = {item[key]: idx for idx, item in enumerate(merged) if key in item}
    revisions: List[Dict[str, Any]] = []
    lifecycle_conflicts: List[Dict[str, Any]] = []
    for item in incoming:
        item_key = item[key]
        if item_key in index:
            current = merged[index[item_key]]
            updated = copy.deepcopy(item)
            if entity_type == "evidence":
                for lifecycle_field in ("initial_strength", "initial_stance"):
                    if current.get(lifecycle_field):
                        updated[lifecycle_field] = current.get(lifecycle_field)
            if "status" in tracked_fields and "status" in updated:
                coerced_status, lifecycle_note = _coerce_status_transition(entity_type, item_key, current.get("status"), updated.get("status"))
                updated["status"] = coerced_status
                if lifecycle_note is not None:
                    lifecycle_conflicts.append(lifecycle_note)
            for field in tracked_fields:
                old_value = current.get(field)
                new_value = updated.get(field, old_value)
                if old_value != new_value:
                    reason = "incoming_status_update" if field == "status" else "incoming_update"
                    _append_revision_event(revisions, entity_type, item_key, field, old_value, new_value, reason=reason)
            current.update(updated)
        else:
            merged.append(copy.deepcopy(item))
            index[item_key] = len(merged) - 1
    return merged[:max_items], revisions, lifecycle_conflicts


def _evidence_retention_score(item: Dict[str, Any]) -> int:
    claim_id = str(item.get("claim_id") or "")
    strength = str(item.get("strength") or "").lower()
    stance = str(item.get("stance") or "").lower()
    source = str(item.get("source") or "").lower()
    binding_status = str(item.get("binding_status") or "").lower()
    support_bucket = str(item.get("support_source_bucket") or "").lower()
    support_quality = str(item.get("support_quality") or "").lower()
    evidence_text = str(item.get("evidence") or "").lower()
    combined_text = " ".join([source, support_bucket, support_quality, evidence_text])

    score = 0
    if claim_id and not claim_id.startswith("claim-fallback"):
        score += 100
    else:
        score -= 120
    if binding_status == "bound_real_claim":
        score += 60
    elif binding_status in {"fallback_bound", "fallback_unverified", "unbound"}:
        score -= 80
    if strength == "strong":
        score += 70
    elif strength == "medium":
        score += 25
    elif strength == "weak":
        score += 5
    if stance in {"supports", "support", "partially_supports", "corroborates"}:
        score += 30
    elif stance == "contradicts":
        score += 25
    if any(token in combined_text for token in ("table", "figure", "ablation", "experiment", "evaluation", "result", "baseline", "dataset", "metric")):
        score += 35
    elif any(token in combined_text for token in ("method", "approach", "framework", "model", "algorithm")):
        score += 25
    elif "abstract" in combined_text:
        score += 5
    if source == "fallback-extraction":
        score -= 60
    return score


def _retain_evidence_items(items: List[Dict[str, Any]], max_items: int = 12) -> List[Dict[str, Any]]:
    if len(items) <= max_items:
        return items
    indexed = list(enumerate(items))
    ranked = sorted(indexed, key=lambda pair: (-_evidence_retention_score(pair[1]), pair[0]))
    selected_indices = {idx for idx, _ in ranked[:max_items]}
    return [item for idx, item in indexed if idx in selected_indices]


def _evidence_signature(item: Dict[str, Any]) -> tuple[str, str, str, str, str, str]:
    return (
        _normalize_text(item.get("claim_id"), max_length=80).lower(),
        _normalize_text(item.get("evidence"), max_length=600).lower(),
        _normalize_text(item.get("source"), max_length=120).lower(),
        _normalize_text(item.get("strength"), max_length=40).lower(),
        _normalize_text(item.get("stance"), max_length=40).lower(),
        _normalize_text(item.get("binding_status"), max_length=80).lower(),
    )


def _next_evidence_id(used_ids: set[str]) -> str:
    max_numeric_id = 0
    for evidence_id in used_ids:
        match = re.fullmatch(r"evidence-(\d+)", str(evidence_id or ""))
        if match:
            max_numeric_id = max(max_numeric_id, int(match.group(1)))
    candidate_index = max_numeric_id + 1
    while True:
        candidate = f"evidence-{candidate_index}"
        if candidate not in used_ids:
            return candidate
        candidate_index += 1


def _preserve_colliding_evidence_ids(
    existing: List[Dict[str, Any]],
    incoming: List[Dict[str, Any]],
) -> tuple[List[Dict[str, Any]], Dict[str, str], int]:
    existing_signatures = {
        str(item.get("evidence_id") or ""): _evidence_signature(item)
        for item in existing
        if item.get("evidence_id")
    }
    used_ids = {str(item.get("evidence_id") or "") for item in existing if item.get("evidence_id")}
    incoming_signatures: Dict[str, tuple[str, str, str, str, str, str]] = {}
    collision_aliases: Dict[tuple[str, tuple[str, str, str, str, str, str]], str] = {}
    renamed_by_original: Dict[str, set[str]] = {}
    rewritten: List[Dict[str, Any]] = []
    collision_count = 0

    for evidence in incoming:
        item = copy.deepcopy(evidence)
        evidence_id = str(item.get("evidence_id") or "")
        signature = _evidence_signature(item)
        existing_signature = existing_signatures.get(evidence_id)
        incoming_signature = incoming_signatures.get(evidence_id)
        material_collision = (
            bool(evidence_id)
            and (
                (existing_signature is not None and existing_signature != signature)
                or (incoming_signature is not None and incoming_signature != signature)
            )
        )
        if material_collision:
            alias_key = (evidence_id, signature)
            new_id = collision_aliases.get(alias_key)
            if new_id is None:
                new_id = _next_evidence_id(used_ids)
                collision_aliases[alias_key] = new_id
                used_ids.add(new_id)
                collision_count += 1
            item["original_evidence_id"] = evidence_id
            item["evidence_id"] = new_id
            item["evidence_id_collision_preserved"] = True
            item["evidence_id_collision_reason"] = "materially_different_same_evidence_id"
            renamed_by_original.setdefault(evidence_id, set()).add(new_id)
            evidence_id = new_id
        elif evidence_id:
            used_ids.add(evidence_id)
            item["evidence_id_collision_preserved"] = bool(item.get("evidence_id_collision_preserved"))

        if evidence_id:
            incoming_signatures[evidence_id] = _evidence_signature(item)
        rewritten.append(item)

    unambiguous_renames = {
        original_id: next(iter(new_ids))
        for original_id, new_ids in renamed_by_original.items()
        if len(new_ids) == 1
    }
    return rewritten, unambiguous_renames, collision_count


def _rewrite_evidence_references_for_renamed_ids(payload: Dict[str, Any], rename_map: Dict[str, str]) -> None:
    if not rename_map:
        return

    def rewrite_id(value: Any) -> Any:
        value_str = str(value or "")
        return rename_map.get(value_str, value)

    def rewrite_list(values: Any) -> List[str]:
        # P0-5: synthetic recovery markers must not survive a rename pass —
        # strip them so claims/recovery patches never reference them.
        return _strip_synthetic_recovery_markers(
            [str(rewrite_id(value)) for value in _normalize_list_of_strings(values, max_items=12, max_length=80)]
        )

    for claim in payload.get("claims", []) or []:
        if isinstance(claim, dict):
            claim["supporting_evidence_ids"] = rewrite_list(claim.get("supporting_evidence_ids", []))
    for flaw in payload.get("flaw_candidates", []) or []:
        if isinstance(flaw, dict):
            flaw["evidence_ids"] = rewrite_list(flaw.get("evidence_ids", []))
    for conflict in payload.get("conflict_notes", []) or []:
        if isinstance(conflict, dict) and conflict.get("evidence_id"):
            conflict["evidence_id"] = rewrite_id(conflict.get("evidence_id"))
    for key in ("target_evidence_ids", "supporting_evidence_ids"):
        if key in payload:
            payload[key] = rewrite_list(payload.get(key, []))


def _merge_question_items(
    existing: List[Dict[str, Any]],
    incoming: List[Dict[str, Any]],
) -> tuple[List[Dict[str, Any]], List[Dict[str, Any]], List[Dict[str, Any]]]:
    merged = copy.deepcopy(existing)
    by_id = {item["question_id"]: idx for idx, item in enumerate(merged) if "question_id" in item}
    by_text = {item.get("question", "").lower(): idx for idx, item in enumerate(merged) if item.get("question")}
    revisions: List[Dict[str, Any]] = []
    lifecycle_conflicts: List[Dict[str, Any]] = []
    for item in incoming:
        idx = by_id.get(item["question_id"])
        if idx is None:
            idx = by_text.get(item["question"].lower())
        if idx is None:
            merged.append(copy.deepcopy(item))
            idx = len(merged) - 1
            by_id[item["question_id"]] = idx
            by_text[item["question"].lower()] = idx
            continue
        current = merged[idx]
        updated = copy.deepcopy(item)
        coerced_status, lifecycle_note = _coerce_status_transition(
            "unresolved_question",
            current["question_id"],
            current.get("status"),
            updated.get("status"),
        )
        updated["status"] = coerced_status
        if lifecycle_note is not None:
            lifecycle_conflicts.append(lifecycle_note)
        for field in ("question", "status", "related_claim_ids"):
            old_value = current.get(field)
            new_value = updated.get(field, old_value)
            if old_value != new_value:
                reason = "incoming_status_update" if field == "status" else "incoming_update"
                _append_revision_event(revisions, "unresolved_question", current["question_id"], field, old_value, new_value, reason=reason)
        current.update(updated)
    return merged[:10], revisions, lifecycle_conflicts


def _merge_conflict_notes(
    existing: List[Dict[str, Any]],
    incoming: List[Dict[str, Any]],
    max_items: int = 12,
) -> tuple[List[Dict[str, Any]], List[Dict[str, Any]]]:
    merged = copy.deepcopy(existing)
    seen = {
        (
            item.get("note", "").lower(),
            item.get("claim_id", ""),
            item.get("evidence_id", ""),
            item.get("flaw_id", ""),
        )
        for item in merged
    }
    added: List[Dict[str, Any]] = []
    for item in incoming:
        key = (
            item.get("note", "").lower(),
            item.get("claim_id", ""),
            item.get("evidence_id", ""),
            item.get("flaw_id", ""),
        )
        if key in seen:
            continue
        seen.add(key)
        copied = copy.deepcopy(item)
        merged.append(copied)
        added.append(copied)
    return merged[:max_items], added[:max_items]


def _collect_claim_evidence(state: Dict[str, Any], claim_id: str) -> List[Dict[str, Any]]:
    return [item for item in state.get("evidence_map", []) if item.get("claim_id") == claim_id]


def _real_strong_support_counts(state: Dict[str, Any]) -> Dict[str, int]:
    real_claim_ids = _real_claim_ids_from_state(state)
    counts: Dict[str, int] = {}
    for item in state.get("evidence_map", []) or []:
        claim_id = str(item.get("claim_id") or "")
        if (
            claim_id in real_claim_ids
            and item.get("strength") == "strong"
            and item.get("stance") in {"supports", "partially_supports"}
            and str(item.get("source") or "") != "fallback-extraction"
            and str(item.get("binding_status") or "bound_real_claim") in {"", "unchecked", "bound_real_claim"}
        ):
            counts[claim_id] = counts.get(claim_id, 0) + 1
    return counts


def _generic_lack_support_flaw_conflicts_with_support(flaw: Dict[str, Any], support_counts: Dict[str, int]) -> bool:
    if flaw.get("status") in {"downgraded", "retracted"}:
        return False
    if flaw.get("evidence_ids"):
        return False
    text = " ".join(str(flaw.get(key) or "") for key in ("title", "description")).lower()
    if "anchored evidence" in text or "grounded evidence" in text:
        return False
    if not _GENERIC_LACK_SUPPORT_PATTERN.search(text):
        return False
    related_claim_ids = [str(item) for item in flaw.get("related_claim_ids", []) or [] if str(item)]
    return any(support_counts.get(claim_id, 0) > 0 for claim_id in related_claim_ids)


def _claim_gap_should_be_not_assessable(claim: Dict[str, Any]) -> bool:
    """Route low-provenance claim gaps away from paper-negative burden.

    Small-model claim salvage and context-synthesized claims are useful
    diagnostic coverage scaffolds, but an unsupported scaffold claim should not
    become an open paper flaw.  The claim remains in ReviewState for follow-up;
    its lack of support is represented as an assessment limitation instead of
    an actionable evidence gap.
    """
    claim_id = str(claim.get("claim_id") or "").strip().lower()
    origin_kind = str(claim.get("claim_origin_kind") or "").strip().lower()
    canonicalized_raw_salvage = bool(claim.get("paper_claim_canonicalized_from_raw_salvage"))
    origin = " ".join(
        str(claim.get(key) or "")
        for key in ("claim_origin", "claim_source", "source_stage", "provenance")
    ).lower()
    return (
        claim_id.startswith("claim-paper-context-")
        or claim_id.startswith("claim-paper-fallback-")
        or (
            origin_kind in {"context_synthesized", "raw_salvaged_claim_agent_output"}
            and not canonicalized_raw_salvage
        )
        or "context_derived" in origin
        or ("raw_salvage" in origin and not canonicalized_raw_salvage)
        or ("malformed_claim_agent_output" in origin and not canonicalized_raw_salvage)
    )


def _refresh_state_consistency(state: Dict[str, Any]) -> tuple[Dict[str, Any], List[Dict[str, Any]], List[Dict[str, Any]]]:
    refreshed = copy.deepcopy(state)
    derived_revisions: List[Dict[str, Any]] = []
    derived_conflicts: List[Dict[str, Any]] = []
    derived_gaps = _normalize_evidence_gaps(refreshed.get("evidence_gaps", []), max_items=20)
    hypotheses = list(refreshed.get("current_hypotheses", []))
    transient_status_locks = dict(refreshed.get("_transient_status_locks", {}) or {})
    persistent_status_guards = dict(refreshed.get("_persistent_status_guards", {}) or {})

    claims = refreshed.get("claims", [])
    flaws = refreshed.get("flaw_candidates", [])
    for claim in claims:
        claim_id = claim.get("claim_id", "")
        lock_status = transient_status_locks.get(_status_lock_key("claim", claim_id))
        guarded_status = persistent_status_guards.get(_status_lock_key("claim", claim_id))
        linked_evidence = _collect_claim_evidence(refreshed, claim_id)
        supporting = [item for item in linked_evidence if item.get("stance") in {"supports", "partially_supports"}]
        contradicting = [item for item in linked_evidence if item.get("stance") == "contradicts"]
        positive_ids = [item.get("evidence_id", "") for item in supporting if item.get("evidence_id")]
        merged_support_ids = _strip_synthetic_recovery_markers(
            _normalize_list_of_strings(
                list(claim.get("supporting_evidence_ids", [])) + positive_ids,
                max_items=6,
                max_length=80,
            )
        )
        if claim.get("supporting_evidence_ids", []) != merged_support_ids:
            _append_revision_event(
                derived_revisions,
                "claim",
                claim_id,
                "supporting_evidence_ids",
                claim.get("supporting_evidence_ids", []),
                merged_support_ids,
                reason="evidence_sync",
            )
            claim["supporting_evidence_ids"] = merged_support_ids

        current_status = claim.get("status", "uncertain")
        desired_status = current_status
        strong_support = any(item.get("strength") == "strong" for item in supporting)
        if supporting and contradicting:
            desired_status = "partially_supported"
            note = {
                "conflict_id": _slugify("conflict", f"{claim_id}-mixed-evidence-{len(derived_conflicts)+1}", len(derived_conflicts) + 1),
                "note": f"Claim {claim_id} now has mixed supporting and contradictory evidence.",
                "claim_id": claim_id,
                "evidence_id": contradicting[0].get("evidence_id", ""),
                "flaw_id": "",
                "conflict_type": "mixed_evidence",
            }
            derived_conflicts.append(note)
            hypothesis = f"Claim {claim_id} may only be partially supported because the evidence is mixed."
            if hypothesis not in hypotheses:
                hypotheses.append(hypothesis)
            derived_gaps = _set_evidence_gap_status(
                derived_gaps,
                claim_id=claim_id,
                status="resolved",
                evidence_id=positive_ids[0] if positive_ids else "",
                resolution="supporting_evidence_bound",
            )
        elif contradicting:
            note = {
                "conflict_id": _slugify("conflict", f"{claim_id}-derived-{len(derived_conflicts)+1}", len(derived_conflicts) + 1),
                "note": f"Claim {claim_id} is challenged by contradictory evidence and should be rechecked.",
                "claim_id": claim_id,
                "evidence_id": contradicting[0].get("evidence_id", ""),
                "flaw_id": "",
                "conflict_type": "evidence_conflict",
            }
            derived_conflicts.append(note)
            hypothesis = f"Claim {claim_id} may be overstated because conflicting evidence has appeared."
            if hypothesis not in hypotheses:
                hypotheses.append(hypothesis)
            derived_gaps = _set_evidence_gap_status(
                derived_gaps,
                claim_id=claim_id,
                status="converted",
                evidence_id=contradicting[0].get("evidence_id", ""),
                resolution="converted_to_evidence_conflict",
            )
            if current_status == "supported":
                desired_status = "uncertain"
        elif supporting:
            desired_status = "supported" if strong_support else "partially_supported"
            derived_gaps = _set_evidence_gap_status(
                derived_gaps,
                claim_id=claim_id,
                status="resolved",
                evidence_id=positive_ids[0] if positive_ids else "",
                resolution="supporting_evidence_bound",
            )
        else:
            gap_text = f"Claim {claim_id or claim.get('claim', '')[:40]} lacks grounded supporting evidence."
            gap_status = "not_assessable" if _claim_gap_should_be_not_assessable(claim) else "open"
            gap_resolution = (
                "diagnostic_or_salvaged_claim_without_verified_support"
                if gap_status == "not_assessable"
                else ""
            )
            derived_gaps = _merge_evidence_gaps(
                derived_gaps,
                [
                    {
                        "gap": gap_text,
                        "claim_id": claim_id,
                        "status": gap_status,
                        "source": "state_consistency",
                        "resolution": gap_resolution,
                    }
                ],
                max_items=20,
            )
            if current_status == "supported":
                desired_status = "uncertain"

        if guarded_status:
            desired_status = guarded_status
        if lock_status:
            desired_status = lock_status

        if desired_status != current_status:
            coerced_status, lifecycle_note = _coerce_status_transition("claim", claim_id, current_status, desired_status)
            if lifecycle_note is not None:
                derived_conflicts.append(lifecycle_note)
            if coerced_status != current_status:
                _append_revision_event(
                    derived_revisions,
                    "claim",
                    claim_id,
                    "status",
                    current_status,
                    coerced_status,
                    reason="consistency_reconciliation",
                )
                claim["status"] = coerced_status

    support_counts = _real_strong_support_counts(refreshed)
    for question in refreshed.get("unresolved_questions", []) or []:
        if not isinstance(question, dict):
            continue
        if str(question.get("status") or "open") != "open":
            continue
        related_claim_ids = [str(item) for item in (question.get("related_claim_ids") or []) if str(item)]
        if not any(support_counts.get(claim_id, 0) > 0 for claim_id in related_claim_ids):
            continue
        question_text = str(question.get("question") or "")
        if not _GENERIC_LACK_SUPPORT_PATTERN.search(question_text):
            continue
        old_status = question.get("status", "open")
        question["status"] = "resolved"
        question["resolved_by"] = "verified_real_claim_support"
        question["hygiene_status_reason"] = "state_consistency_resolved_by_real_claim_support"
        question_id = str(question.get("question_id") or question.get("question") or "unresolved_question")
        _append_revision_event(
            derived_revisions,
            "unresolved_question",
            question_id,
            "status",
            old_status,
            "resolved",
            reason="state_consistency_resolved_by_real_claim_support",
        )

    for flaw in flaws:
        flaw_id = flaw.get("flaw_id", "")
        if flaw.get("status") == "confirmed" and not flaw.get("evidence_ids"):
            _append_revision_event(
                derived_revisions,
                "flaw",
                flaw_id,
                "status",
                "confirmed",
                "candidate",
                reason="missing_anchor_evidence",
            )
            flaw["status"] = "candidate"
            derived_conflicts.append(
                {
                    "conflict_id": _slugify("conflict", f"{flaw_id}-missing-evidence-{len(derived_conflicts)+1}", len(derived_conflicts) + 1),
                    "note": f"Flaw {flaw_id} was downgraded because it lacks anchored evidence.",
                    "claim_id": (flaw.get("related_claim_ids") or [""])[0],
                    "evidence_id": "",
                    "flaw_id": flaw_id,
                    "conflict_type": "flaw_anchor_gap",
                }
            )
        if _generic_lack_support_flaw_conflicts_with_support(flaw, support_counts):
            old_status = flaw.get("status", "candidate")
            flaw["status"] = "downgraded"
            flaw["hygiene_status_reason"] = "evidence_aware_lack_flaw_conflicts_with_strong_support"
            _append_revision_event(
                derived_revisions,
                "flaw",
                flaw_id,
                "status",
                old_status,
                "downgraded",
                reason="evidence_aware_support_conflict",
            )
        if (
            flaw.get("status") in {"candidate", "confirmed"}
            and not _flaw_has_negative_grounding(flaw, refreshed)
            and _flaw_only_cites_supports(flaw, refreshed)
        ):
            old_status = flaw.get("status", "candidate")
            flaw["status"] = "downgraded"
            flaw["hygiene_status_reason"] = "support_only_flaw_lacks_verified_negative_evidence"
            _append_revision_event(
                derived_revisions,
                "flaw",
                flaw_id,
                "status",
                old_status,
                "downgraded",
                reason="support_only_flaw_without_verified_negative_grounding",
            )
            derived_conflicts.append(
                {
                    "conflict_id": _slugify("conflict", f"{flaw_id}-support-only-flaw-{len(derived_conflicts)+1}", len(derived_conflicts) + 1),
                    "note": f"Flaw {flaw_id} was downgraded because it only cites positive support evidence and lacks verified negative grounding.",
                    "claim_id": (flaw.get("related_claim_ids") or [""])[0],
                    "evidence_id": (flaw.get("evidence_ids") or [""])[0],
                    "flaw_id": flaw_id,
                    "conflict_type": "support_only_flaw_without_negative_grounding",
                }
            )
        if flaw.get("status") in {"candidate", "confirmed"} and not flaw.get("evidence_ids"):
            gap_text = f"Flaw {flaw_id or flaw.get('title', '')[:40]} lacks anchored evidence."
            derived_gaps = _merge_evidence_gaps(
                derived_gaps,
                [
                    {
                        "gap": gap_text,
                        "claim_id": (flaw.get("related_claim_ids") or [""])[0],
                        "flaw_id": flaw_id,
                        "status": "open",
                        "source": "state_consistency",
                    }
                ],
                max_items=20,
            )
        elif flaw.get("status") in {"candidate", "confirmed"} and flaw.get("evidence_ids"):
            derived_gaps = _set_evidence_gap_status(
                derived_gaps,
                flaw_id=flaw_id,
                status="resolved",
                evidence_id=(flaw.get("evidence_ids") or [""])[0],
                resolution="anchored_flaw_evidence_bound",
            )
        if flaw.get("status") in {"retracted", "downgraded"}:
            derived_gaps = _set_evidence_gap_status(
                derived_gaps,
                flaw_id=flaw_id,
                status="superseded",
                evidence_id=(flaw.get("evidence_ids") or [""])[0],
                resolution="flaw_inactive",
            )
            hypothesis = f"Flaw {flaw.get('flaw_id', '')} no longer provides a stable rejection signal."
            if hypothesis not in hypotheses:
                hypotheses.append(hypothesis)

    refreshed["evidence_gaps"] = _normalize_evidence_gaps(derived_gaps, max_items=10)
    refreshed["current_hypotheses"] = _normalize_list_of_strings(hypotheses, max_items=8, max_length=240)
    refreshed["conflict_notes"], added_conflicts = _merge_conflict_notes(
        refreshed.get("conflict_notes", []),
        _normalize_conflicts(derived_conflicts),
        max_items=12,
    )
    return refreshed, derived_revisions, added_conflicts


def _open_unresolved_questions(state: Dict[str, Any]) -> List[str]:
    results = []
    for item in state.get("unresolved_questions", []):
        if isinstance(item, dict):
            if item.get("status", "open") == "open":
                question_text = _normalize_text(item.get("question"), max_length=300)
                if question_text:
                    results.append(question_text)
        else:
            text = _normalize_text(item, max_length=300)
            if text:
                results.append(text)
    return results


